    # 提取关键符号：n_x, n_y, L_x, L_y
    # 从上下文或预测中查找类似公式或数值

    # 匹配公式模式：tan(theta) = (n_y * L_y) / (n_x * L_x)
    pattern = r'tan\?\(\s*theta\s*\)\s*=\s*\(\s*n_y\s*\*\s*L_y\s*\)\s*/\s*\(\s*n_x\s*\*\s*L_x\s*\)'
    if re.search(pattern, question + prediction + context, re.IGNORECASE):
        evidence = '公式模式匹配: tan(theta) = (n_y * L_y) / (n_x * L_x)'

    # 尝试提取 n_x, n_y, L_x, L_y 的数值
    num_pattern = r'(?:n_x|n_y|L_x|L_y)\s*=\s*([\d\.]+)'
    matches = re.findall(num_pattern, question + prediction + context)

    if len(matches) < 4:
        message = '未提取到足够参数值'
        return {'result': 'inconclusive', 'message': message, 'evidence': ''}

    try:
        n_x = float(matches[0])
        n_y = float(matches[1])
        L_x = float(matches[2])
        L_y = float(matches[3])

        # 检查是否为有效正数
        if n_x <= 0 or n_y <= 0 or L_x <= 0 or L_y <= 0:
            message = '参数必须为正数'
            return {'result': 'fail', 'message': message, 'evidence': ''}

        # 计算 tan(theta) 的理论值
        tan_theta = (n_y * L_y) / (n_x * L_x)

        # 检查预测中是否包含 tan(theta) 的值
        tan_pattern = r'tan\?\(\s*theta\s*\)\s*=\s*([\d\.]+)'
        tan_match = re.search(tan_pattern, prediction + context, re.IGNORECASE)
        if tan_match:
            pred_tan = float(tan_match.group(1))
            # 允许轻微误差
            if abs(pred_tan - tan_theta) < 1e-6:
                result = 'pass'
                message = 'tan(theta) 值匹配理论计算'
            else:
                result = 'fail'
                message = f'tan(theta) 计算值 {pred_tan:.6f} 与理论值 {tan_theta:.6f} 不符'
        else:
            # 若无 tan(theta) 值，但公式结构存在，视为部分匹配
            result = 'pass'
            message = '公式结构正确，参数完整'

    except Exception as e:
        message = '数值解析失败'
        return {'result': 'inconclusive', 'message': message, 'evidence': ''}

    return {'result': result, 'message': message, 'evidence': evidence}

