    collision_order_keywords = []
    if '先撞' in question:
        parts = question.split('先撞')
        if len(parts) >= 2:
            first = parts[1].split('再撞')[0].strip()
            second = parts[1].split('再撞')[1].strip() if '再撞' in parts[1] else None
            if first and second:
                collision_order_keywords = [first, second]
            elif first:
                collision_order_keywords = [first]

    if not collision_order_keywords:
        return {
            "result": "inconclusive",
            "message": "未检测到碰撞顺序描述",
            "evidence": ""
        }

    # 检查预测中是否按顺序提及边界
    pred_lower = prediction.lower()
    order_found = []
    for boundary in collision_order_keywords:
        if boundary in pred_lower:
            order_found.append(boundary)

    # 检查顺序是否一致
    if len(order_found) != len(collision_order_keywords):
        return {
            "result": "fail",
            "message": "碰撞顺序不完整或缺失",
            "evidence": "" if not collision_order_keywords else collision_order_keywords[0]
        }

    # 检查顺序是否正确
    first_match = pred_lower.find(collision_order_keywords[0].lower())
