# rule_id=exp_393a82f64e5b386a | domain=Mechanics | topic=Kinematics in 1D/2D/3D
def check_exp_393a82f64e5b386a_a51e9d31e05c(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    context = sample.get('context', '')

    # 合并文本用于查找关键信息
    text = (question + ' ' + prediction + ' ' + context).lower()

    # 查找时间间隔 Δt

    delta_t_match = re.search(r'Δt|delta t|time interval|time difference|time gap|t\s*\(\s*\d+\s*\)\s*=\s*(\d+\.?\d*)', text)
    if not delta_t_match:
        return {'result': 'inconclusive', 'message': '未找到时间间隔 Δt', 'evidence': ''}

    try:
        delta_t = float(delta_t_match.group(1))
        if delta_t <= 0:
            return {'result': 'inconclusive', 'message': 'Δt 必须为正数', 'evidence': ''}
    except:
        return {'result': 'inconclusive', 'message': 'Δt 解析失败', 'evidence': ''}

    # 查找高度差 ΔH
    delta_h_match = re.search(r'Δh|delta h|height difference|height gap|difference in height|Δh\s*=\s*(\d+\.?\d*)', text)
    if not delta_h_match:
        return {'result': 'inconclusive', 'message': '未找到高度差 ΔH', 'evidence': ''}

    try:
        delta_h = float(delta_h_match.group(1))
        if delta_h < 0:
            return {'result': 'inconclusive', 'message': 'ΔH 不能为负', 'evidence': ''}
    except:
        return {'result': 'inconclusive', 'message': 'ΔH 解析失败', 'evidence': ''}

    # g 取标准值 9.8 m/s²
    g = 9.8

    # 计算理论 ΔH = 1/8 * g * (Δt)^2
    theoretical_delta_h = (1/8) * g * (delta_t ** 2)

    # 允许 5% 的误差
    tolerance = 0.05
    if abs(delta_h - theoretical_delta_h) <= tolerance * theoretical_delta_h:
        return {
            'result': 'pass',
            'message': f'ΔH = {delta_h:.2f} 符合公式 ΔH = 1/8 * g * (Δt)^2 = {theoretical_delta_h:.2f}',
            'evidence': f'Δt={delta_t}, ΔH={delta_h}'
        }
    else:
        return {
            'result': 'fail',
            'message': f'ΔH = {delta_h:.2f} 与理论值 {theoretical_delta_h:.2f} 不符，误差超过5%。',
            'evidence': f'Δt={delta_t}, ΔH={delta_h}'
        }

