# rule_id=exp_5020bed4341ab142 | domain=Mechanics | topic=Kinematics in 1D/2D/3D
def check_exp_5020bed4341ab142_3d34ea8a5ae3(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否涉及竖直上抛或自由落体的高度差计算
    if '竖直上抛' not in question and '自由落体' not in question and 'vertical throw' not in question and 'free fall' not in question:
        return {'result': 'inconclusive', 'message': '未触发竖直运动场景', 'evidence': ''}

    # 检查是否使用最高点作为参考系
    if '最高点' not in prediction and 'highest point' not in prediction and 'top point' not in prediction:
        return {'result': 'fail', 'message': '未以最高点为参考系', 'evidence': ''}

    # 检查是否使用了对称性公式 h = 1/8 * g * ((Δt_A)^2 - (Δt_B)^2)
    # 提取 Δt_A 和 Δt_B 的符号

    pattern = r'\d*\.?\d*\s*\*\s*\(\s*\(\s*Δt[_\s]*A\s*\)\s*\^\s*2\s*\-\s*\(\s*Δt[_\s]*B\s*\)\s*\^\s*2\s*\)'
    if not re.search(pattern, prediction):
        return {'result': 'fail', 'message': '未使用对称性公式', 'evidence': ''}

    # 检查是否包含 1/8 * g
    if '1/8' not in prediction and '0.125' not in prediction:
        return {'result': 'fail', 'message': '缺少 1/8 或 0.125 系数', 'evidence': ''}

    if 'g' not in prediction and 'gravity' not in prediction:
        return {'result': 'fail', 'message': '缺少重力加速度 g', 'evidence': ''}

    # 检查是否正确表达 h = 1/8 * g * ((Δt_A)^2 - (Δt_B)^2)
    # 简单验证结构
    if not re.search(r'h\s*=\s*1/8\s*\*\s*g\s*\*\s*\(\s*\(\s*Δt[_\s]*A\s*\)\s*\^\s*2\s*\-\s*\(\s*Δt[_\s]*B\s*\)\s*\^\s*2\s*\)', prediction):
        return {'result': 'fail', 'message': '公式结构错误', 'evidence': ''}

    # 检查是否 A 低 B 高，且 h = h_A - h_B
    if 'h_A' in prediction and 'h_B' in prediction and 'h_A - h_B' in prediction:
        pass
    elif 'h_A' in prediction and 'h_B' in prediction and 'h_B - h_A' in prediction:
        return {'result': 'fail', 'message': '高度差符号错误，应为 h_A - h_B', 'evidence': ''}
    else:
        return {'result': 'inconclusive', 'message': '未明确 h_A 与 h_B 的关系', 'evidence': ''}

    return {'result': 'pass', 'message': '符合高度差对称性检查规则', 'evidence': 'h = 1/8 * g * ((Δt_A)^2 - (Δt_B)^2)'}

