# rule_id=exp_727d95c333b57256 | domain=Mechanics | topic=Kinematics in 1D/2D/3D
def check_exp_727d95c333b57256_828b0d6aa046(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '')
    context = sample.get('context', '')
    text = (question + ' ' + prediction + ' ' + context).strip()

    if '接收机无时钟' not in text and '需确定接收时间t' not in text and '三维坐标' not in text:
        return {'result': 'inconclusive', 'message': '未触发规则条件', 'evidence': ''}

    # 检查是否包含光速c和(t-ti)的平方项
    # 期望形式: (x-x_i)^2 + (y-y_i)^2 + (z-z_i)^2 = c^2(t-t_i)^2
    # 禁止出现Δti等额外时间差变量

    # 检查是否包含 c^2(t-t_i)^2 或 c^2*(t-t_i)^2
    c_t_term = 'c^2(t-t_i)^2' in text or 'c^2*(t-t_i)^2' in text
    if not c_t_term:
        return {'result': 'fail', 'message': '未发现c^2(t-t_i)^2项', 'evidence': ''}

    # 检查是否包含其他时间差变量如 Δt_i, Δti, dt_i 等
    time_diff_vars = ['Δt_i', 'Δti', 'dt_i', 'delta_t_i', 'Δt', 'dt', 'delta_t']
    for var in time_diff_vars:
        if var in text:
            return {'result': 'fail', 'message': f'发现非法时间差变量: {var}', 'evidence': var}

    # 检查是否包含 (x-x_i)^2 + (y-y_i)^2 + (z-z_i)^2
    pos_terms = ['(x-x_i)^2', '(y-y_i)^2', '(z-z_i)^2']
    missing_pos = [term for term in pos_terms if term not in text]
    if missing_pos:
        return {'result': 'fail', 'message': f'缺少位置项: {missing_pos}', 'evidence': missing_pos[0]}

    # 检查等号左右结构
    if '=' not in text:
        return {'result': 'fail', 'message': '缺少等号', 'evidence': ''}

    left, right = text.split('=', 1)
    left = left.strip()
    right = right.strip()

    # 右侧应为 c^2(t-t_i)^2
    if not (right == 'c^2(t-t_i)^2' or right == 'c^2*(t-t_i)^2'):
        return {'result': 'fail', 'message': '右侧应为c^2(t-t_i)^2', 'evidence': right}

    # 左侧应为三项平方和
    if not all(term in left for term in pos_terms):
        return {'result': 'fail', 'message': '左侧缺少位置平方项', 'evidence': ''}

    # 检查是否有其他非法符号或结构
    if '+' not in left or left.count('+') != 2:
        return {'result': 'fail', 'message': '左侧应为三项加和', 'evidence': ''}

    return {'result': 'pass', 'message': '符合无时钟定位模型标准形式', 'evidence': 'c^2(t-t_i)^2'}

# rule_id=exp_7b0c37502350b956 | domain=Mechanics | topic=Kinematics in 1D/2D/3D
def check_exp_7b0c37502350b956_76048102fa4c(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否涉及多次碰撞或往复运动
    if not any(keyword in question or keyword in context for keyword in ['collision', 'collide', 'bounce', 'back and forth', 'oscillate', 'repeated', 'periodic', 'cycle']):
        return {'result': 'inconclusive', 'message': '未触发多过程运动场景', 'evidence': ''}

    # 检查预测中是否使用了总路程而非位移
    # 查找平均速度公式

    # 匹配 v_avg = ... 的表达式
    avg_speed_pattern = re.compile(r'v_avg[= ]*([^\n]+)', re.IGNORECASE)
    matches = avg_speed_pattern.findall(prediction)

    if not matches:
        return {'result': 'inconclusive', 'message': '未找到平均速度表达式', 'evidence': ''}

    # 检查每个匹配项
    for expr in matches:
        expr = expr.strip()
        # 检查是否包含绝对值或分段求和形式
        # 期望形式：v_avg = (h0 + 2*h1 + 2*h2 + ...) / T
        # 检查是否包含 h_i 项且系数为 2 或 1，且总和除以 T
        if 'h_' in expr and 't' in expr and 't' in expr.lower():
            # 检查是否为分段求和形式
            # 简单检查：是否有多个 h_i 项，且有加号，且有除以 T
            if '+' in expr and 't' in expr.lower() and '/' in expr:
                # 检查是否为 (sum) / T
                if re.search(r'\([^)]*\)/[tT]', expr):
                    # 检查是否包含 2*h_i 形式
                    if re.search(r'2\*h_\d+', expr) or re.search(r'2h_\d+', expr):
                        return {'result': 'pass', 'message': '正确累加分段路程并使用周期性系数', 'evidence': expr}

    # 检查是否使用了位移（如 Δy, x_final - x_initial）
    displacement_keywords = ['delta', 'final - initial', 'x_f - x_i', 'y_f - y_i', 'displacement']
    if any(kw in prediction for kw in displacement_keywords):
        return {'result': 'fail', 'message': '使用位移而非总路程计算平均速度', 'evidence': prediction}

    # 检查是否明确累加了绝对值
    if any(kw in prediction for kw in ['|', 'abs', 'absolute', 'sum of |', 'total path']):
        return {'result': 'pass', 'message': '使用绝对值累加路程', 'evidence': prediction}

    return {'result': 'inconclusive', 'message': '无法确认是否正确累加路程', 'evidence': ''}

# rule_id=exp_84cd3a248f2378c0 | domain=Mechanics | topic=Kinematics in 1D/2D/3D
def check_exp_84cd3a248f2378c0_d0ddb1ac5fd9(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否涉及转向角和质心侧向加速度
    if 'theta' not in question and 'steering' not in question and 'turn' not in question:
        return {'result': 'inconclusive', 'message': '未提及转向角', 'evidence': ''}
    if 'lateral acceleration' not in question and 'a_y' not in question and 'side' not in question:
        return {'result': 'inconclusive', 'message': '未提及侧向加速度', 'evidence': ''}

    # 检查预测中是否包含 v^2/R + v_dot 形式
    # 优先匹配常见表达式：v^2/R(t) + v_dot, v^2/R + dv/dt, etc.
    patterns = [
        r'v\s*\^\s*2\s*/\s*R\s*\(\s*t\s*\)\s*\+\s*\dot{v}',
        r'v\s*\^\s*2\s*/\s*R\s*\+\s*\dot{v}',
        r'v\s*\*\s*v\s*/\s*R\s*\(\s*t\s*\)\s*\+\s*\dot{v}',
        r'v\s*\*\s*v\s*/\s*R\s*\+\s*\dot{v}',
        r'v\s*\^\s*2\s*/\s*R\s*\+\s*dv/dt',
        r'v\s*\*\s*v\s*/\s*R\s*\+\s*dv/dt',
        r'v\s*\^\s*2\s*/\s*R\s*\+\s*\partial{v}/\partial{t}',
        r'v\s*\*\s*v\s*/\s*R\s*\+\s*\partial{v}/\partial{t}',
        r'v\s*\^\s*2\s*/\s*R\s*\+\s*\frac{dv}{dt}',
        r'v\s*\*\s*v\s*/\s*R\s*\+\s*\frac{dv}{dt}',
        r'v\s*\^\s*2\s*/\s*R\s*\+\s*\dot{v}_y',
        r'v\s*\*\s*v\s*/\s*R\s*\+\s*\dot{v}_y',
        r'v\s*\^\s*2\s*/\s*R\s*\+\s*\partial{v}_y/\partial{t}',
        r'v\s*\*\s*v\s*/\s*R\s*\+\s*\partial{v}_y/\partial{t}',
        r'v\s*\^\s*2\s*/\s*R\s*\+\s*\frac{dv_y}{dt}',
        r'v\s*\*\s*v\s*/\s*R\s*\+\s*\frac{dv_y}{dt}',
    ]

    # 检查预测或上下文是否包含任一模式
    text_to_check = prediction + ' ' + context

    for pattern in patterns:
        if any(pattern in text for text in [prediction, context]):
            return {'result': 'pass', 'message': '正确包含向心项和切向项', 'evidence': text_to_check}

    # 检查是否仅使用分量求导（如 a_y = d(v_y)/dt）
    if any(r'dv_y/dt' in text or r'\frac{dv_y}{dt}' in text or r'\dot{v}_y' in text for text in [prediction, context]):
        if 'v^2/R' not in prediction and 'v^2/R' not in context and 'v* v / R' not in prediction and 'v* v / R' not in context:
            return {'result': 'fail', 'message': '仅使用分量求导，缺少向心项', 'evidence': text_to_check}

    # 若未命中任何模式，保守判断
    return {'result': 'inconclusive', 'message': '未明确建模侧向加速度项', 'evidence': ''}

