# rule_id=exp_bce2ff893ec4b065 | domain=Mechanics | topic=Kinematics in 1D/2D/3D
def check_exp_bce2ff893ec4b065_a687ed132620(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否同时提及震源深度和震中距
    has_depth = any(word in question or word in context for word in ['深度', 'h', 'depth'])
    has_distance = any(word in question or word in context for word in ['震中距', 'd', 'distance', 'epicentral'])

    if not (has_depth and has_distance):
        return {'result': 'inconclusive', 'message': '未同时提及震源深度和震中距', 'evidence': ''}

    # 检查是否明确说明波沿地表传播
    if any(word in prediction or word in context for word in ['沿地表传播', 'surface wave', 'directly along surface', '地表传播']):
        return {'result': 'pass', 'message': '明确说明沿地表传播，无需勾股定理', 'evidence': ''}

    # 查找预测中是否使用了勾股定理公式 s = sqrt(d^2 + h^2)
    # 优先匹配符号表达式
    pattern = r's\s*=\s*sqrt\(d\^2\s*\+\s*h\^2\)'
    if any(pattern in text for text in [prediction, context]):
        return {'result': 'pass', 'message': '正确使用勾股定理计算传播距离', 'evidence': ''}

    # 尝试数值解析 d 和 h，检查是否在预测中使用了 d 和 h 但未用勾股定理
    # 简单提取数字和符号

    d_match = re.search(r'(?i)(?:d|depth|震源深度)\s*[:=]?(\d+\.?\d*)', prediction)
    h_match = re.search(r'(?i)(?:h|depth|震源深度)\s*[:=]?(\d+\.?\d*)', prediction)

    if d_match and h_match:
        d_val = float(d_match.group(1))
        h_val = float(h_match.group(1))
        s_calc = (d_val**2 + h_val**2)**0.5

        # 检查预测中是否直接给出 s 值
        s_match = re.search(r'(?i)s\s*[:=]?(\d+\.?\d*)', prediction)
        if s_match:
            s_pred = float(s_match.group(1))
            if abs(s_pred - s_calc) < 1e-6:
                return {'result': 'pass', 'message': '预测值与勾股定理计算结果一致', 'evidence': ''}
            else:
                return {'result': 'fail', 'message': '传播距离未按勾股定理计算', 'evidence': prediction}

    # 无法确认是否使用勾股定理
    return {'result': 'inconclusive', 'message': '无法确认是否正确使用勾股定理', 'evidence': ''}

