    if not (has_projectile and has_geometry):
        return {
            'result': 'fail',
            'message': '未结合抛体运动与几何尺寸建模',
            'evidence': ''
        }

    # 检查是否使用动量守恒
    momentum_keywords = ['动量守恒', '动量', '守恒定律']
    if any(kw in prediction or kw in context for kw in momentum_keywords):
        return {
            'result': 'fail',
            'message': '错误使用动量守恒，应使用抛体运动方程',
            'evidence': ''
        }

    # 检查是否包含 g, R, m 等符号
    required_symbols = ['g', 'r', 'm']
    found_symbols = set()
    text = question + ' ' + prediction + ' ' + context
    for sym in required_symbols:
        if sym in text or sym.upper() in text:
            found_symbols.add(sym)

    if len(found_symbols) < 3:
        return {
            'result': 'fail',
            'message': '未正确使用 g, R, m 等必要符号',
            'evidence': ''
        }

    # 检查是否出现 W_min = ΔK 或类似表达
