    # 检查是否满足正确公式 T - mg cosθ = m v² / L
    correct_pattern = r't\s*-\s*m\s*\*\s*g\s*\*\s*cos\s*\(\s*\theta\s*\)\s*=\s*m\s*\*\s*v\s*\*\s*v\s*\/\s*L'

