# rule_id=exp_3540497a51d17abe | domain=Mechanics | topic=Circular Motion and Centripetal Force
def check_exp_3540497a51d17abe_d1fe6c9c6918(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    context = sample.get('context', '')
    full_text = question + ' ' + prediction + ' ' + context

    # 检查是否提及隐函数求导或全微分
    if not any(keyword in full_text.lower() for keyword in ['隐函数', '全微分', 'df/dt', 'd/dt', 'dx/dt', 'dy/dt']):
        return {'result': 'inconclusive', 'message': '未提及隐函数求导', 'evidence': ''}

    # 检查是否出现 2x(dx/dt) + 2y(dy/dt) = 0 形式
    canonical = '2x(dx/dt) + 2y(dy/dt) = 0'
    if canonical in prediction or canonical in context:
        return {'result': 'pass', 'message': '命中标准微分形式', 'evidence': canonical}

    # 检查是否出现类似结构：a*x*dx/dt + b*y*dy/dt = 0

    pattern = r'([+-]?[0-9]*[xX])\s*\(d[xy]/dt\)\s*([+-])\s*([+-]?[0-9]*[yY])\s*\(d[xy]/dt\)\s*=\s*0'
    matches = re.findall(pattern, prediction)
    if matches:
        # 简单验证系数是否为2
        for match in matches:
            x_term = match[0].strip()
            y_term = match[2].strip()
            if (x_term.replace('x', '').replace('X', '').strip() == '2' or x_term.replace('x', '').replace('X', '').strip() == '') and \
                (y_term.replace('y', '').replace('Y', '').strip() == '2' or y_term.replace('y', '').replace('Y', '').strip() == ''):
                return {'result': 'pass', 'message': '系数为2的隐微分形式', 'evidence': match[0] + ' ' + match[1] + ' ' + match[2]}

    return {'result': 'inconclusive', 'message': '未发现匹配的微分形式', 'evidence': ''}

# rule_id=exp_3dbeb06a9b454677 | domain=Mechanics | topic=Circular Motion and Centripetal Force
def check_exp_3dbeb06a9b454677_ec7996a4385b(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否涉及摆动、张力、角度、长度、重力
    if 'pendulum' not in question and '摆' not in question and 'swing' not in question:
        return {'result': 'inconclusive', 'message': '未提及摆动场景', 'evidence': ''}
    if 'tension' not in prediction and '张力' not in prediction and 'force' not in prediction and '压力' not in prediction:
        return {'result': 'inconclusive', 'message': '未预测张力或压力', 'evidence': ''}
    if 'theta' not in prediction and '角度' not in prediction and 'cos' not in prediction:
        return {'result': 'inconclusive', 'message': '未涉及角度或cos项', 'evidence': ''}

    # 提取关键参数：L, theta, g（默认g=9.8）
    L = None
    theta = None
    g = 9.8
    try:
        # 从上下文或问题中提取L
        if 'l=' in context or 'l =' in context:
            start = context.find('l=') + 2
            end = context.find(' ', start)
            if end == -1: end = len(context)
            L_str = context[start:end].strip()
            L = float(L_str)
        elif 'length' in context or '长度' in context:
            # 简单提取数字

            nums = re.findall(r'\d+\.?\d*', context)
            if nums:
                L = float(nums[0])
        if L is None:
            # 从问题中尝试提取
            if 'l=' in question:
                start = question.find('l=') + 2
                end = question.find(' ', start)
                if end == -1: end = len(question)
                L_str = question[start:end].strip()
                L = float(L_str)
    except:
        pass

    # 尝试提取角度
    try:

        theta_match = re.search(r'\b(\d+\.?\d*)\s*deg\b|\b(\d+\.?\d*)\s*度\b', prediction)
        if theta_match:
            theta = float(theta_match.group(1) or theta_match.group(2))
            theta = theta * 3.14159 / 180  # 转为弧度
    except:
        pass

    # 检查是否满足 v² = 2gL cosθ
    # 仅当释放角为90°时成立
    if '90' in context or '90度' in context or '90°' in context:
        if L is None or theta is None:
            return {'result': 'inconclusive', 'message': '缺少L或θ', 'evidence': ''}
        v_squared = 2 * g * L * (1 if abs(theta) < 1e-6 else abs(0.0))  # cos(90°)=0
        # 但若θ=0，则cosθ=1，v²=2gL
        if abs(theta) < 1e-6:  # θ=0
            v_squared = 2 * g * L
        else:
            # 一般情况：v² = 2gL cosθ
            v_squared = 2 * g * L * abs(0.0)  # 仅在θ=0时非零
            # 实际上，若释放角为90°，则θ=0时v²=2gL，θ=90°时v²=0
            # 所以 v² = 2gL * cos(θ)
            v_squared = 2 * g * L * abs(0.0)  # 修正：cos(θ) 但θ是当前角度
            # 重新计算：cos(θ)

            cos_theta = math.cos(theta)
            v_squared = 2 * g * L * cos_theta
    else:
        # 释放角非90°，无法使用该公式
        return {'result': 'inconclusive', 'message': '释放角非90°，不适用该公式', 'evidence': ''}

    # 检查预测中是否包含 T = mg cosθ + m v² / L
    # 用符号匹配：T = m g cosθ + m v² / L
    # 用字符串匹配
    if 't=' in prediction or 'tension' in prediction or '张力' in prediction:
        # 检查是否包含 mg cosθ + m v² / L
        # 用简单关键词匹配
        if 'mg' in prediction and 'cos' in prediction and 'v' in prediction and 'l' in prediction and 'm' in prediction:
            # 检查是否包含 m * g * cos(theta) + m * v^2 / L
            # 用正则匹配

            pattern1 = r'm\s*\*\s*g\s*\*\s*cos\s*\(\s*\w*\s*\)'  # m*g*cos(θ)
            pattern2 = r'm\s*\*\s*v\s*\*\s*v\s*/\s*L'  # m*v^2/L
            if re.search(pattern1, prediction) and re.search(pattern2, prediction):
                return {'result': 'pass', 'message': '符合能量-力关联准则', 'evidence': 'T = mg cosθ + m v² / L'}
    return {'result': 'fail', 'message': '未正确使用能量-力关联公式', 'evidence': ''}

