    # 检查是否出现 T*dθ ≈ dm*ω²r 或类似微元形式
    pattern2 = r't\s*\*\s*dθ\s*≈\s*dm\s*\*\s*ω\s*\*\s*ω\s*\*\s*r|t\s*\*\s*dθ\s*≈\s*dm\s*\*\s*ω\s*\^\s*2\s*\*\s*r|t\s*\*\s*dθ\s*≈\s*dm\s*\*\s*ω\s*\*\s*\^\s*2\s*\*\s*r'
