# rule_id=exp_be5504b6afc50ca7 | domain=Mechanics | topic=Circular Motion and Centripetal Force
def check_exp_be5504b6afc50ca7_3215e62ca6cc(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()
    text = question + ' ' + prediction + ' ' + context

    # 检查是否提及张力 T 与周长伸长量的关系
    # 关键模式：T = k * 2π(r - R)
    # 保守匹配：T = k * 2π(.*? - .*)

    pattern = r't\s*=\s*k\s*\*\s*2π\s*\(\s*r\s*-*\s*[a-z]\s*\)'
    if re.search(pattern, text, re.IGNORECASE):
        return {
            "result": "pass",
            "message": "正确表达了张力与周长伸长量的关系",
            "evidence": re.search(pattern, text, re.IGNORECASE).group()
        }

    # 检查是否错误地使用单位长度受力
    # 如：T = k * (r - R) 或 T = k * Δr
    if re.search(r't\s*=\s*k\s*\*\s*\(\s*r\s*-*\s*[a-z]\s*\)', text, re.IGNORECASE):
        return {
            "result": "fail",
            "message": "错误地将劲度系数用于单位长度，应为周长伸长量",
            "evidence": re.search(r't\s*=\s*k\s*\*\s*\(\s*r\s*-*\s*[a-z]\s*\)', text, re.IGNORECASE).group()
        }

    return {
        "result": "inconclusive",
        "message": "未检测到相关表达式",
        "evidence": ""
    }

