# rule_id=exp_aa4d006cab6f7475 | domain=Mechanics | topic=Newton's Laws and Free Body Diagrams
def check_exp_aa4d006cab6f7475_2811afec8505(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    combined_text = question + ' ' + prediction + ' ' + answer + ' ' + context

    # 检查微分方程形式 dv/dt = g - (k/m)v^2
    equation_pattern = 'dv/dt = g - (k/m)v^2'
    if equation_pattern not in combined_text:
        return {
            'result': 'fail',
            'message': '未发现标准微分方程形式',
            'evidence': ''
        }

    # 检查解析解是否包含 tanh 形式，且包含指定符号
    canonical_tanh = 'sqrt(mg/k) * tanh(sqrt(kg/m) * t)'
    if 'tanh' not in combined_text:
        return {
            'result': 'fail',
            'message': '解析解中未出现 tanh 函数',
            'evidence': ''
        }

    # 检查关键符号是否存在
    required_symbols = {'m', 'g', 'k', 't'}
    found_symbols = set()
    for char in combined_text:
        if char.isalpha() and char in 'mgkt':
            found_symbols.add(char)

    if not required_symbols.issubset(found_symbols):
        return {
            'result': 'inconclusive',
            'message': '关键符号缺失，无法确认',
            'evidence': ''
        }

    # 检查是否包含标准解的结构
    if canonical_tanh not in combined_text:
        return {
            'result': 'fail',
            'message': '解析解形式不匹配标准形式',
            'evidence': ''
        }

    return {
        'result': 'pass',
        'message': '符合平方阻力运动方程标准化规则',
        'evidence': canonical_tanh
    }

# rule_id=exp_f84dc06ca4b9e924 | domain=Mechanics | topic=Newton's Laws and Free Body Diagrams
def check_exp_f84dc06ca4b9e924_1e5ee974644a(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否提及复杂分布函数（如指数、幂律）
    complex_distributions = ['exponential', 'power law', 'inverse square', 'r**', 'r^', 'exp(', 'e^']
    has_complex = any(dist in question or dist in prediction or dist in context for dist in complex_distributions)

    # 检查是否提及 h << R 或近地近似
    near_earth = any(keyword in question or keyword in prediction or keyword in context for keyword in ['h << r', 'h much less than r', 'near earth', 'local approximation', 'h << r_e', 'h << r_earth'])

    # 检查是否在 h=0 处取值或忽略高阶项
    simplified_at_zero = any(keyword in prediction or keyword in context for keyword in ['evaluate at h=0', 'set h=0', 'ignore higher order terms', 'treat as constant', 'constant gravity', 'g is constant'])

    # 若有复杂分布且有近地条件，但未简化，则失败
    if has_complex and near_earth and not simplified_at_zero:
        return {
            "result": "fail",
            "message": "未在 h=0 处简化复杂分布函数，违反近地近似规则",
            "evidence": "complex distribution + h<<R but no simplification at h=0"
        }

    # 若有复杂分布但无近地条件，或未提及简化，返回 inconclusive
    if has_complex and not near_earth:
        return {
            "result": "inconclusive",
            "message": "未提及 h<<R，无法判断是否应简化",
            "evidence": "complex distribution but no h<<R condition"
        }

    # 若无复杂分布，但提及近地近似，且简化了，视为合理
    if not has_complex and near_earth and simplified_at_zero:
        return {
            "result": "pass",
            "message": "近地近似下合理简化为恒力",
            "evidence": "h<<R and simplified at h=0"
        }

    # 其他情况视为无问题或无法判断
    return {
        "result": "inconclusive",
        "message": "未检测到明确的分布或简化行为",
        "evidence": ""
    }

# rule_id=exp_57525a0331091aee | domain=Mechanics | topic=Friction and Contact Forces
def check_exp_57525a0331091aee_0a62ae5d2796(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()
    answer = sample.get('answer', '').lower()

    # 提取关键符号
    symbols = {'μ': None, 'm': None, 'g': None, 'ω': None, 'r': None, 'v': None}
    found_symbols = 0

    # 简单正则匹配符号

    for sym in symbols:
        match = re.search(rf'({sym})[\s\*\^\(\)]*([\d\.]+)', prediction + ' ' + context + ' ' + answer)
        if match:
            try:
                symbols[sym] = float(match.group(2))
                found_symbols += 1
            except:
                pass

    # 检查是否至少找到所有符号
    if found_symbols < 6:
        return {
            "result": "inconclusive",
            "message": "未找到足够物理量符号",
            "evidence": ""
        }

    # 检查是否包含 (ωr/v)^2 项
    pattern = r'\(\s*ω\s*\*\s*r\s*\/\s*v\s*\)\s*\^\s*2|\(\s*ωr\s*\/\s*v\s*\)\s*\^\s*2|ω\s*\*\s*r\s*\/\s*v\s*\^\s*2|ωr\s*\/\s*v\s*\^\s*2'
    if not re.search(pattern, prediction + ' ' + context + ' ' + answer):
        return {
            "result": "fail",
            "message": "未发现 (ωr/v)^2 项",
            "evidence": ""
        }

    # 检查是否正比于 μmg(ωr/v)^2
    # 检查是否包含 μmg
    if not re.search(r'μ\s*\*\s*m\s*\*\s*g|μm g|μmg', prediction + ' ' + context + ' ' + answer):
        return {
            "result": "fail",
            "message": "未发现 μmg 因子",
            "evidence": ""
        }

    # 检查是否为比例关系
    if not re.search(r'∝|proportional|正比|正比于', prediction + ' ' + context + ' ' + answer):
        return {
            "result": "fail",
            "message": "未体现正比关系",
            "evidence": ""
        }

    # 检查是否满足 ωr << v
    omega_r = symbols['ω'] * symbols['r']
    v_val = symbols['v']
    if v_val <= 0 or omega_r <= 0:
        return {
            "result": "inconclusive",
            "message": "速度或角速度为零或无效",
            "evidence": ""
        }

    if omega_r >= v_val:
        return {
            "result": "fail",
            "message": "不满足 ωr << v 条件",
            "evidence": ""
        }

    return {
        "result": "pass",
        "message": "符合复合运动摩擦力投影规则",
        "evidence": "(ωr/v)^2 项、μmg 因子、正比关系、ωr << v 均满足"
    }

# rule_id=exp_7b9cfa6d9ad18c80 | domain=Mechanics | topic=Friction and Contact Forces
def check_exp_7b9cfa6d9ad18c80_94c5bf4c0daa(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否触发规则：题目要求物理量存在 local maximum
    if 'local maximum' not in question and 'local max' not in question:
        return {'result': 'inconclusive', 'message': '未触发局部极大值条件', 'evidence': ''}

    # 检查预测中是否包含一阶导为零且二阶导为负的判据
    # 优先匹配符号表达式：dθ/dt = 0 且 d²θ/dt² < 0
    # 使用关键词匹配，避免复杂解析
    has_first_derivative_zero = any(keyword in prediction for keyword in ['dθ/dt = 0', 'dθ/dt = 0', 'dθ/dt = 0', 'velocity = 0', 'v = 0', 'angular velocity = 0', 'ω = 0'])
    has_second_derivative_negative = any(keyword in prediction for keyword in ['d²θ/dt² < 0', 'd²θ/dt² < 0', 'acceleration < 0', 'a < 0', 'angular acceleration < 0', 'α < 0'])

    # 检查是否同时满足两个条件
    if has_first_derivative_zero and has_second_derivative_negative:
        return {'result': 'pass', 'message': '正确识别局部极大值判据', 'evidence': 'dθ/dt = 0 且 d²θ/dt² < 0'}

    # 若仅满足一个或都不满足
    if not has_first_derivative_zero or not has_second_derivative_negative:
        return {'result': 'fail', 'message': '未同时满足一阶导为零且二阶导为负', 'evidence': ''}

    return {'result': 'inconclusive', 'message': '无法判断是否满足判据', 'evidence': ''}

