# rule_id=exp_942950ef2a68eef9 | domain=Mechanics | topic=Friction and Contact Forces
def check_exp_942950ef2a68eef9_ef1eb0b7e3af(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    context = sample.get('context', '')
    text = (question + ' ' + prediction + ' ' + context).lower()

    # 检查是否涉及力 F 的表达式
    if 'f' not in text and 'force' not in text:
        return {'result': 'inconclusive', 'message': '未检测到力相关变量', 'evidence': ''}

    # 量纲模式: [F] = [M][L][T]^-2
    # 检查右侧是否包含 m, g 等符号
    required_symbols = {'m', 'g'}
    found_symbols = set()
    for sym in required_symbols:
        if f' {sym} ' in text or f' {sym}(' in text or f'{sym} ' in text:
            found_symbols.add(sym)

    if len(found_symbols) < len(required_symbols):
        return {'result': 'inconclusive', 'message': '未找到全部必要符号', 'evidence': ''}

    # 检查是否出现速度 v 或角速度 ω 与半径 r 的组合
    velocity_terms = ['v', 'velocity', 'speed', 'omega', 'angular velocity']
    radius_terms = ['r', 'radius', 'length']
    has_velocity = any(term in text for term in velocity_terms)
    has_radius = any(term in text for term in radius_terms)

    if has_velocity and has_radius:
        # 检查是否出现 v*r 或 omega*r 等组合
        combinations = ['v*r', 'v r', 'omega*r', 'omega r', 'omega * r', 'v * r']
        if not any(combo in text for combo in combinations):
            return {'result': 'fail', 'message': '速度与半径组合缺失', 'evidence': ''}

    # 检查量纲是否匹配：F 应为 [M][L][T]^-2
    # 简单检查：若出现 m*g，则为 [M][L][T]^-2，合理
    if 'm*g' in text or 'm * g' in text:
        return {'result': 'pass', 'message': '量纲匹配', 'evidence': 'm*g'}

    # 若未明确出现 m*g，但有其他组合，保守判断
    return {'result': 'inconclusive', 'message': '无法确认量纲一致性', 'evidence': ''}

