# rule_id=exp_af82c102b6dbed1d | domain=Mechanics | topic=Power and Energy Dissipation
def check_exp_af82c102b6dbed1d_d2c4588670f0(sample: dict) -> dict:
    text = (sample.get('prediction', '') + ' ' + sample.get('context', '')).lower()
    if not text.strip():
        return {'result': 'inconclusive', 'message': '无输入文本', 'evidence': ''}

    # 检查是否出现 v * dv/dy 或等价形式
    has_v_dv_dy = any(pattern in text for pattern in [
        'v * dv/dy', 'v dv/dy', 'v (dv/dy)', 'v\*dv/dy', 'v\*\(dv/dy\)',
        'v \cdot dv/dy', 'v \frac{dv}{dy}', 'v \frac{dv}{dy} =',
        'v dv/dy =', 'v * dv/dy =', 'v (dv/dy) ='
    ])

    # 检查是否出现 -g - (k/m)v^2 或等价形式
    has_right_side = any(pattern in text for pattern in [
        '-g - (k/m)v^2', '-g - k/m * v^2', '-g - (k/m)v^2',
        '-g - k/m v^2', '-g - (k/m)v^2', '-g - k/m * v^2',
        '-g - (k/m)*v^2', '-g - k/m*v^2',
        ' - g - (k/m)v^2', ' - g - k/m * v^2'
    ])

    # 检查是否使用时间积分（如 dt, dv/dt, a = dv/dt）
    has_time_integral = any(pattern in text for pattern in [
        'dv/dt', 'a = dv/dt', 'dv/dt =', 'dt', 'time', 't', 'd/dt'
    ])

    # 若出现时间积分，直接失败
    if has_time_integral:
        return {'result': 'fail', 'message': '使用了时间积分而非空间积分', 'evidence': ''}

    # 若未出现 v(dv/dy) 形式，但出现正确右侧项，可能不完整
    if not has_v_dv_dy and has_right_side:
        return {'result': 'inconclusive', 'message': '未发现 v(dv/dy) 形式', 'evidence': ''}

    # 若同时出现 v(dv/dy) 和右侧项，且无时间积分
    if has_v_dv_dy and has_right_side:
        return {'result': 'pass', 'message': '正确使用空间积分 v(dv/dy) = a', 'evidence': ''}

    # 其他情况
    return {'result': 'inconclusive', 'message': '未检测到关键表达式', 'evidence': ''}

# rule_id=exp_25aae165bd25a9ec | domain=Mechanics | topic=Linear Momentum and Collisions
def check_exp_25aae165bd25a9ec_1c552db619ec(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    if 'momentum' not in question and 'collision' not in question and 'merge' not in question and 'combine' not in question:
        return {'result': 'inconclusive', 'message': '未触发碰撞场景', 'evidence': ''}

    # 检查是否直接使用碰撞前速度计算动能
    direct_use_pattern = r'k_after.*?=(.*?)(?:v_before|u|initial|original|pre-collision|before collision)'

    # 检查是否先求末速度再求动能
    correct_sequence = r'(?:momentum|conservation).*?v_final|v_after|v_new|v_final.*?k_after'

    if not any(keyword in prediction for keyword in ['momentum', 'conservation', 'v_final', 'v_after', 'v_new']):
        return {'result': 'fail', 'message': '未使用动量守恒求末速度', 'evidence': ''}

    if any(keyword in prediction for keyword in ['k_after', 'kinetic energy after']) and any(keyword in prediction for keyword in ['v_before', 'initial velocity', 'pre-collision']):
        if any(pattern in prediction for pattern in [r'k_after.*?v_before', r'k_after.*?u', r'k_after.*?initial']):
            return {'result': 'fail', 'message': '直接用碰撞前速度计算动能', 'evidence': ''}

    # 检查是否出现错误的动能公式
    if 'k_after = (m^2 / (m + m)) * (k_before / m)' in prediction or 'k_after = (m^2 / (m + m)) * k_before' in prediction:
        return {'result': 'fail', 'message': '使用错误的动能公式', 'evidence': ''}

    # 检查是否出现符号提示中的等价式
    canonical_hint = 'k_after = (M^2 / (M + m)) * (k_before / M)'
    if canonical_hint in prediction:
        return {'result': 'pass', 'message': '符合能量转化规则', 'evidence': canonical_hint}

    return {'result': 'inconclusive', 'message': '无法确认是否正确使用规则', 'evidence': ''}

# rule_id=exp_386d2646ec10da07 | domain=Mechanics | topic=Linear Momentum and Collisions
def check_exp_386d2646ec10da07_9e8f4e220d49(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    text = question + ' ' + prediction + ' ' + answer + ' ' + context
    text = text.lower()

    # 检查是否涉及完全弹性碰撞
    if 'perfectly elastic' not in text and 'elastic collision' not in text:
        return {'result': 'inconclusive', 'message': '未提及完全弹性碰撞', 'evidence': ''}

    # 提取 v1, v2, v1', v2' 的值
    # 使用正则匹配速度符号

    # 匹配 v1, v2, v1', v2' 的数值
    pattern = r'(?:v[12]|v[12]’|v[12]prime|v[12]\’|v[12]\\u2019)[\s]*=\s*([+-]?\d+\.?\d*)'
    matches = re.findall(pattern, text)

    if len(matches) < 4:
        return {'result': 'inconclusive', 'message': '未提取到足够速度值', 'evidence': ''}

    try:
        v1 = float(matches[0])
        v2 = float(matches[1])
        v1_prime = float(matches[2])
        v2_prime = float(matches[3])
    except:
        return {'result': 'inconclusive', 'message': '速度值解析失败', 'evidence': ''}

    # 计算碰撞前后的相对速度
    relative_before = v2 - v1
    relative_after = v2_prime - v1_prime

    # 检查是否满足 v2' - v1' = -(v2 - v1)
    # 允许小误差
    tolerance = 1e-6
    if abs(relative_after + relative_before) < tolerance:
        return {'result': 'pass', 'message': '相对速度大小相等，方向相反', 'evidence': f'v2 - v1 = {relative_before}, v2prime - v1prime = {relative_after}'}
    else:
        return {'result': 'fail', 'message': '相对速度不满足守恒律', 'evidence': f'v2 - v1 = {relative_before}, v2prime - v1prime = {relative_after}'}

