# rule_id=exp_ad6ce22bf45ef7ac | domain=Mechanics | topic=Rotational Kinematics and Dynamics
def check_exp_ad6ce22bf45ef7ac_d867745146f3(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    context = sample.get('context', '')
    text = (question + ' ' + prediction + ' ' + context).lower()

    # 检查是否提及滑动摩擦力与相对速度单位向量
    if 'friction' not in text or 'relative velocity' not in text and 'hat{u}' not in text:
        return {'result': 'inconclusive', 'message': '未提及滑动摩擦力与相对速度单位向量', 'evidence': ''}

    # 检查加速度方向是否与 -\hat{u} 一致
    acc_match = any(keyword in text for keyword in ['acceleration', 'dot{v}', 'v\dot', 'a'])
    neg_u_match = any(keyword in text for keyword in ['minus hat{u}', '-\hat{u}', 'negative hat{u}'])
    if not (acc_match and neg_u_match):
        return {'result': 'fail', 'message': '加速度方向未与 -\hat{u} 一致', 'evidence': ''}

    # 检查力矩是否满足右手定则：\vec{r} \times (-\mu mg \hat{u})
    cross_product_match = any(keyword in text for keyword in ['cross', 'times', 'r cross', 'r \times'])
    mu_mg_u_match = any(keyword in text for keyword in ['mu mg hat{u}', 'mu m g hat{u}', 'friction force'])
    if not (cross_product_match and mu_mg_u_match):
        return {'result': 'fail', 'message': '力矩方向未满足右手定则', 'evidence': ''}

    # 检查是否出现 canonical 形式
    canonical = 'm\dot{\vec{v}} = -\mu mg \hat{u}'
    if canonical not in text:
        return {'result': 'inconclusive', 'message': '未出现标准方程形式', 'evidence': ''}

    return {'result': 'pass', 'message': '滑动摩擦力方向与相对速度单位向量一致，力矩满足右手定则', 'evidence': canonical}

