# rule_id=exp_08f6806c117fd562 | domain=Mechanics | topic=Angular Momentum Conservation
def check_exp_08f6806c117fd562_1a78f3a75568(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()
    text = question + ' ' + prediction + ' ' + context

    trigger_keywords = ['潮汐锁定', '同步旋转', '过程结束且力矩消失']
    if not any(kw in text for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未触发规则条件', 'evidence': ''}

    # 检查是否使用了统一变量 ω 表示自转与公转角速度
    # 优先匹配 ω_rotation = ω_orbit = ω_final 形式
    pattern = r'ω[_　-〿＀-￯]?[a-z]*\s*=[^=]*ω[_　-〿＀-￯]?[a-z]*\s*=[^=]*ω[_　-〿＀-￯]?[a-z]*'
    if not any(kw in text for kw in ['ω_rotation', 'ω_orbit', 'ω_final']):
        return {'result': 'inconclusive', 'message': '未发现关键符号', 'evidence': ''}

    # 简单检查是否出现 ω 的等价关系
    if 'ω' not in text:
        return {'result': 'fail', 'message': '未使用 ω 变量', 'evidence': ''}

    # 检查是否出现 ω_rotation = ω_orbit 或类似等式
    if any(kw in text for kw in ['ω_rotation = ω_orbit', 'ω_orbit = ω_rotation', 'ω_rotation = ω_final', 'ω_final = ω_rotation']):
        return {'result': 'pass', 'message': '满足潮汐锁定同步判据', 'evidence': '检测到 ω_rotation = ω_orbit 等价关系'}

    # 检查是否出现 ω = ω 的形式
    if 'ω = ω' in text:
        return {'result': 'pass', 'message': '满足潮汐锁定同步判据', 'evidence': '检测到 ω = ω'}

    return {'result': 'inconclusive', 'message': '未明确匹配等价关系', 'evidence': ''}

