    has_no_torque = any(keyword in context for keyword in ['no external torque', 'no net torque', 'no external moment', 'no external force', 'no external influence'])
    has_no_relative_omega_change = any(keyword in context for keyword in ['no relative angular velocity change', 'no relative tangential velocity', 'no radial or tangential thrust', 'no push', 'no force in radial or tangential direction'])

    # 检查是否提及质量流失但角速度不变
    has_mass_loss = any(keyword in context for keyword in ['mass loss', 'mass ejection', 'mass flowing out', 'ejecting mass', 'losing mass'])
