# rule_id=exp_047e92b4d83463bc | domain=Mechanics | topic=Gravitation and Kepler's Laws
def check_exp_047e92b4d83463bc_1b1321a25299(sample: dict) -> dict:
    question = sample.get('question', '').lower()
