# rule_id=exp_37a18c99c7de474c | domain=Mechanics | topic=Gravitation and Kepler's Laws
def check_exp_37a18c99c7de474c_426ea165f401(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    # 提取 R_inner 和 R_outer
    r_inner = None
    r_outer = None

    # 从 context 或 prediction 中提取数值

    # 匹配类似 "R_inner = 0.72" 或 "r_inner = 0.72" 的模式
    for text in [context, prediction, question, answer]:
        match = re.search(r'(r_inner|radius_inner|inner_radius|r_in|inner|orbit_radius_inner)[\s=]*([\d\.]+)', text)
        if match:
            try:
                r_inner = float(match.group(2))
            except:
                pass
        match = re.search(r'(r_outer|radius_outer|outer_radius|r_out|outer|orbit_radius_outer)[\s=]*([\d\.]+)', text)
        if match:
            try:
                r_outer = float(match.group(2))
            except:
                pass

    if r_inner is None or r_outer is None:
        return {
            "result": "inconclusive",
            "message": "未找到内行星或外行星轨道半径值",
            "evidence": ""
        }

    if r_inner >= r_outer:
        return {
            "result": "fail",
            "message": "内轨道半径不应大于或等于外轨道半径",
            "evidence": ""
        }

    # 计算 sin(θ_max) = r_inner / r_outer
    sin_theta_max = r_inner / r_outer

    # 检查是否在合理范围内 [0, 1]
    if sin_theta_max > 1.0:
        return {
            "result": "fail",
            "message": "sin(θ_max) 超出 [0,1] 范围，不合理",
            "evidence": ""
        }

    # 检查是否在预测或答案中出现 sin(θ_max) = r_inner / r_outer
    # 用关键词匹配
    canonical_eq = f"sin(θ_max) = {r_inner} / {r_outer}"
    canonical_eq_alt = f"sin(θ_max) = {r_inner}/{r_outer}"

    matched = False
    for text in [prediction, answer, context, question]:
        if canonical_eq in text or canonical_eq_alt in text:
            matched = True
            break

    if matched:
        return {
            "result": "pass",
            "message": "满足 sin(θ_max) = R_inner / R_outer 的几何关系",
            "evidence": canonical_eq
        }

    # 尝试匹配 sin(θ_max) ≈ x 的形式
    sin_match = re.search(r'sin\s*\(\s*θ_max\s*\)\s*[=≈]\s*([\d\.]+)', prediction)
    if sin_match:
        try:
            sin_val = float(sin_match.group(1))
            if abs(sin_val - sin_theta_max) < 1e-5:
                return {
                    "result": "pass",
                    "message": "sin(θ_max) 数值匹配 R_inner / R_outer",
                    "evidence": f"sin(θ_max) ≈ {sin_val}"
                }
        except:
            pass

    return {
        "result": "fail",
        "message": "未检测到 sin(θ_max) = R_inner / R_outer 或等效表达",
        "evidence": ""
    }

# rule_id=exp_44f6759e80e831f2 | domain=Mechanics | topic=Gravitation and Kepler's Laws
def check_exp_44f6759e80e831f2_98cfc6b566b0(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否触发条件：地面参考系、转动地球、速度合成
    if 'ground frame' not in question and '地面参考系' not in question:
        return {'result': 'inconclusive', 'message': '未触发地面参考系条件', 'evidence': ''}

    # 检查是否涉及惯性系与地球随动速度区分
    if 'inertial' not in prediction and '惯性系' not in prediction and 'v_inertial' not in prediction:
        return {'result': 'fail', 'message': '未区分惯性系速度与地面随动速度', 'evidence': prediction}

    # 检查是否正确使用顺行/逆行公式
    # 顺行：v = v_inertial - v_earth
    # 逆行：v = v_inertial + v_earth
    # 检查是否出现 v_inertial - v_earth 或 v_inertial + v_earth
    has_minus = 'v_inertial' in prediction and ' - ' in prediction and 'v_earth' in prediction
    has_plus = 'v_inertial' in prediction and ' + ' in prediction and 'v_earth' in prediction

    # 检查是否同时出现正负，或仅出现一个
    if has_minus and has_plus:
        return {'result': 'fail', 'message': '同时使用顺行和逆行公式，逻辑矛盾', 'evidence': prediction}

    if not has_minus and not has_plus:
        return {'result': 'fail', 'message': '未正确使用速度合成公式', 'evidence': prediction}

    # 检查是否在答案中体现正确关系
    if 'v_{inertial}' in answer and 'v_{ground}' in answer and 'omega' in answer and 'r' in answer:
        return {'result': 'pass', 'message': '正确使用速度合成公式', 'evidence': answer}

    # 保守判断
    return {'result': 'inconclusive', 'message': '无法确认公式使用是否正确', 'evidence': prediction}

# rule_id=exp_4efef57ccc2cd9fd | domain=Mechanics | topic=Gravitation and Kepler's Laws
def check_exp_4efef57ccc2cd9fd_2882c8f014f7(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否触发条件：给出g和R，未给G
    has_g = any(keyword in question or context for keyword in ['g', 'gravity', 'acceleration due to gravity'])
    has_R = any(keyword in question or context for keyword in ['r', 'radius', 'earth radius'])
    has_G = any(keyword in question or context or prediction for keyword in ['g', 'gravitational constant', 'g', 'g_'])

    if not (has_g and has_R) or has_G:
        return {'result': 'inconclusive', 'message': '未满足触发条件', 'evidence': ''}

    # 检查是否使用了 GM = g * R^2 的替换
    # 关键表达式：GM = g * R^2
    # 检查预测中是否出现 GM 被替换为 g * R^2 的形式
    # 优先检查是否出现 g * R^2 形式，且未显式使用 G
    g_term = any(keyword in prediction for keyword in ['g * r', 'g * r_e', 'g * r_earth', 'g * r^2', 'g * r_e^2'])
    G_used = any(keyword in prediction for keyword in ['g', 'gravitational constant', 'g_', 'g\s*\*'])

    # 若预测中使用了 g*R^2 且未显式出现 G，则认为使用了黄金代换
    if g_term and not G_used:
        return {'result': 'pass', 'message': '正确使用 GM = gR^2 代换', 'evidence': 'g * r^2'}

    # 检查是否在推导中出现 GM 被替换为 gR^2
    if 'gm' in prediction and any(kw in prediction for kw in ['g * r', 'g * r_e', 'g * r^2']):
        return {'result': 'pass', 'message': '正确使用 GM = gR^2 代换', 'evidence': 'gm = g * r^2'}

    return {'result': 'fail', 'message': '未使用 GM = gR^2 代换', 'evidence': ''}

