# rule_id=exp_6a841ecb9ce0d80c | domain=Mechanics | topic=Gravitation and Kepler's Laws
def check_exp_6a841ecb9ce0d80c_aa7abb1f0b25(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否触发规则：寻找两种机制切换点或临界半径
    trigger_keywords = ['切换点', '临界半径', '转换点', '平衡点', '相变半径', '等效半径']
    if not any(kw in question or kw in context for kw in trigger_keywords):
        return {
            "result": "inconclusive",
            "message": "未检测到切换点或临界半径相关描述",
            "evidence": ""
        }

    # 检查是否涉及两种机制（如摩擦与辐射）
    mechanism_keywords = ['摩擦', '辐射', '耗散', '阻尼', '引力', '库仑', '粘滞', '热传导', '引力波']
    mechanisms_found = [kw for kw in mechanism_keywords if kw in context or kw in prediction]
    if len(mechanisms_found) < 2:
        return {
            "result": "inconclusive",
            "message": "未识别出两种耗散机制",
            "evidence": ""
        }

    # 检查能量损失率量纲一致性：dE/dt 必须相同
    # 常见能量损失率形式：P ~ v^n * a^m
    # 通过关键词判断是否出现功率表达式
    power_patterns = ["p =", "power =", "dE/dt =", "energy loss rate", "radiation power"]
    has_power_expr = any(pattern in prediction or pattern in context for pattern in power_patterns)
    if not has_power_expr:
        return {
            "result": "inconclusive",
            "message": "未发现能量损失率表达式",
            "evidence": ""
        }

    # 检查是否建立等量关系：P1(a) = P2(a)
    equality_pattern = r"p\s*[^=]*=\s*[^=]+"
    matches = []
    for text in [prediction, context]:
        if any(kw in text for kw in ['p1', 'p2', 'mechanism1', 'mechanism2', 'p_mech1', 'p_mech2']):
            if any(eq in text for eq in ['=', '==', 'is equal to']):
                matches.append(text)
    if not matches:
        return {
            "result": "fail",
            "message": "未建立两种机制功率相等关系 P1(a) = P2(a)",
            "evidence": ""
        }

    # 检查特征速度幂次比例是否符合物理直觉：如 sigma ~ c 时，幂次应一致
    # 简单检查是否出现速度符号（如 v, c, sigma）并判断其幂次
    speed_symbols = ['c', 'v', 'sigma', 'u', 'speed']
    speed_powers = []
    for text in [prediction, context]:
        for sym in speed_symbols:
            if sym in text:
                # 查找该符号的幂次（如 c^2, sigma^1）

                power_match = re.search(rf"{re.escape(sym)}\s*\^?\s*([0-9]+|\-?[0-9]+)", text)
                if power_match:
                    try:
                        power = int(power_match.group(1))
                        speed_powers.append(power)
                    except:
                        pass
    if len(speed_powers) < 2:
        return {
            "result": "inconclusive",
            "message": "未检测到足够速度符号的幂次信息",
            "evidence": ""
        }

    # 检查幂次是否一致或合理（如 c^2 与 sigma^2）
    if len(set(speed_powers)) > 1:
        # 若幂次不同，需判断是否合理（如 c^2 与 sigma^2 可接受，c^1 与 sigma^2 不合理）
        # 简化判断：若幂次差 > 1，则视为不合理
        if max(speed_powers) - min(speed_powers) > 1:
            return {
                "result": "fail",
                "message": "特征速度幂次比例不符合物理直觉（差异过大）",
                "evidence": ""
            }

    # 所有检查通过
    return {
        "result": "pass",
        "message": "满足耗散机制切换点建模规则：量纲一致、等量代换、速度幂次合理",
        "evidence": ""
    }

# rule_id=exp_6c5c6e4dc7bf5813 | domain=Mechanics | topic=Gravitation and Kepler's Laws
def check_exp_6c5c6e4dc7bf5813_ac55c7226d2a(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    text = question + ' ' + prediction + ' ' + answer + ' ' + context

    # 检查是否提及史瓦西半径或引力半径
    if '引力半径' not in text and 'schwarzschild' not in text and 'r_g' not in text and '2gm/c^2' not in text:
        return {'result': 'inconclusive', 'message': '未提及引力半径相关公式', 'evidence': ''}

    # 检查公式是否为 R = 2GM/c^2 或等价形式
    formula_patterns = [
        'r = 2gm/c^2',
        'r_g = 2gm/c^2',
        '2gm/c^2',
        '2 * g * m / c^2',
        '2gm/c²',
        '2 * g * m / c²'
    ]
    matched_formula = any(pattern in text for pattern in formula_patterns)

    if not matched_formula:
        return {'result': 'fail', 'message': '公式不匹配 R = 2GM/c^2', 'evidence': ''}

    # 检查数量级：G ~ 6.67e-11, c^2 ~ 9e16, 所以 G/c^2 ~ 7.4e-28
    # 2G/c^2 ~ 1.48e-27，应接近 10^-27
    # 仅检查是否数量级在 10^-27 左右（1e-28 到 1e-26）
    g_val = 6.67e-11
    c2_val = 9e16
    expected_factor = 2 * g_val / c2_val  # ~1.48e-27

    # 检查是否在 1e-28 到 1e-26 之间
    if expected_factor < 1e-28 or expected_factor > 1e-26:
        return {'result': 'fail', 'message': '数量级抵消不在 10^-27 左右', 'evidence': ''}

    return {'result': 'pass', 'message': '公式与数量级校验通过', 'evidence': 'R = 2GM/c^2'}

# rule_id=exp_723a930e6fa2cf23 | domain=Mechanics | topic=Gravitation and Kepler's Laws
def check_exp_723a930e6fa2cf23_e3c76daeda70(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    evidence = ''
    result = 'inconclusive'
    message = ''

    # 提取 v_f 和 v_circular（或 v_0）
    v_f = None
    v_circular = None

    # 尝试从 prediction 或 answer 中提取数值

    # 匹配 v_f
    v_f_match = re.search(r'v_f\s*[:=]?(\s*[-+]?\d*\.?\d+)', prediction + ' ' + answer + ' ' + context, re.IGNORECASE)
    if v_f_match:
        try:
            v_f = float(v_f_match.group(1).strip())
        except:
            pass

    # 匹配 v_circular 或 v_0
    v_circular_match = re.search(r'v_0\s*[:=]?(\s*[-+]?\d*\.?\d+)|v_circular\s*[:=]?(\s*[-+]?\d*\.?\d+)', prediction + ' ' + answer + ' ' + context, re.IGNORECASE)
    if v_circular_match:
        try:
            v_circular = float(v_circular_match.group(1).strip() or v_circular_match.group(2).strip())
        except:
            pass

    # 若都未提取到，返回 inconclusive
    if v_f is None or v_circular is None:
        return {
            "result": "inconclusive",
            "message": "未提取到足够数值信息",
            "evidence": ""
        }

    # 计算 sqrt(2) * v_circular
    sqrt2 = 1.41421356237
    threshold = sqrt2 * v_circular

    # 判断 v_f < sqrt(2) * v_circular
    if v_f < threshold:
        result = 'pass'
        message = '未达到逃逸速度，未脱离引力束缚'
    else:
        result = 'fail'
        message = '达到或超过逃逸速度，脱离引力束缚'

    # 尝试提取命中的文本片段
    for text in [prediction, answer, context]:
        if 'v_f' in text and 'v_circular' in text:
            evidence = text
            break
        if 'v_f' in text and 'v_0' in text:
            evidence = text
            break

    return {
        "result": result,
        "message": message,
        "evidence": evidence
    }

# rule_id=exp_7c41f6ccbb87ff0c | domain=Mechanics | topic=Gravitation and Kepler's Laws
def check_exp_7c41f6ccbb87ff0c_1b3127372b9f(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否提及中心密度或特定点密度但无分布函数
    has_center_density = any(word in question for word in ['center density', 'rho0', 'central density', 'ρ0'])
    has_point_density = any(word in question for word in ['specific point', 'at a point', 'given point'])

    if not (has_center_density or has_point_density):
        return {'result': 'pass', 'message': '未提及密度信息', 'evidence': ''}

    # 检查是否引入了线性或多项式分布假设
    linear_assumptions = ['linear', 'linearly', 'proportional', 'rho = a*r', 'rho = a + b*r', 'rho = a*r + b', 'rho = a*r**2']
    poly_assumptions = ['polynomial', 'quadratic', 'cubic', 'higher order', 'power law']

    found_linear = any(assumption in prediction for assumption in linear_assumptions)
    found_poly = any(assumption in prediction for assumption in poly_assumptions)

    # 检查是否通过上下文或前序题定义了分布
    has_distribution_def = any(word in context for word in ['defined', 'given', 'assumed', 'from previous part', 'previously', 'derived'])

    if found_linear or found_poly:
        if not has_distribution_def:
            return {'result': 'fail', 'message': '禁止私自引入线性或多项式密度分布假设', 'evidence': prediction}

    # 若未发现违规但无分布定义，需进一步确认
    if not has_distribution_def:
        return {'result': 'inconclusive', 'message': '未明确分布定义，但未发现违规假设', 'evidence': ''}

