# rule_id=exp_7ed77810e20d0fb8 | domain=Mechanics | topic=Gravitation and Kepler's Laws
def check_exp_7ed77810e20d0fb8_ffe7bcb7355c(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否触发规则：涉及周期、角速度、速度与半径幂律关系
    trigger_keywords = ['周期', '角速度', '速度', '轨道', '幂次', 'p', '指数', '关系']
    if not any(kw in question or kw in context for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未触发规则', 'evidence': ''}

    # 查找 prediction 或 answer 中的 p 值
    # 优先匹配 p = -1.5 或 -3/2

    p_match = re.search(r'p[=：]\s*([-+]?[0-9]*\.?[0-9]+|[-+]?(?:1/2|3/2|1\.5|1\.5))', prediction + ' ' + answer)
    if not p_match:
        return {'result': 'inconclusive', 'message': '未找到 p 值', 'evidence': ''}

    p_str = p_match.group(1).strip()
    p_value = None
    if p_str == '1.5' or p_str == '3/2':
        p_value = 1.5
    elif p_str == '-1.5' or p_str == '-3/2':
        p_value = -1.5
    else:
        try:
            p_value = float(p_str)
        except:
            return {'result': 'inconclusive', 'message': 'p 值无法解析', 'evidence': ''}

    # 校验 p 是否等于 -1.5
    if abs(p_value + 1.5) < 1e-6:
        return {'result': 'pass', 'message': 'p = -1.5 符合推导结果', 'evidence': p_match.group()}
    else:
        return {'result': 'fail', 'message': f'p = {p_value} ≠ -1.5', 'evidence': p_match.group()}

