# rule_id=exp_95cd256db8853fec | domain=Mechanics | topic=Gravitation and Kepler's Laws
def check_exp_95cd256db8853fec_90a78660f60f(sample: dict) -> dict:
    text = ""
    for key in ["question", "prediction", "answer", "context"]:
        if key in sample and isinstance(sample[key], str):
            text += sample[key] + " "

    if not text.strip():
        return {"result": "inconclusive", "message": "无文本可分析", "evidence": ""}

    # 检查是否包含 M/(M+m) 或类似形式
    # 优先匹配 M/(M+m) 或 (M+m)/M 等常见变体

    pattern = r'(?i)M\s*[/]\s*\(\s*M\s*\+\s*m\s*\)'
    if re.search(pattern, text):
        return {"result": "pass", "message": "检测到 M/(M+m) 修正项", "evidence": re.search(pattern, text).group()}

    # 检查是否包含折合质量公式 mu = (m1*m2)/(m1+m2)
    pattern2 = r'(?i)mu\s*=\s*\(\s*m1\s*\*\s*m2\s*\)\s*/\s*\(\s*m1\s*\+\s*m2\s*\)'
    if re.search(pattern2, text):
        return {"result": "pass", "message": "检测到折合质量公式", "evidence": re.search(pattern2, text).group()}

    # 检查是否包含 m/(M+m) 或 M/(M+m) 的变体
    pattern3 = r'(?i)\b(m|\w+)\s*[/]\s*\(\s*(m|\w+)\s*\+\s*(m|\w+)\s*\)'
    matches = re.findall(pattern3, text)
    for match in matches:
        if len(match) >= 3 and any(s.lower() in ['m', 'm1', 'm2', 'm_center', 'm_small'] for s in match):
            if any(s.lower() in ['m', 'm1', 'm2', 'm_center', 'm_small'] for s in match) and any(s.lower() in ['m', 'm1', 'm2', 'm_center', 'm_small'] for s in match):
                return {"result": "pass", "message": "检测到质量比修正项", "evidence": match[0] + "/(" + match[1] + "+" + match[2] + ")"}

    return {"result": "fail", "message": "未发现 M/(M+m) 或折合质量相关修正项", "evidence": ""}

# rule_id=exp_9fc33f6773002198 | domain=Mechanics | topic=Gravitation and Kepler's Laws
def check_exp_9fc33f6773002198_7e09bfe14d1c(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '')

    if 'satellite' not in question and 'orbit' not in question and 'table' not in question:
        return {'result': 'inconclusive', 'message': '未检测到轨道参数表格', 'evidence': ''}

    # 提取所有卫星的 a 和 T
    satellites = []
    lines = context.split('\n')
    for line in lines:
        line = line.strip()
        if not line or '|' not in line:
            continue
        parts = [p.strip() for p in line.split('|')]
        if len(parts) < 3:
            continue
        name = parts[0]
        try:
            a = float(parts[1])
            T = float(parts[2])
            if a > 0 and T > 0:
                satellites.append({'name': name, 'a': a, 'T': T})
        except ValueError:
            continue

    if len(satellites) < 2:
        return {'result': 'inconclusive', 'message': '卫星数据不足', 'evidence': ''}

    # 优先使用已知完整参数的卫星（如 WESTFORD）
    westford = None
    for s in satellites:
        if 'westford' in s['name'].lower():
            westford = s
            break

    if westford is None:
        # 若无 WESTFORD，使用第一个卫星作为参考
        ref = satellites[0]
    else:
        ref = westford

    # 计算参考卫星的 a^3 / T^2
    ref_value = (ref['a'] ** 3) / (ref['T'] ** 2)

    # 检查其他卫星是否满足 a^3 / T^2 ≈ ref_value
    tolerance = 1e-6
    for s in satellites:
        if s == ref:
            continue
        value = (s['a'] ** 3) / (s['T'] ** 2)
        if abs(value - ref_value) > tolerance * max(abs(value), abs(ref_value)):
            return {'result': 'fail', 'message': f'卫星 {s["name"]} 的 a^3/T^2 与参考值不一致', 'evidence': line}

    return {'result': 'pass', 'message': '所有卫星的 a^3/T^2 值一致', 'evidence': ''}

