def check_exp_bf221effe9e577a7_5489ba99afc5(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()
    text = question + ' ' + prediction + ' ' + context

    # 检查是否涉及远距离掠过场景
    if 'b >> gm/v²' not in text and 'b much greater than gm/v²' not in text and 'b >> gm/v^2' not in text:
        return {'result': 'inconclusive', 'message': '未触发远距离掠过条件', 'evidence': ''}

    # 查找偏转角公式形式：alpha = k * (G*M)/(b*v^2)
    # 使用正则匹配 alpha = k * (G*M)/(b*v^2) 或类似形式

    pattern = r'alpha[\s]*=[\s]*([0-9]+\.?[0-9]*)[\s]*\*\s*\(\s*G\s*\*\s*M\s*\)\s*/\s*\(\s*b\s*\*\s*v\s*\^\s*2\s*\)'
    match = re.search(pattern, text, re.IGNORECASE)

    if not match:
        return {'result': 'inconclusive', 'message': '未找到 alpha = k * (G*M)/(b*v^2) 形式', 'evidence': ''}

    k_str = match.group(1)
    try:
        k = float(k_str)
    except:
        return {'result': 'inconclusive', 'message': 'k 值无法解析', 'evidence': ''}

    # 检查 k 是否等于 2
    if abs(k - 2.0) < 1e-6:
        return {'result': 'pass', 'message': '系数 k = 2，符合牛顿近似', 'evidence': match.group(0)}
    else:
        return {'result': 'fail', 'message': f'系数 k = {k}，应为 2', 'evidence': match.group(0)}

