    # 匹配数字+单位的模式，如 100 kpc, 1.5 pc, 2 mpc, 1e10 pc
    pattern = r'([\d\.e]+)\s*([kmp]?pc|kpc|pc|mpc|Gpc|ly|km|m|cm|mm|\d+\s*km)'
    matches = re.findall(pattern, text, re.IGNORECASE)

    # 仅关注 kpc, pc, mpc, Gpc
    valid_units = {"kpc", "pc", "mpc", "gpc"}
    found_values = []
    for val, unit in matches:
        unit_lower = unit.strip().lower()
        if unit_lower in valid_units:
            try:
                num = float(val.replace('e', 'E'))
                # 转换为 pc 为单位
                if unit_lower == "kpc":
                    num *= 1e3
                elif unit_lower == "mpc":
                    num *= 1e6
                elif unit_lower == "gpc":
                    num *= 1e9
                # kpc 已经是 1e3 pc，无需额外转换
                found_values.append(num)
            except:
                continue

    # 若无有效值，返回 inconclusive
    if not found_values:
        return {"result": "inconclusive", "message": "未检测到有效物理量", "evidence": ""}

    # 检查是否超过 10^10 pc
    threshold = 1e10  # 10^10 pc
    for val in found_values:
        if val > threshold:
            result = "fail"
            message = f"物理量 {val:.2e} pc 超过宇宙尺度阈值 1e10 pc，可能存在建模错误"
            evidence = f"{val:.2e} pc"
            break

    if result == "inconclusive":
        result = "pass"
        message = "所有物理量在合理区间内"

    return {"result": result, "message": message, "evidence": evidence}

