    pattern4 = 'dp/dx\s*=\s*rho\s*\*\s*omega\s*\*\s*omega\s*\*\s*x'

    if any(pattern in text for pattern in [pattern1, pattern2, pattern3, pattern4]):
        return {'result': 'pass', 'message': '匹配旋转流体静力平衡方程', 'evidence': 'dP/dx = rho * omega^2 * x'}

    # 检查是否包含 dP = rho * a_n * dx，且 a_n = omega^2 * x
    if 'dp = rho * a_n * dx' in text and 'a_n = omega^2 * x' in text:
        return {'result': 'pass', 'message': '匹配径向受力平衡方程', 'evidence': 'dP = rho * a_n * dx'}

    # 检查是否包含向心加速度项 ω²x
    if 'omega\^2\s*\*\s*x' in text or 'omega\s*\*\s*omega\s*\*\s*x' in text:
        # 检查是否与压力梯度相关
        if 'dp/dx' in text or 'dP/dx' in text or 'pressure gradient' in text:
            return {'result': 'pass', 'message': '包含向心加速度项与压力梯度', 'evidence': 'omega^2 * x'}

    return {'result': 'inconclusive', 'message': '未发现关键方程或项', 'evidence': ''}

