# rule_id=exp_805aacd95cf88e8c | domain=Mechanics | topic=Non-inertial Reference Frames and Pseudo Forces
def check_exp_805aacd95cf88e8c_719ea78517b8(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
