# rule_id=exp_127b6ec1a50d272b | domain=Mechanics | topic=Fluid Statics (Buoyancy, Pressure in Fluids)
def check_exp_127b6ec1a50d272b_ef99b4322281(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否触发条件
    trigger_phrases = [
        '远方水面为 z=0',
        'far away from the board is on the x y plane with z=0'
    ]
    if not any(phrase in question or phrase in context for phrase in trigger_phrases):
        return {
            "result": "inconclusive",
            "message": "未触发无穷远场零势能约束条件",
            "evidence": ""
        }

    # 查找预测中可能的函数表达式
    # 优先匹配 z(x) 或 z(x) = ... 形式

    # 匹配 z(x) = ... 或 z(x) ~ ... 等形式
    pattern = r'z\s*\(\s*x\s*\)\s*=?\s*[^\n]*'
    matches = re.findall(pattern, prediction)
    if not matches:
        return {
            "result": "inconclusive",
            "message": "未找到 z(x) 的表达式",
            "evidence": ""
        }

    # 取第一个匹配
    expr = matches[0]
    # 简单检查是否包含极限行为
    # 检查是否包含 lim_{x->inf} z(x) = 0 或类似表达
    limit_pattern = r'lim\s*\{[^}]*x\s*->\s*inf[^}]*\}\s*.*?z\s*\(\s*x\s*\)\s*=\s*0'
    if re.search(limit_pattern, prediction):
        return {
            "result": "pass",
            "message": "检测到极限条件 lim_{x->inf} z(x) = 0，符合约束",
            "evidence": re.search(limit_pattern, prediction).group()
        }

    # 检查是否包含常数项 C 且未被消除
    # 若表达式中存在 C 且未被设为 0，可能违反约束
    # 但仅当表达式中存在 C 且无显式设为 0 时才怀疑
    # 简单判断：若表达式中含 C 且无 =0 或 =const 且 const=0
    if 'c' in expr or 'C' in expr:
        # 检查是否显式设为 0
        if re.search(r'c\s*=\s*0|C\s*=\s*0', expr):
            return {
                "result": "pass",
                "message": "常数项 C 显式设为 0，符合无穷远零势能约束",
                "evidence": re.search(r'c\s*=\s*0|C\s*=\s*0', expr).group()
            }
        else:
            return {
                "result": "fail",
                "message": "存在常数项 C 但未设为 0，违反无穷远零势能约束",
                "evidence": expr
            }

    # 若无 C 但表达式中无极限行为，保守判断
    # 仅当表达式中无 C 且无极限表达式时，视为可能符合
    # 但无明确证据，返回 inconclusive
    return {
        "result": "inconclusive",
        "message": "未检测到极限条件或常数项，无法确认是否满足约束",
        "evidence": ""
    }

# rule_id=exp_21553da9c3495765 | domain=Mechanics | topic=Fluid Statics (Buoyancy, Pressure in Fluids)
def check_exp_21553da9c3495765_968031db75f9(sample: dict) -> dict:
    content = (sample.get('question', '') + ' ' + sample.get('prediction', '') + ' ' + sample.get('context', '')).lower()

    # 检查是否涉及球冠、浮力、排水体积
    if not any(keyword in content for keyword in ['sphere', 'spherical', 'ball', 'buoy', 'displace', 'volume', 'submerged', 'crown', 'cap']):
        return {'result': 'inconclusive', 'message': '未涉及球冠或浮力相关计算', 'evidence': ''}

    # 检查是否出现 h_air 或类似表示露出高度的符号
    if 'h_air' not in content and 'height above' not in content and 'exposed' not in content:
        return {'result': 'inconclusive', 'message': '未识别露出高度符号', 'evidence': ''}

    # 检查公式中是否使用 h_air 直接代入排水体积公式
    # 期望公式：V_sub = π(2R - h_air)^2 / 3 * (3R - (2R - h_air))
    # 简化后：V_sub = π(2R - h_air)^2 / 3 * (R + h_air)
    # 若出现 h_air 且未用 2R - h_air 替代，则为错误
    # 检查是否出现 (2R - h_air) 或等价形式
    if '2r - h_air' in content or '2R - h_air' in content or '2r - h_{air}' in content or '2R - h_{air}' in content:
        return {'result': 'pass', 'message': '正确使用 2R - h_air 计算排水体积', 'evidence': '命中公式中 2R - h_air'}

    # 若出现 h_air 但未使用 2R - h_air，则为错误
    if 'h_air' in content or 'height above' in content or 'exposed' in content:
        return {'result': 'fail', 'message': '排水体积公式中应使用 2R - h_air，而非 h_air', 'evidence': '命中 h_air 但未使用 2R - h_air'}

    return {'result': 'inconclusive', 'message': '未检测到关键符号', 'evidence': ''}

