# rule_id=exp_8f890b31e0b9294a | domain=Mechanics | topic=Fluid Statics (Buoyancy, Pressure in Fluids)
def check_exp_8f890b31e0b9294a_c8a447a9d103(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    context = sample.get('context', '')
    answer = sample.get('answer', '')

    # 合并文本用于搜索
    text = (question + ' ' + prediction + ' ' + context + ' ' + answer).lower()

    # 检查是否提及 tan(beta) = s * tan(alpha)
    if 'tan(beta) = s * tan(alpha)' not in text and 'tan(beta) = s tan(alpha)' not in text:
        return {'result': 'inconclusive', 'message': '未提及目标公式', 'evidence': ''}

    # 提取 s 的值
    s_value = None
    # 尝试匹配 s = ... 形式

    s_match = re.search(r's\s*=\s*([-+]?\d*\.?\d+)', text)
    if s_match:
        try:
            s_value = float(s_match.group(1))
        except:
            pass

    if s_value is None:
        return {'result': 'inconclusive', 'message': '未提取到s的数值', 'evidence': ''}

    # 检查是否提及 rho_i 和 rho_w
    if 'rho_i' not in text or 'rho_w' not in text:
        return {'result': 'inconclusive', 'message': '未提及rho_i或rho_w', 'evidence': ''}

    # 检查是否提及岩石密度
    if 'rock' in text or 'density of rock' in text or 'rocks' in text:
        return {'result': 'fail', 'message': 's不应与岩石密度相关', 'evidence': 'rock'}

    # 检查是否提及冰面或底面压力补偿
    if 'ice' in text and 'compensate' in text:
        # 冰面补偿时s应为负或极小正值
        if s_value > 1e-6:
            return {'result': 'fail', 'message': '冰面补偿时s应为负或极小正值', 'evidence': 'ice compensate'}

    # 检查s是否符合 (rho_w - rho_i) / rho_i
    # 由于无法解析rho_i和rho_w的具体值，只能检查符号逻辑
    # 若s为正，应为 (rho_w - rho_i)/rho_i，即 rho_w > rho_i
    # 若s为负，应为 -(rho_w - rho_i)/rho_i，即 rho_w < rho_i
    # 但无法获取具体值，只能保守判断

    # 若s为正，且未提及冰面补偿，可接受
    # 若s为负，且提及冰面补偿，可接受
    # 但若s为负且未提及冰面补偿，可能有问题

    # 保守处理：若s为负且未提及冰面补偿，视为可疑
    if s_value < -1e-6 and 'ice' not in text and 'compensate' not in text:
        return {'result': 'fail', 'message': '负s值未提及冰面补偿，不符合物理逻辑', 'evidence': 'negative s without ice'}

    # 若s为正，且提及冰面补偿，可能错误
    if s_value > 1e-6 and ('ice' in text or 'compensate' in text):
        return {'result': 'fail', 'message': '正s值与冰面补偿矛盾', 'evidence': 'positive s with ice'}

    # 其他情况视为通过
    return {'result': 'pass', 'message': 's值符合密度差逻辑', 'evidence': ''}

