    if 'rate per volume' not in question and 'source term' not in question and 'alpha' not in question and 'injection' not in question:
        return {'result': 'inconclusive', 'message': '未提及源项或单位体积注入率', 'evidence': ''}

    # 检查是否要求列出连续性方程
    if 'continuity' not in question and 'conservation' not in question and 'mass balance' not in question:
        return {'result': 'inconclusive', 'message': '未要求列出连续性方程', 'evidence': ''}

    # 检查预测中是否出现标准形式：Phi_out - Phi_in = S * V
    standard_pattern = r'[a-z]+_out\s*[-+]\s*[a-z]+_in\s*=\s*[a-z]+\s*\*\s*[a-z]+'
    # 简化匹配：查找类似 "flux_out - flux_in = s * v" 的结构
    if any(keyword in prediction for keyword in ['flux', 'flow', 'phi', 'q']) and 'out' in prediction and 'in' in prediction and '=' in prediction and '*' in prediction:
        # 提取左右两边
        parts = prediction.split('=', 1)
        if len(parts) != 2:
            return {'result': 'inconclusive', 'message': '方程格式异常', 'evidence': ''}
        left, right = parts[0].strip(), parts[1].strip()

        # 检查左边是否为通量差
        if not any(x in left for x in ['out', 'in']) or '-' not in left:
            return {'result': 'inconclusive', 'message': '左侧非通量差形式', 'evidence': ''}

        # 检查右边是否为源项乘体积
        if not any(x in right for x in ['s', 'alpha', 'source', 'injection']) or '*' not in right or 'v' not in right:
            return {'result': 'inconclusive', 'message': '右侧非源项×体积形式', 'evidence': ''}

        # 确保源项未直接加在点通量中
        if any(x in prediction for x in ['+ alpha', '+ s', '+ source', '+ injection']) and 'flux' in prediction and 'out' in prediction and 'in' in prediction:
            return {'result': 'fail', 'message': '源项直接加在点通量中，违反通量差=源项×体积原则', 'evidence': prediction}

        return {'result': 'pass', 'message': '符合通量差 = 源项×体积的连续性方程形式', 'evidence': prediction}

    # 若未发现明显匹配，保守判断
    return {'result': 'inconclusive', 'message': '未检测到符合标准的方程形式', 'evidence': ''}

