# rule_id=exp_7ad380952c9d4b28 | domain=Mechanics | topic=Fluid Dynamics (Bernoulli's Equation, Continuity)
def check_exp_7ad380952c9d4b28_76aeb47f5b3e(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()
    text = question + ' ' + prediction + ' ' + context

    # 检查是否出现 P(t) 和压缩系数 c_r
    if 'p(t)' not in text and 'pressure(t)' not in text and 'p(t)' not in text:
        return {'result': 'inconclusive', 'message': '未检测到压力随时间变化', 'evidence': ''}
    if 'c_r' not in text and 'compressibility' not in text:
        return {'result': 'inconclusive', 'message': '未检测到压缩系数', 'evidence': ''}

    # 检查是否建立 dP/dt 与 q 的微分关系
    diff_relation = any(keyword in text for keyword in ['dp/dt', 'dP/dt', 'derivative of p', 'pressure derivative'])
    if not diff_relation:
        return {'result': 'fail', 'message': '未建立 dP/dt 与流量 q 的微分关系', 'evidence': ''}

    # 检查积分形式 t = integral(1/q(P) dP)
    integral_pattern = r't\s*=\s*integral\s*\(\s*1\s*/\s*q\s*\(\s*P\s*\)\s*\dP\s*\)'

    if not re.search(integral_pattern, text, re.IGNORECASE):
        return {'result': 'fail', 'message': '未发现 t = integral(1/q(P) dP) 的积分形式', 'evidence': ''}

    # 检查积分限是否对应初始与最终压力（或流量）的对数关系
    # 检查是否出现 log(P_final) - log(P_initial)
    log_pattern = r'log\s*\(\s*P\s*\S*\s*\)\s*[-+]\s*log\s*\(\s*P\s*\S*\s*\)'
    if not re.search(log_pattern, text, re.IGNORECASE):
        return {'result': 'fail', 'message': '积分限未体现初始与最终压力的对数关系', 'evidence': ''}

    return {'result': 'pass', 'message': '微分关系与积分限均符合要求', 'evidence': 't = integral(1/q(P) dP)'}

