# rule_id=exp_8ed96807516ece13 | domain=Mechanics | topic=Fluid Dynamics (Bernoulli's Equation, Continuity)
def check_exp_8ed96807516ece13_134a7a6f2e49(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()

    # 提取 M, V, rho
    M = None
    V = None
    rho = None

    # 从 context 或 question 中提取数值

    numbers = re.findall(r'\d+\.?\d*', question + ' ' + context)
    if len(numbers) >= 3:
        try:
            M = float(numbers[0])
            V = float(numbers[1])
            rho = float(numbers[2])
        except:
            return {'result': 'inconclusive', 'message': '数值解析失败', 'evidence': ''}

    if M is None or V is None or rho is None:
        return {'result': 'inconclusive', 'message': '缺少必要参数', 'evidence': ''}

    if V == 0:
        return {'result': 'inconclusive', 'message': '体积为零', 'evidence': ''}

    rho_avg = M / V

    # 判断升力方向
    if rho_avg > rho:
        expected_sign = 'up'
    elif rho_avg < rho:
        expected_sign = 'down'
    else:
        return {'result': 'inconclusive', 'message': '密度相等，无明确升力方向', 'evidence': ''}

    # 检查预测中是否包含方向
    if 'up' in prediction or 'upward' in prediction:
        actual_sign = 'up'
    elif 'down' in prediction or 'downward' in prediction:
        actual_sign = 'down'
    else:
        return {'result': 'inconclusive', 'message': '预测未明确升力方向', 'evidence': ''}

    if actual_sign == expected_sign:
        return {'result': 'pass', 'message': '升力方向符合密度比较规则', 'evidence': ''}
    else:
        return {'result': 'fail', 'message': f'升力方向错误：应{expected_sign}，但预测为{actual_sign}', 'evidence': ''}

# rule_id=exp_b00f7ad1b496103c | domain=Mechanics | topic=Fluid Dynamics (Bernoulli's Equation, Continuity)
def check_exp_b00f7ad1b496103c_f2372fa4cfbe(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否涉及旋转物体在流体中运动（马格努斯效应）且要求水平直线运动
    if 'rotation' not in question and 'magnus' not in question and 'spinning' not in question:
        return {'result': 'inconclusive', 'message': '未触发旋转流体运动条件', 'evidence': ''}

    if 'horizontal' not in question and 'straight' not in question and 'linear' not in question:
        return {'result': 'inconclusive', 'message': '未要求水平直线运动', 'evidence': ''}

    # 提取关键符号：M, rho, v, omega
    # 从 prediction 或 context 中尝试提取数值表达式

    # 匹配 M, rho, v, omega 的数值表达式
    def extract_value(text, symbol):
        pattern = rf'{symbol}\s*=[\s\d\-\.]+|{symbol}\s*\+?\s*[-\d\.]+|{symbol}\s*\*\s*[-\d\.]+|[-\d\.]+\s*{symbol}'
        matches = re.findall(pattern, text)
        for m in matches:
            # 简单提取数字
            nums = re.findall(r'[-+]?\d*\.?\d+', m)
            if nums:
                try:
                    return float(nums[0])
                except:
                    continue
        return None

    M = extract_value(prediction, 'm') or extract_value(context, 'm') or extract_value(prediction, 'M') or extract_value(context, 'M')
    rho = extract_value(prediction, 'rho') or extract_value(context, 'rho')
    v = extract_value(prediction, 'v') or extract_value(context, 'v')
    omega = extract_value(prediction, 'omega') or extract_value(context, 'omega')

    # 若缺少关键变量，返回 inconclusive
    if M is None or rho is None or v is None or omega is None:
        return {'result': 'inconclusive', 'message': '缺少关键物理量', 'evidence': ''}

    # 检查是否出现负的 omega
    if omega < 0:
        return {'result': 'fail', 'message': 'ω 为负，升力方向与实际受力需求相反', 'evidence': 'omega < 0'}

    # 检查是否满足方程：M*g - rho*V*g = rho*v*(2*pi*R^2*omega)*H
    # 但无 g, V, R, H，无法完整验证
    # 仅能基于 ω 符号判断

    # 若 ω 为正，且无其他矛盾，视为通过
    return {'result': 'pass', 'message': 'ω 为正，方向符合预期', 'evidence': 'omega > 0'}

