# rule_id=exp_e15f69732ba3b8e8 | domain=Mechanics | topic=Fluid Dynamics (Bernoulli's Equation, Continuity)
def check_exp_e15f69732ba3b8e8_50d57f0e1a26(sample: dict) -> dict:
    text = (sample.get('question', '') + ' ' + sample.get('prediction', '') + ' ' + sample.get('answer', '') + ' ' + sample.get('context', '')).lower()

    # 检查是否涉及球形物体的质量与阻力计算
    if not any(word in text for word in ['sphere', 'spherical', 'ball', 'raindrop', 'droplet', 'radius', 'diameter', 'volume', 'area', 'cross-sectional', 'resistance', 'drag']):
        return {'result': 'inconclusive', 'message': '未提及球体或相关物理量', 'evidence': ''}

    # 查找直径 d 和半径 r 的使用情况
    has_d = 'd=' in text or 'd =' in text or 'd = ' in text or 'diameter' in text
    has_r = 'r=' in text or 'r =' in text or 'r = ' in text or 'radius' in text

    # 检查是否同时使用了 d 和 r，且未统一
    if has_d and has_r:
        # 检查是否在体积和面积公式中使用了不一致的变量
        volume_formula = any(pattern in text for pattern in [
            '4/3*pi*r^3', '4/3*pi*r**3', '4/3*pi*(r)^3', '4/3*pi*r³',
            '4/3*pi*d^3/8', '4/3*pi*d**3/8', '4/3*pi*(d/2)^3', '4/3*pi*(d/2)**3',
            '4/3*pi*d³/8', '4/3*pi*(d/2)³'
        ])
        area_formula = any(pattern in text for pattern in [
            'pi*r^2', 'pi*r**2', 'pi*(r)^2', 'pi*r²',
            'pi*d^2/4', 'pi*d**2/4', 'pi*(d/2)^2', 'pi*(d/2)**2',
            'pi*d²/4', 'pi*(d/2)²'
        ])

        # 如果体积用 r，面积用 d，或反之，可能不一致
        if volume_formula and area_formula:
            # 检查是否在体积中用了 r，面积中用了 d
            if ('4/3*pi*r' in text and 'pi*d' in text) or ('4/3*pi*(r)' in text and 'pi*(d/2)' in text):
                return {'result': 'fail', 'message': '体积用半径 r，阻力用直径 d，不一致', 'evidence': '体积公式使用 r，面积公式使用 d'}
            # 检查是否在体积中用了 d，面积中用了 r
            if ('4/3*pi*d' in text and 'pi*r' in text) or ('4/3*pi*(d/2)' in text and 'pi*(r)' in text):
                return {'result': 'fail', 'message': '体积用直径 d，阻力用半径 r，不一致', 'evidence': '体积公式使用 d，面积公式使用 r'}

    # 检查是否在公式中使用了 (d/2) 作为半径
    consistent_with_d2 = any(pattern in text for pattern in [
        '4/3*pi*(d/2)^3', '4/3*pi*(d/2)**3', '4/3*pi*(d/2)³',
        'pi*(d/2)^2', 'pi*(d/2)**2', 'pi*(d/2)²'
    ])

    # 如果体积和面积都使用 (d/2)，则一致
    if consistent_with_d2:
        return {'result': 'pass', 'message': '体积与面积均使用 (d/2)，几何一致', 'evidence': '使用 (d/2) 作为半径'}

    # 检查是否在体积中使用 r，面积中使用 r
    if any(pattern in text for pattern in ['4/3*pi*r^3', '4/3*pi*r**3', '4/3*pi*r³']) and any(pattern in text for pattern in ['pi*r^2', 'pi*r**2', 'pi*r²']):
        return {'result': 'pass', 'message': '体积与面积均使用半径 r，几何一致', 'evidence': '使用 r 作为半径'}

    # 保守处理：无法判断
    return {'result': 'inconclusive', 'message': '无法确认几何参数一致性', 'evidence': ''}

# rule_id=exp_e540317efbc5369d | domain=Mechanics | topic=Fluid Dynamics (Bernoulli's Equation, Continuity)
def check_exp_e540317efbc5369d_b14d72657319(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()
    text = question + ' ' + prediction + ' ' + context

    # 检查是否同时出现伯努利方程和静水压公式
    bernoulli_keywords = ['p + rho g h', 'p + \rho g h', 'bernoulli', 'p + 1/2 rho v^2']
    hydrostatic_keywords = ['p = p_a + rho g h', 'p = p_a + \rho g h', 'p = p_0 + rho g h']

    bernoulli_found = any(kw in text for kw in bernoulli_keywords)
    hydrostatic_found = any(kw in text for kw in hydrostatic_keywords)

    if not (bernoulli_found and hydrostatic_found):
        return {
            "result": "inconclusive",
            "message": "未同时出现伯努利方程和静水压公式",
            "evidence": ""
        }

    # 检查压力项是否重复
    # 若 P 已表示某点压力（含 ρgh 贡献），则不应再在伯努利中出现 ρgh
    # 检查是否存在 P + ρgh 且 P 已包含液面下高度项
    # 通过关键词判断：若出现 P = P_a + ρgh 且 P 在伯努利中又出现 ρgh，则可能冗余
    # 保守判断：若 P 在伯努利中出现，且 P 被定义为含 ρgh 的形式，则视为冗余
    # 检查 P 是否被定义为 P = P_a + ρgh
    p_defines_rho_gh = any(kw in text for kw in ['p = p_a + rho g h', 'p = p_a + \rho g h', 'p = p_0 + rho g h'])
    bernoulli_with_p_rho_gh = 'p + rho g h' in text or 'p + \rho g h' in text

    if p_defines_rho_gh and bernoulli_with_p_rho_gh:
        # 检查是否在伯努利中同时出现 P 和 ρgh
        # 若 P 已包含 ρgh，再加 ρgh 即为冗余
        # 保守判断：若 P 被定义为含 ρgh，且伯努利中出现 P + ρgh，则视为冗余
        # 但需确认 P 是否代表“某点压力”
        # 通过上下文判断：若 P 被定义为“某点压力”或“液面下压力”，则视为已含 ρgh
        point_pressure_keywords = ['point', 'below surface', 'depth', 'h', 'under', 'submerged']
        if any(kw in text for kw in point_pressure_keywords):
            return {
                "result": "fail",
                "message": "压力项重复：P 已包含液柱高度贡献，不应再加 ρgh",
                "evidence": "P = P_a + ρgh 且在伯努利中出现 P + ρgh"
            }

    return {
        "result": "inconclusive",
        "message": "未发现明确的重复项或上下文不足",
        "evidence": ""
    }

