# rule_id=exp_3fe1143b5b1ddb6d | domain=Mechanics | topic=Oscillations and Simple Harmonic Motion
def check_exp_3fe1143b5b1ddb6d_535831f70f61(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否涉及恒力场中的简谐运动
    if 'gravity' not in prediction and 'constant force' not in prediction and 'slope' not in prediction:
        return {'result': 'inconclusive', 'message': '未提及恒力场场景', 'evidence': ''}

    # 检查是否使用了正确的位移定义：相对于平衡位置
    # 关键模式：F = -k(x + x0) + F_ext = -kx
    # 或等价形式：位移x定义为相对于平衡位置
    patterns = [
        r'f\s*=\s*-k\s*\(x\s*\+\s*x_0\)\s*\+\s*f_ext\s*=\s*-k\s*x',
        r'x\s*is\s*displacement\s*from\s*equilibrium',
        r'x\s*measured\s*from\s*equilibrium',
        r'x_0\s*is\s*the\s*equilibrium\s*displacement',
        r'net\s*force\s*=\s*-k\s*\(x\s*\+\s*x_0\)\s*\+\s*F_ext',
        r'f_net\s*=\s*-k\s*\(x\s*\+\s*x_0\)\s*\+\s*f_ext',
        r'x\s*is\s*relative\s*to\s*equilibrium',
        r'x\s*is\s*displacement\s*from\s*zero\s*net\s*force',
        r'equilibrium\s*position\s*is\s*at\s*x\s*=\s*-x_0',
        r'x_0\s*is\s*the\s*shift\s*due\s*to\s*constant\s*force'
    ]

    # 检查预测中是否包含关键表达式
    found = False
    evidence = ''
    for pattern in patterns:
        if any(match in prediction for match in [pattern, pattern.replace('x', 'x_0'), pattern.replace('k', 'k'), pattern.replace('f_ext', 'F_ext')]):
            found = True
            evidence = pattern
            break

    if not found:
        # 检查上下文
        for pattern in patterns:
            if any(match in context for match in [pattern, pattern.replace('x', 'x_0'), pattern.replace('k', 'k'), pattern.replace('f_ext', 'F_ext')]):
                found = True
                evidence = pattern
                break

    if found:
        return {'result': 'pass', 'message': '位移定义为相对于平衡位置', 'evidence': evidence}
    else:
        return {'result': 'fail', 'message': '位移未定义为相对于平衡位置', 'evidence': ''}

