# rule_id=exp_9037b945723355c9 | domain=Mechanics | topic=Oscillations and Simple Harmonic Motion
def check_exp_9037b945723355c9_6807b64c6369(sample: dict) -> dict:
    result = "inconclusive"
    message = ""
    evidence = ""

    text = (sample.get("prediction", "") + " " + sample.get("context", "") + " " + sample.get("answer", "")).lower()

    # 检查是否提及振幅等差递减
    if "振幅" in text and ("等差" in text or "线性" in text or "等量减少" in text):
        # 提取关键参数：μ, m, g, k

        mu_match = re.search(r"(\d+\.?\d*)\s*\*?\s*mu", text)
        m_match = re.search(r"(\d+\.?\d*)\s*\*?\s*m", text)
        g_match = re.search(r"(\d+\.?\d*)\s*\*?\s*g", text)
        k_match = re.search(r"(\d+\.?\d*)\s*\*?\s*k", text)

        if mu_match and m_match and g_match and k_match:
            try:
                mu = float(mu_match.group(1))
                m = float(m_match.group(1))
                g = float(g_match.group(1))
                k = float(k_match.group(1))
                expected_delta = 4 * mu * m * g / k

                # 检查是否提及每半个周期振幅减少量为 4μmg/k
                pattern = r"(\d+\.?\d*)\s*\*?\s*4\s*\*?\s*mu\s*\*?\s*m\s*\*?\s*g\s*\/\s*k"
                if re.search(pattern, text):
                    result = "pass"
                    message = "振幅线性衰减，每半周期减少量符合 4μmg/k"
                    evidence = re.search(pattern, text).group(0)
                else:
                    # 检查是否提及减少量为常数
                    const_decrease = re.search(r"(\d+\.?\d*)\s*\*?\s*常数", text)
                    if const_decrease:
                        result = "pass"
                        message = "振幅等差递减，减少量为常数"
                    else:
                        result = "fail"
                        message = "未明确提及振幅等差递减或减少量公式"
            except:
                result = "inconclusive"
                message = "参数解析失败"
        else:
            result = "inconclusive"
            message = "关键参数未完整提取"
    else:
        result = "inconclusive"
        message = "未提及振幅等差递减特征"

    return {
        "result": result,
        "message": message,
        "evidence": evidence
    }

# rule_id=exp_a84bda60eb4c269f | domain=Mechanics | topic=Oscillations and Simple Harmonic Motion
def check_exp_a84bda60eb4c269f_87edb7b2eca0(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()

    # 检查触发条件：是否涉及加速度表达为位移或时间函数，且有弹簧或恒力系统
    trigger_keywords = ['acceleration', 'a =', 'a as function of', 'spring', 'constant force', 'k', 'f']
    if not any(kw in question or kw in context for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未触发规则条件', 'evidence': ''}

    # 检查是否直接使用 F_net = ma
    if 'f_net = m*a' in prediction or 'f = m*a' in prediction or 'newton' in prediction and 'second law' in prediction:
        return {'result': 'fail', 'message': '不应直接使用牛顿第二定律，应优先建立 a 与 (L_current - L_0) 的线性关系', 'evidence': 'F_net = ma'}

    # 检查是否优先使用 a 与 (x_target - x_current) 的线性关系
    # 期望形式：a = (k/m)*(x_target - x_current) - f/m
    expected_pattern = r'a\s*=\s*\(k/m\)\s*\*\s*\(x_target\s*-*\s*x_current\)\s*-*\s*f/m'
    if not any(pattern in prediction for pattern in [expected_pattern, 'a = (k/m)*(x_target - x_current) - f/m']):
        return {'result': 'fail', 'message': '未优先使用 a 与 (x_target - x_current) 的线性关系', 'evidence': prediction}

    return {'result': 'pass', 'message': '符合动力学变量替换优先律', 'evidence': expected_pattern}

