def check_exp_b204fa9b150ca0f9_b300698fda83(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    combined_text = question + ' ' + prediction + ' ' + answer + ' ' + context

    # 检查是否包含关键符号
    required_symbols = {'k', 'm', 'u', 'N'}
    found_symbols = set()
    for char in combined_text:
        if char.isalpha() and char in 'kmuN':
            found_symbols.add(char)

    if not required_symbols.issubset(found_symbols):
        return {
            "result": "inconclusive",
            "message": "缺少必要符号 k, m, u, N",
            "evidence": ""
        }

    # 检查是否包含标准能量守恒方程
    canonical_eq = "1/2 * k * A^2 = 1/2 * k * (x_0 - x_e)^2 + 1/2 * m * u^2"
    if canonical_eq not in combined_text:
        return {
            "result": "fail",
            "message": "未发现标准能量守恒方程",
            "evidence": ""
        }

    # 简单数值匹配：检查方程结构是否一致
    left_side = "1/2 * k * A^2"
    right_side = "1/2 * k * (x_0 - x_e)^2 + 1/2 * m * u^2"

    if left_side not in combined_text or right_side not in combined_text:
        return {
            "result": "inconclusive",
            "message": "方程结构不完整",
            "evidence": ""
        }

    # 检查是否有明显错误表达（如等号两边不等）
    if "1/2 * k * A^2" in combined_text and "1/2 * k * (x_0 - x_e)^2 + 1/2 * m * u^2" in combined_text:
        return {
            "result": "pass",
            "message": "能量守恒方程正确匹配",
            "evidence": canonical_eq
        }

    return {
        "result": "inconclusive",
        "message": "无法确认方程匹配",
        "evidence": ""
    }

