    # 检查是否在撤去力瞬间满足 x=0 且 v=0
    if '撤去瞬间' in prediction and 'x=0' in prediction and 'v=0' in prediction:
        return {'result': 'pass', 'message': '符合恒力作用下SHM平衡位置偏移规则', 'evidence': prediction}

    # 若未明确提及撤去瞬间条件，但整体逻辑合理，保守判断
