# rule_id=exp_e4b0abf1359e2acc | domain=Mechanics | topic=Oscillations and Simple Harmonic Motion
def check_exp_e4b0abf1359e2acc_62f0ee7219e2(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否涉及弹簧、简谐运动或圆周运动
    keywords = ['弹簧', '简谐运动', '圆周运动', 'oscillation', 'harmonic', 'circular']
    if not any(kw in question or kw in context for kw in keywords):
        return {'result': 'inconclusive', 'message': '未涉及目标物理场景', 'evidence': ''}

    # 检查是否询问时间或次数
    time_keywords = ['时间', 't=', 'time', 'how long', 'duration', 'period', 'cycle', '次数', 'number']
    if not any(kw in question for kw in time_keywords):
        return {'result': 'inconclusive', 'message': '未询问时间或次数', 'evidence': ''}

    # 检查预测或答案中是否包含周期因子 nT 或 2n*pi
    # 匹配 n*T, n·T, n*T, 2n*pi, 2n*π, 2nπ

    pattern1 = r'\bn\s*\*?\s*[tT]\b|\bn\s*\*?\s*\(\s*[tT]\s*\)\b|\bn\s*\*?\s*2\s*\*?\s*\pi\b|\bn\s*\*?\s*2\s*\*?\s*π\b|\b2n\s*\*?\s*\pi\b|\b2n\s*\*?\s*π\b'
    pattern2 = r'\bn\s*\*?\s*[tT]\s*\*?\s*n\b|\bn\s*\*?\s*2\s*\*?\s*\pi\s*\*?\s*n\b'

    # 检查预测或答案中是否包含 nT 或 2nπ
    found = False
    if re.search(pattern1, prediction) or re.search(pattern1, answer):
        found = True
    elif re.search(pattern2, prediction) or re.search(pattern2, answer):
        found = True

    # 检查是否初始与末态相同（隐含周期性）
    # 常见描述：回到原点、回到起点、完成一次循环等
    cycle_keywords = ['回到原点', '回到起点', '初始位置', '相同状态', '周期性', '循环', '重复', 'once', 'back to start']
    is_cycle = any(kw in context or kw in question for kw in cycle_keywords)

    # 若为循环过程，应有 nT 或 2nπ
    if is_cycle and not found:
        return {'result': 'fail', 'message': '循环过程未体现周期整数倍', 'evidence': prediction or answer}
    elif not is_cycle and found:
        return {'result': 'fail', 'message': '非循环过程错误引入周期因子', 'evidence': prediction or answer}
    elif found or is_cycle:
        return {'result': 'pass', 'message': '周期因子使用合理', 'evidence': prediction or answer}
    else:
        return {'result': 'inconclusive', 'message': '无法判断周期性与因子使用关系', 'evidence': ''}

