    if 'period' not in prediction and 't = ' not in prediction and 't = 2' not in prediction:
        return {'result': 'inconclusive', 'message': '未提及周期公式', 'evidence': ''}

    # 检查是否包含修正等效摆长 l' = l * M / (M + m)
    # 优先匹配公式结构
    canonical_pattern = r'2\s*\*\s*pi\s*\*\s*sqrt\(\s*(M\s*\*\s*l)\s*/\s*\(\s*(M\s*\+\s*m)\s*\*\s*g\s*\)\s*\)'

    if re.search(canonical_pattern, prediction, re.IGNORECASE):
        return {'result': 'pass', 'message': '正确使用修正等效摆长公式', 'evidence': re.search(canonical_pattern, prediction, re.IGNORECASE).group()}

    # 检查是否包含 M/(M+m) 的形式
    if re.search(r'\bM\s*\*\s*l\s*/\s*\(\s*M\s*\+\s*m\s*\)', prediction, re.IGNORECASE):
        return {'result': 'pass', 'message': '包含修正项 M*l/(M+m)', 'evidence': re.search(r'\bM\s*\*\s*l\s*/\s*\(\s*M\s*\+\s*m\s*\)', prediction, re.IGNORECASE).group()}

    # 检查是否错误地使用了原始摆长
    if re.search(r'2\s*\*\s*pi\s*\*\s*sqrt\(\s*l\s*/\s*g\s*\)', prediction, re.IGNORECASE):
        return {'result': 'fail', 'message': '未修正等效摆长，使用原始 l', 'evidence': re.search(r'2\s*\*\s*pi\s*\*\s*sqrt\(\s*l\s*/\s*g\s*\)', prediction, re.IGNORECASE).group()}

    return {'result': 'inconclusive', 'message': '未发现有效公式匹配', 'evidence': ''}

