# rule_id=exp_6e32a9193903f71b | domain=Mechanics | topic=Normal Modes and Coupled Oscillations
def check_exp_6e32a9193903f71b_45e8a0db3a87(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()
    text = question + ' ' + prediction + ' ' + context

    # 检查是否提及拉格朗日力学和小振幅摆动
    if 'lagrangian' not in text and 'lagrange' not in text:
        return {'result': 'inconclusive', 'message': '未提及拉格朗日力学', 'evidence': ''}
    if 'small angle' not in text and 'small oscillation' not in text and 'small amplitude' not in text:
        return {'result': 'inconclusive', 'message': '未提及小角条件', 'evidence': ''}

    # 检查是否在求导前或求导后立即进行 sinθ≈θ 和 cosθ≈1
    # 关键词：求导前、求导后、before differentiation、after differentiation
    before_diff = 'before differentiation' in text or 'prior to differentiation' in text or 'before taking derivative' in text
    after_diff = 'after differentiation' in text or 'post differentiation' in text or 'after taking derivative' in text

    # 检查是否出现 sin(theta) ≈ theta 或 cos(theta) ≈ 1
    has_sin_approx = 'sin(theta)' in text and ('approx' in text or 'approximate' in text or '≈' in text or '=' in text) and ('theta' in text or 'angle' in text)
    has_cos_approx = 'cos(theta)' in text and ('approx' in text or 'approximate' in text or '≈' in text or '=' in text) and ('1' in text or 'unity' in text)

    # 检查是否出现 dot(theta)^2 * sin(theta) 且未被忽略
    has_high_order_term = 'dot(theta)' in text and 'sin(theta)' in text and 'dot(theta)^2 * sin(theta)' in text
    has_ignore = 'ignore' in text or 'neglect' in text or 'drop' in text or 'zero' in text or 'set to zero' in text

    # 如果存在高阶项但未被忽略，则失败
    if has_high_order_term and not has_ignore:
        return {'result': 'fail', 'message': '未忽略 dot(theta)^2 * sin(theta) 三阶小量', 'evidence': 'dot(theta)^2 * sin(theta)'}

    # 如果有近似但不在求导前后，则失败
    if (has_sin_approx or has_cos_approx) and not (before_diff or after_diff):
        return {'result': 'fail', 'message': '小角近似未在求导前后进行', 'evidence': 'sin(theta) ≈ theta or cos(theta) ≈ 1'}

    # 如果有近似且在求导前后，且高阶项被忽略，则通过
    if (has_sin_approx or has_cos_approx) and (before_diff or after_diff):
        return {'result': 'pass', 'message': '小角近似在求导前后进行，高阶项已忽略', 'evidence': ''}

    return {'result': 'inconclusive', 'message': '未检测到足够信息', 'evidence': ''}

# rule_id=exp_c0443782dfbd5be2 | domain=Mechanics | topic=Normal Modes and Coupled Oscillations
def check_exp_c0443782dfbd5be2_4fcbb485b3a5(sample: dict) -> dict:
    text = (sample.get('prediction', '') + ' ' + sample.get('context', '')).lower()
    if not text.strip():
        return {'result': 'inconclusive', 'message': '无输入文本', 'evidence': ''}

    # 检查是否提及 N 个物体和 N-1 个弹簧

    n_match = re.search(r'(\d+\b)\s*物体', text)
    if not n_match:
        return {'result': 'inconclusive', 'message': '未识别物体数量', 'evidence': ''}
    n = int(n_match.group(1))
    if n < 2:
        return {'result': 'inconclusive', 'message': '物体数不足2', 'evidence': ''}

    # 检查端点受力公式
    expected_left = f'f_1 = -k_1(x_1 - x_2)'
    expected_right = f'f_n = -k_{n-1}(x_n - x_{n-1})'
    if not (expected_left in text or expected_right in text):
        return {'result': 'fail', 'message': '端点受力公式缺失', 'evidence': ''}

    # 检查中间物体受两个弹簧力
    middle_pattern = re.compile(r'f_\d+\s*=\s*[^\n]+\s*\+\s*[^\n]+')
    middle_matches = middle_pattern.findall(text)
    if len(middle_matches) < n - 2:
        return {'result': 'fail', 'message': '中间物体受力数量不足', 'evidence': ''}

    # 检查力与位移差成正比
    force_diff_pattern = re.compile(r'f_\d+\s*=\s*-[k_\d+|k]\s*\(x_\d+\s*[-+]\s*x_\d+\)')
    if not force_diff_pattern.search(text):
        return {'result': 'fail', 'message': '力未正比于位移差', 'evidence': ''}

    return {'result': 'pass', 'message': '边界受力校验通过', 'evidence': expected_left + ' ' + expected_right}

# rule_id=exp_0bef14df033d965d | domain=Mechanics | topic=Elasticity and Hooke's Law
def check_exp_0bef14df033d965d_a028cc051dc7(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否提及均匀形变、应变、质量、长度、动能
    if 'uniform' not in question and 'uniform' not in prediction and 'uniform' not in context:
        return {'result': 'inconclusive', 'message': '未提及均匀形变', 'evidence': ''}
    if 'strain' not in question and 'strain' not in prediction and 'strain' not in context:
        return {'result': 'inconclusive', 'message': '未提及应变', 'evidence': ''}
    if 'mass' not in question and 'mass' not in prediction and 'mass' not in context:
        return {'result': 'inconclusive', 'message': '未提及质量', 'evidence': ''}
    if 'length' not in question and 'length' not in prediction and 'length' not in context:
        return {'result': 'inconclusive', 'message': '未提及长度', 'evidence': ''}
    if 'kinetic energy' not in question and 'kinetic energy' not in prediction and 'kinetic energy' not in context:
        return {'result': 'inconclusive', 'message': '未提及动能', 'evidence': ''}

    # 提取 m, L, dε/dt

    m_match = re.search(r'(?:mass|mass\s*=|m\s*=|m\s*=|m\s*=)\s*([\d\.]+)', prediction + ' ' + context)
    L_match = re.search(r'(?:length|length\s*=|L\s*=|L\s*=|L\s*=)\s*([\d\.]+)', prediction + ' ' + context)
    de_dt_match = re.search(r'(?:d\varepsilon/dt|d\varepsilon/dt|\dot\varepsilon|d\varepsilon/dt|\dot{\varepsilon}|\dot{\varepsilon})\s*=\s*([\d\.]+)', prediction + ' ' + context)

    if not m_match or not L_match or not de_dt_match:
        return {'result': 'inconclusive', 'message': '未提取到 m, L, dε/dt', 'evidence': ''}

    m = float(m_match.group(1))
    L = float(L_match.group(1))
    de_dt = float(de_dt_match.group(1))

    # 计算理论动能 K = (1/24) * m * L^2 * (dε/dt)^2
    theoretical_k = (1/24) * m * L**2 * de_dt**2

    # 尝试从 prediction 或 answer 中提取数值
    pred_k_match = re.search(r'([\d\.]+)\s*(?:joule|j|joules)', prediction)
    ans_k_match = re.search(r'([\d\.]+)\s*(?:joule|j|joules)', answer)

    if not pred_k_match and not ans_k_match:
        return {'result': 'inconclusive', 'message': '未提取到动能数值', 'evidence': ''}

    pred_k = float(pred_k_match.group(1)) if pred_k_match else None
    ans_k = float(ans_k_match.group(1)) if ans_k_match else None

    # 使用 prediction 或 answer 中的数值
    observed_k = pred_k if pred_k is not None else ans_k

    # 比较数值是否接近（允许 10% 误差）
    if abs(observed_k - theoretical_k) / theoretical_k < 0.1:
        return {'result': 'pass', 'message': '动能建模正确', 'evidence': prediction if pred_k_match else answer}
    else:
        return {'result': 'fail', 'message': '动能建模错误', 'evidence': prediction if pred_k_match else answer}

# rule_id=exp_2db19cba5d2a7743 | domain=Mechanics | topic=Elasticity and Hooke's Law
def check_exp_2db19cba5d2a7743_bdfef4144231(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()

    # 合并文本用于搜索
    text = question + ' ' + prediction + ' ' + context

    # 检查是否包含单位体积能量密度表达式 u = 1/2 * E * ε²
    has_energy_density = any(pattern in text for pattern in [
        '1/2 * e * ε^2', '1/2 * e * ε²', '1/2 * e * epsilon^2',
        '0.5 * e * ε^2', '0.5 * e * ε²', '0.5 * e * epsilon^2',
        '1/2 * e * (epsilon)^2', '1/2 * e * ε**2', '1/2 * e * ε^2'
    ])

    # 检查是否乘以总体积 V 或使用 m/ρ 代换
    has_volume_term = any(pattern in text for pattern in [
        'v', 'volume', 'total volume', 'm / ρ', 'mass / density',
        'm / rho', 'mass / rho', 'm / density', 'm / ρ',
        'multiply by volume', 'multiplied by v', 'multiplied by m / ρ'
    ])

    # 检查是否同时满足能量密度和体积项
    if not has_energy_density:
        return {
            "result": "fail",
            "message": "未发现单位体积能量密度表达式 u = 1/2 * E * ε²",
            "evidence": ""
        }

    if not has_volume_term:
        return {
            "result": "fail",
            "message": "未发现总体积 V 或 m/ρ 代换项",
            "evidence": ""
        }

    # 检查是否使用 m/ρ 代换 V，且 E, ε, m, ρ 均出现
    required_symbols = ['e', 'ε', 'ε²', 'ε^2', 'epsilon', 'm', 'ρ', 'rho', 'density', 'mass']
    symbol_count = sum(1 for sym in required_symbols if any(s in text for s in [sym, sym.replace('ε', 'epsilon')]))

    if symbol_count < 4:
        return {
            "result": "inconclusive",
            "message": "符号数量不足，无法确认完整性",
            "evidence": ""
        }

    # 检查是否出现 m/ρ 代换
    has_mass_density_sub = 'm / ρ' in text or 'm / rho' in text or 'mass / density' in text

    if not has_mass_density_sub:
        return {
            "result": "fail",
            "message": "未使用 m/ρ 代换总体积 V，且未明确给出 V",
            "evidence": ""
        }

    # 最终通过
    return {
        "result": "pass",
        "message": "正确使用能量密度 u = 1/2 * E * ε² 乘以 m/ρ 代换体积",
        "evidence": "u = 1/2 * E * ε² * (m / ρ)"
    }

