# rule_id=exp_36ae2d8c062c5e57 | domain=Mechanics | topic=Center of Mass and Motion of Extended Bodies
def check_exp_36ae2d8c062c5e57_15815cc55103(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否涉及阻力 f = -kv 且物体从静止开始最终停止
    has_resistance = any(keyword in question or keyword in prediction or keyword in context
                         for keyword in ['f = -kv', 'resistance proportional to velocity', 'drag force -kv'])
    starts_stops = any(keyword in question or keyword in prediction or keyword in context
                       for keyword in ['from rest', 'initially at rest', 'comes to rest', 'final velocity zero'])

    if not (has_resistance and starts_stops):
        return {
            "result": "inconclusive",
            "message": "未检测到阻力系统或初末静止条件",
            "evidence": ""
        }

    # 检查是否提及动量变化为零且无外力
    has_zero_momentum_change = any(keyword in question or keyword in prediction or keyword in context
                                   for keyword in ['initial momentum zero', 'final momentum zero', 'delta p = 0', 'momentum conserved'])
    no_external_force = any(keyword in question or keyword in prediction or keyword in context
                             for keyword in ['no external force', 'no other forces', 'only internal forces'])

    if not (has_zero_momentum_change and no_external_force):
        return {
            "result": "inconclusive",
            "message": "未明确动量变化为零或无外力条件",
            "evidence": ""
        }

    # 检查是否得出位移为零的结论
    displacement_zero = any(keyword in prediction or keyword in answer
                             for keyword in ['displacement is zero', 'delta x = 0', 'total displacement zero', 'x = 0'])

    if not displacement_zero:
        return {
            "result": "fail",
            "message": "未正确推导出位移为零的结论",
            "evidence": "prediction or answer does not state displacement is zero"
        }

    # 检查是否基于动量定理和阻力积分推导
    momentum_integral = any(keyword in prediction or keyword in context
                             for keyword in ['integral of force dt', 'impulse', 'int (f dt) = delta p', 'int v dt = 0'])

    if not momentum_integral:
        return {
            "result": "inconclusive",
            "message": "未体现动量定理积分推导过程",
            "evidence": ""
        }

    return {
        "result": "pass",
        "message": "正确应用动量定理推导出位移为零",
        "evidence": "f = -kv, initial and final velocity zero, no external force, implies delta x = 0"
    }

