    trigger_keywords = ['总能量', '总人口', '持续时间', '时间', '分配', '每人', '人均']
    if not any(kw in question or kw in prediction or kw in context for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未触发条件', 'evidence': ''}

    # 查找能量和功率单位
    energy_units = {'joule', 'j', 'kj', 'kjoule', 'kilojoule', 'watt-second', 'ws'}
    power_units = {'watt', 'w', 'kw', 'kilowatt', 'kilo-watt'}

    # 提取所有数字+单位的组合

    pattern = r'(-?\d+\.?\d*)\s*([a-zA-Z]+)'
    matches = re.findall(pattern, prediction + ' ' + context)

    energy_found = False
    power_found = False

    for value, unit in matches:
        unit_clean = unit.strip().lower()
        if unit_clean in energy_units:
            energy_found = True
        if unit_clean in power_units:
            power_found = True

    # 检查是否同时存在能量和功率单位
    if not energy_found or not power_found:
        return {'result': 'fail', 'message': '缺少能量或功率单位', 'evidence': ''}

    # 检查公式结构：T = E / (N * P)
    formula_keywords = ['t', 'time', 'duration', 'total energy', 'total population', 'power', 'per person']
    if not any(kw in prediction or kw in context for kw in formula_keywords):
        return {'result': 'inconclusive', 'message': '未发现公式结构', 'evidence': ''}

    # 检查是否出现 E / (N * P) 形式
    # 简单匹配：E / (N * P) 或类似表达
    if re.search(r'([eE][^\s]*|total\s*energy|energy)\s*[/÷]\s*\([^\s]*n[^\s]*\s*\*\s*[^\s]*p[^\s]*\)', prediction + ' ' + context):
        return {'result': 'pass', 'message': '单位一致且公式结构正确', 'evidence': ''}

    # 检查是否出现 E / N / P 形式（等价于 E / (N * P)）
    if re.search(r'([eE][^\s]*|total\s*energy)\s*[/÷]\s*[^\s]*n[^\s]*\s*[/÷]\s*[^\s]*p[^\s]*', prediction + ' ' + context):
        return {'result': 'pass', 'message': '单位一致且公式结构正确', 'evidence': ''}

    return {'result': 'fail', 'message': '公式结构不匹配', 'evidence': ''}

