    context = sample.get('context', '').lower()

    # 检查是否涉及量级估算
    if 'order of magnitude' not in question and 'order of magnitude' not in prediction:
        return {'result': 'inconclusive', 'message': '未触发量级估算条件', 'evidence': ''}

    # 检查是否提供特定模型数据（如E0, h, I(t)）
    required_symbols = ['e0', 'h', 'i(t)', 'integrate', 'integral']
    has_data = all(sym in context for sym in required_symbols)
    if not has_data:
        return {'result': 'inconclusive', 'message': '未提供必要模型数据', 'evidence': ''}

    # 检查预测中是否使用了题干中的物理量
    used_symbols = [sym for sym in ['e0', 'h', 'i(t)', 'integrate', 'integral'] if sym in prediction]
    if len(used_symbols) < 3:
        return {'result': 'fail', 'message': '未优先使用题干物理量推导能量', 'evidence': ' '.join(used_symbols) if used_symbols else ''}

    # 检查是否引入外部经验常数（如e, c, G等）
    external_constants = ['e', 'c', 'g', 'h_planck', 'pi', 'sqrt', 'exp', 'log']
