# rule_id=exp_242ad7646e8db813 | domain=Electromagnetism | topic=Electric Potential and Potential Energy
def check_exp_242ad7646e8db813_e3757d85dcde(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    context = sample.get('context', '')
    text = (question + ' ' + prediction + ' ' + context).lower()

    # 关键词匹配触发条件
    if '无穷远' not in text or '同号电荷' not in text or '穿过' not in text and '到达' not in text:
        return {'result': 'inconclusive', 'message': '未满足触发条件', 'evidence': ''}

    # 提取符号：m, v, k, Q, R
    # 仅尝试从文本中提取数值和符号，不使用 eval

    # 匹配 m, v, Q, R 的数值
    m_match = re.search(r'(?<!\w)([0-9]+\.?[0-9]*)\s*kg', text)
    v_match = re.search(r'(?<!\w)([0-9]+\.?[0-9]*)\s*m/s', text)
    q_match = re.search(r'(?<!\w)([0-9]+\.?[0-9]*)\s*C', text)
    r_match = re.search(r'(?<!\w)([0-9]+\.?[0-9]*)\s*m', text)
    k_match = re.search(r'k\s*=\s*([0-9]+\.?[0-9]*)', text)

    # 若缺少关键参数，返回 inconclusive
    if not m_match or not v_match or not q_match or not r_match:
        return {'result': 'inconclusive', 'message': '缺少必要参数', 'evidence': ''}

    # 提取数值
    m = float(m_match.group(1))
    v = float(v_match.group(1))
    q = float(q_match.group(1))
    r = float(r_match.group(1))
    k = float(k_match.group(1)) if k_match else 8.99e9  # 默认 k = 8.99e9 N·m²/C²

    # 计算初动能：1/2 * m * v^2
    initial_kinetic_energy = 0.5 * m * v * v

    # 计算电势能增量：k * Q * Q / R
    # 注意：Q 是电荷量，假设两个同号电荷均为 q
    potential_energy_change = k * q * q / r

    # 检查不等式：初动能 >= 电势能增量
    if initial_kinetic_energy >= potential_energy_change:
        return {'result': 'pass', 'message': '初动能满足穿越条件', 'evidence': '1/2*m*v^2 >= k*q^2/R'}
    else:
        return {'result': 'fail', 'message': '初动能不足，无法穿越', 'evidence': '1/2*m*v^2 < k*q^2/R'}

