# rule_id=exp_36b55552d45524c4 | domain=Electromagnetism | topic=Electric Potential and Potential Energy
def check_exp_36b55552d45524c4_a5cc93f80c29(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')

    if not question or not prediction:
        return {'result': 'inconclusive', 'message': '缺少问题或预测内容', 'evidence': ''}

    # 检查是否包含多个问号或并列子问题
    if question.count('?') < 2 and not any(kw in question for kw in ['and', 'or', 'also', 'then', 'then also']):
        return {'result': 'pass', 'message': '单问句，无需多问句检查', 'evidence': ''}

    # 定义需覆盖的疑问词
    required_questions = ['How much', 'Is it', 'Is it related to']

    # 提取预测中是否包含对每个疑问词的回应
    found = {}
    for q in required_questions:
        if q.lower() in prediction.lower():
            found[q] = True
        else:
            found[q] = False

    # 检查问题中是否出现这些疑问词
    missing_in_question = []
    for q in required_questions:
        if q.lower() in question.lower():
            if not found[q]:
                missing_in_prediction = True
            else:
                missing_in_prediction = False
        else:
            continue

    # 若问题中出现某个疑问词但预测未覆盖，则失败
    for q in required_questions:
        if q.lower() in question.lower() and not found[q]:
            return {
                'result': 'fail',
                'message': f'遗漏对疑问词 "{q}" 的回答',
                'evidence': q
            }

    return {
        'result': 'pass',
        'message': '所有疑问词均被覆盖',
        'evidence': ''
    }

