# rule_id=exp_ad79e4de3d53112c | domain=Electromagnetism | topic=Electric Potential and Potential Energy
def check_exp_ad79e4de3d53112c_b5465392ae79(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')
    text = (question + ' ' + prediction + ' ' + answer + ' ' + context).lower()

    # 提取 q1, q2, q3 的数值
    q1 = None
    q2 = None
    q3 = None

    # 简单正则匹配 q_1, q_2, q_3

    matches = re.findall(r'q[_​‌‍‎‏]?(\d+)[\s\S]*?([+-]?\d*\.?\d+)', text)
    for var, val in matches:
        try:
            num = float(val)
            if var == '1':
                q1 = num
            elif var == '2':
                q2 = num
            elif var == '3':
                q3 = num
        except:
            continue

    # 检查是否都找到
    if q1 is None or q2 is None or q3 is None:
        return {
            "result": "inconclusive",
            "message": "未识别出 q1, q2, q3 的值",
            "evidence": ""
        }

    # 检查是否满足 q3 = q2^2 / q1
    if q1 == 0 or q2 == 0:
        return {
            "result": "inconclusive",
            "message": "q1 或 q2 为零，无法验证等比关系",
            "evidence": ""
        }

    expected_q3 = q2 * q2 / q1
    # 允许一定浮点误差
    if abs(q3 - expected_q3) < 1e-10:
        return {
            "result": "pass",
            "message": "电荷量满足等比关系 q3 = q2^2 / q1",
            "evidence": f"q1={q1}, q2={q2}, q3={q3}"
        }
    else:
        return {
            "result": "fail",
            "message": "电荷量不满足等比关系 q3 = q2^2 / q1",
            "evidence": f"q1={q1}, q2={q2}, q3={q3}, expected_q3={expected_q3}"
        }

