# rule_id=exp_fca022c6ae65f256 | domain=Electromagnetism | topic=Gauss's Law and Applications
def check_exp_fca022c6ae65f256_4d444775765b(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否涉及地球表面大气电场随高度变化
    trigger_keywords = ['earth surface', 'atmospheric electric field', 'height', 'elevation', 'altitude', 'determine charge density']
    if not any(kw in question or kw in context for kw in trigger_keywords):
        return {"result": "inconclusive", "message": "不涉及地球表面电场随高度变化", "evidence": ""}

    # 检查是否使用一维平面高斯模型（柱体上下底面）
    gaussian_model_keywords = ['gaussian surface', 'cylindrical', 'cylinder', 'flat surface', 'planar', '1d', 'one-dimensional']
    if not any(kw in prediction or kw in context for kw in gaussian_model_keywords):
        return {"result": "fail", "message": "未使用一维平面高斯模型", "evidence": ""}

    # 检查电荷密度公式是否为 ρ = ε₀ * (ΔE/Δh) 或等价形式
    # 允许的符号：rho, epsilon_0, E, h, delta, d, (E_surface - E_height) / h
    # 检查是否包含 ε₀ * (ΔE/Δh) 或类似表达式

    # 匹配 ε₀ 或 epsilon_0
    epsilon_pattern = re.compile(r'epsilon[_ ]?0|\varepsilon_0|epsilon0', re.IGNORECASE)
    # 匹配 ΔE/Δh 或 (E_surface - E_height)/h 或 dE/dz
    delta_pattern = re.compile(r'(delta|d)[ _]?e[ _]?([a-z]+)?[/][ _]?([a-z]+)?|d[ _]?e[ _]?[a-z]+[/][ _]?d[ _]?[a-z]+|\(e[ _]?[a-z]+[ _]?-?[ _]?e[ _]?[a-z]+\)[/][ _]?h', re.IGNORECASE)
    # 检查是否包含 ε₀ * (ΔE/Δh) 或等价形式
    if not epsilon_pattern.search(prediction) or not delta_pattern.search(prediction):
        return {"result": "fail", "message": "电荷密度公式不正确，未使用 ρ = ε₀ * (ΔE/Δh)", "evidence": ""}

    # 检查是否使用了正确的物理量：rho, epsilon_0, E, h
    required_symbols = ['rho', 'epsilon_0', 'e', 'h']
    found_symbols = set()
    for sym in required_symbols:
        if re.search(rf'\b{sym}\b', prediction, re.IGNORECASE):
            found_symbols.add(sym)

    if len(found_symbols) < 3:
        return {"result": "fail", "message": "缺少必要符号", "evidence": ""}

    # 检查是否使用了正确的结构：ρ = ε₀ * (E_surface - E_height) / h
    canonical_pattern = re.compile(r'rho[ _]?=[ _]?epsilon[_ ]?0[ _]?\*[ _]?\(e[ _]?surface[ _]?-?[ _]?e[ _]?height\)[ _]?[/][ _]?h', re.IGNORECASE)
    if canonical_pattern.search(prediction):
        return {"result": "pass", "message": "符合一维平面高斯模型和电荷密度公式", "evidence": canonical_pattern.search(prediction).group()}

    # 检查是否使用了等价形式：ρ = ε₀ * (ΔE/Δh)
    alt_pattern = re.compile(r'rho[ _]?=[ _]?epsilon[_ ]?0[ _]?\*[ _]?delta[ _]?e[ _]?[/][ _]?delta[ _]?h|rho[ _]?=[ _]?epsilon[_ ]?0[ _]?\*[ _]?d[ _]?e[ _]?[/][ _]?d[ _]?h', re.IGNORECASE)
    if alt_pattern.search(prediction):
        return {"result": "pass", "message": "符合电荷密度公式", "evidence": alt_pattern.search(prediction).group()}

    return {"result": "inconclusive", "message": "公式形式不明确，无法确认", "evidence": ""}

