# rule_id=exp_ea2d85fa3ff2bce1 | domain=Electromagnetism | topic=Capacitance and Dielectrics
def check_exp_ea2d85fa3ff2bce1_afe5c77bebf9(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否出现 N+1 片定片与 N 片动片交错排列的描述
    if 'n+1' not in question and 'n+1' not in prediction and 'n+1' not in context:
        return {'result': 'inconclusive', 'message': '未检测到 N+1 片定片与 N 片动片交错排列', 'evidence': ''}

    # 提取 N 的值（假设 N 是整数，从文本中提取数字）

    numbers = re.findall(r'\d+', question + ' ' + prediction + ' ' + context)
    N = None
    for num in numbers:
        n_val = int(num)
        if n_val > 0:
            # 假设 N 是动片数量，即 N 片动片 + N+1 片定片
            if 'n' in question or 'n' in prediction or 'n' in context:
                N = n_val
                break

    if N is None:
        return {'result': 'inconclusive', 'message': '未识别出 N 的值', 'evidence': ''}

    # 有效电场区域（间隙数）应为 2N
    expected_gaps = 2 * N

    # 检查预测中是否提到总电容与间隙数的关系
    # 检查是否错误地认为是 N 或 N+1 个间隙
    if 'n' in prediction and 'n+1' in prediction and '2n' not in prediction:
        # 若预测中说 N+1 个间隙，但未提 2N，则可能错误
        if 'n' in prediction and 'n+1' in prediction and '2n' not in prediction:
            return {'result': 'fail', 'message': f'总电容有效间隙数应为 2N={expected_gaps}，而非 N 或 N+1', 'evidence': prediction}

    # 检查是否正确提到 2N 个间隙
    if f'2{n}' in prediction or f'2*{n}' in prediction or f'2n' in prediction:
        return {'result': 'pass', 'message': f'正确识别有效间隙数为 2N={expected_gaps}', 'evidence': prediction}

    # 若未明确提及 2N，但提到了 N 或 N+1，则视为错误
