    if not any(keyword in question.lower() or keyword in prediction.lower() or keyword in context.lower()
               for keyword in ['isolated node', 'isolated island', 'capacitor only', 'only capacitor']):
        return {'result': 'inconclusive', 'message': '未检测到孤立节点描述', 'evidence': ''}

    # 提取电荷值（Q_j）
    # 从 prediction 或 answer 中提取类似 Q1, Q2, ..., Qn 的数值

    q_values = []
    text = prediction + ' ' + answer + ' ' + context
    # 匹配 Q1, Q2, ..., Qn 或 Q_j 形式
    matches = re.findall(r'Q[0-9]+|Q_[0-9]+|Q[0-9]*[a-zA-Z]', text)
    # 尝试提取数值
    for match in matches:
        # 从匹配中提取数字部分
        num_part = re.sub(r'[^0-9.-]', '', match)
