def check_exp_8b5c00401e80e020_f915b8ed53b9(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    context = sample.get('context', '')
    text = (question + ' ' + prediction + ' ' + context).lower()

    if 'high magnetic permeability' not in text or 'field lines constrained inside' not in text:
        return {'result': 'inconclusive', 'message': '未触发条件', 'evidence': ''}

    # 检查是否出现 Φ 的等式形式

    phi_pattern = r'\Phi[\s]*[=≠]([\s\w\-\+\(\)\*\/\.]+)'
    matches = re.findall(phi_pattern, text)

    if not matches:
        return {'result': 'fail', 'message': '未发现磁通量等式', 'evidence': ''}

    # 提取所有 Φ 的表达式
    phi_expressions = [m.strip() for m in matches]

    # 检查是否至少有两个表达式
    if len(phi_expressions) < 2:
        return {'result': 'inconclusive', 'message': '表达式不足两个', 'evidence': ''}

    # 简单检查是否为相同符号或对称形式
    # 仅检查是否出现类似 Φ1 = Φ2 或 Φ = Φ 的等式
    # 保守判断：若存在两个不同符号的 Φ 且未明确相等，则视为错误
    phi_vars = set()
    for expr in phi_expressions:
        # 简单提取变量名
        var = re.sub(r'[^a-zA-Z0-9_]', '', expr)
        if var and var != 'phi' and var != 'phi1' and var != 'phi2':
            phi_vars.add(var)

    # 若有多个不同变量，且未明确相等，视为错误
    if len(phi_vars) > 1:
        # 检查是否明确写出 Φ1 = Φ2
        if re.search(r'\Phi[12]s?\s*[=≠]\s*\Phi[12]', text):
            return {'result': 'pass', 'message': '磁通量相等关系正确', 'evidence': ''}
        else:
            return {'result': 'fail', 'message': '磁通量未正确相等，存在倍数缩放错误', 'evidence': ''}

    # 若只有一个变量，但表达式重复，视为可能正确
    return {'result': 'pass', 'message': '磁通量连续性满足', 'evidence': ''}

