    if 'thin plate' in context or 'thin rectangular plate' in context:
        return {'result': 'inconclusive', 'message': '上下文为薄板，不适用线框规则', 'evidence': ''}

    # 检查预测中是否出现错误系数
    # 匹配形如 1/3, 1/2, 2/3, 1/6, 1/12 等分数

    fractions = re.findall(r'\b(\d+)/(\d+)\b', prediction)
    valid_coefficients = {1/6, 1/12}
    invalid_coefficients = {1/3, 1/2, 2/3, 1/4, 1/5, 1/8, 1/10, 1/15, 1/20}

    found_invalid = False
    for num, den in fractions:
        try:
            val = int(num) / int(den)
            if val in invalid_coefficients:
                found_invalid = True
                break
        except:
            continue

    if found_invalid:
        return {'result': 'fail', 'message': '检测到错误系数，如1/3，应为1/6', 'evidence': ''}

    # 检查是否包含正确的公式形式
    correct_pattern = r'I\s*=\s*\frac{1}{6}m l\^2|I\s*=\s*1/6\s*m\s*l\^2|I\s*=\s*\frac{1}{6}ml^2'
    if re.search(correct_pattern, prediction, re.IGNORECASE):
        return {'result': 'pass', 'message': '公式正确', 'evidence': ''}

    # 检查是否包含 m 和 l 且系数接近 1/6
    if 'm' in prediction and 'l' in prediction:
        # 简单数值解析：寻找 m 和 l 之间的系数
        # 例如：1/6 m l^2, 0.1667 m l^2, 1/6ml^2
        coeff_match = re.search(r'(\d+\.?\d*)\s*[/×*]\s*(\d+\.?\d*)\s*m\s*l\^2', prediction, re.IGNORECASE)
        if coeff_match:
            try:
                num = float(coeff_match.group(1))
                den = float(coeff_match.group(2))
                val = num / den
                if abs(val - 1/6) < 1e-3:
                    return {'result': 'pass', 'message': '系数接近1/6', 'evidence': ''}
            except:
                pass

        # 检查 0.1667 类似值
        float_match = re.search(r'([0-9]\.[0-9]{3,})\s*m\s*l\^2', prediction, re.IGNORECASE)
        if float_match:
            try:
                val = float(float_match.group(1))
                if abs(val - 1/6) < 1e-3:
                    return {'result': 'pass', 'message': '系数接近1/6', 'evidence': ''}
            except:
                pass

    return {'result': 'inconclusive', 'message': '未检测到正确公式或系数', 'evidence': ''}

