    # 检查tanδ表达式中是否为感抗/电阻或电阻/感抗
    # 优先检查tanδ = X_L / R 或 tanδ = R / X_L
    tan_delta_expr = None
    if 'tan' in prediction and 'delta' in prediction:
        # 简单匹配tanδ = ...

        match = re.search(r'tan\s*\(\s*delta\s*\)\s*=\s*([^\s]+)', prediction)
        if match:
            expr = match.group(1).strip()
