    # 若tanδ表达式为R/X_L，但实际应为X_L/R（阻抗角），则错误
    if tan_delta_expr == 'r_over_x_l':
        return {'result': 'fail', 'message': 'tanδ表达式应为感抗/电阻，非电阻/感抗', 'evidence': prediction}

