# rule_id=exp_732464e4fa43295b | domain=Electromagnetism | topic=Electromagnetic Induction and Faraday's Law
def check_exp_732464e4fa43295b_21ee70865de9(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否触发规则：B(t) 和 A(t) 同时变化
    if 'b(t)' not in question and 'b(t)' not in context and 'b(t)' not in prediction:
        return {'result': 'inconclusive', 'message': '未提及B(t)随时间变化', 'evidence': ''}
    if 'a(t)' not in question and 'a(t)' not in context and 'a(t)' not in prediction:
        return {'result': 'inconclusive', 'message': '未提及A(t)随时间变化', 'evidence': ''}

    # 检查是否使用了全微分形式 dΦ/dt = B(dA/dt) + A(dB/dt)
    # 检查是否包含 B * dA/dt 和 A * dB/dt 两项
    terms = ['b * da/dt', 'b * (da/dt)', 'a * db/dt', 'a * (db/dt)', 'b * dA/dt', 'b * (dA/dt)', 'a * dB/dt', 'a * (dB/dt)']
    found_terms = any(term in prediction for term in terms)

    if not found_terms:
        return {'result': 'fail', 'message': '未正确使用全微分形式 dΦ/dt = B(dA/dt) + A(dB/dt)', 'evidence': ''}

    # 检查是否正确叠加，而非简单相减
    # 检查是否出现 B(dA/dt) - A(dB/dt) 或类似减法形式
    negative_forms = ['b * da/dt - a * db/dt', 'b * (da/dt) - a * (db/dt)', 'b * dA/dt - a * dB/dt', 'b * (dA/dt) - a * (dB/dt)']
    if any(form in prediction for form in negative_forms):
        return {'result': 'fail', 'message': '两项应叠加而非相减，违反楞次定律符号规则', 'evidence': ''}

    # 检查是否包含负号（-）在整体表达式前，表示楞次定律
    if not any('-' in pred for pred in [prediction, answer, context]):
        return {'result': 'fail', 'message': '缺少负号，未体现楞次定律方向性', 'evidence': ''}

    # 检查符号是否统一：B(dA/dt) 和 A(dB/dt) 项应同为正或同为负，且整体带负号
    # 简单检查：若两项都存在且符号一致，且整体有负号，则通过
    # 保守判断：若两项都出现且无明显相减，且整体有负号，则认为通过
    if 'b *' in prediction and 'a *' in prediction and '-' in prediction:
        return {'result': 'pass', 'message': '正确使用全微分叠加，符合楞次定律', 'evidence': ''}

    return {'result': 'inconclusive', 'message': '无法确认符号处理是否正确', 'evidence': ''}

