    context = sample.get('context', '').lower()

    # 检查是否触发规则
    if 'long straight wire' not in question and 'rectangular loop' not in question:
        return {'result': 'inconclusive', 'message': '未触发计算长直导线旁矩形线圈磁通量场景', 'evidence': ''}

    # 提取预测中的关键符号
    symbols = set()
    for word in prediction.split():
        word_clean = word.strip('()[]{}+-*/=')
        if word_clean in ['l', 'r_far', 'r_near', 'r_f', 'r_n', 'r1', 'r2']:
            symbols.add(word_clean)

    # 检查是否包含 L, r_far, r_near
    required = {'l', 'r_far', 'r_near'}
    if not required.issubset(symbols):
        return {'result': 'fail', 'message': '缺少必要符号: L, r_far, r_near', 'evidence': ''}

    # 检查对数项形式: ln(r_far / r_near)
    log_pattern = r'ln\(.*?r_far.*?/.*?r_near.*?\)'
    if not any(log_pattern in pred for pred in [prediction, context]):
        return {'result': 'fail', 'message': '未发现对数项 ln(r_far / r_near)', 'evidence': ''}

    # 检查 L 是否作为线性系数（乘在对数项前）
    # 简单检查：L 是否在对数项前且为乘法
    l_before_log = False
    for part in prediction.split():
        if 'l' in part and 'ln' in prediction:
            idx_l = prediction.find('l')
            idx_ln = prediction.find('ln')
            if idx_l < idx_ln and (idx_l == 0 or prediction[idx_l-1] in ' 	*'):
                l_before_log = True
                break

    if not l_before_log:
        return {'result': 'fail', 'message': 'L 未作为线性系数乘在对数项前', 'evidence': ''}

    # 检查 r_far 和 r_near 是否分别对应远端和近端距离
    # 简单检查：r_far 应大于 r_near
    # 从预测中提取数值（若存在）

    nums = re.findall(r'\d+\.?\d*', prediction)
    if len(nums) >= 2:
        try:
            r_far_val = float(nums[-2])
            r_near_val = float(nums[-1])
            if r_far_val <= r_near_val:
                return {'result': 'fail', 'message': 'r_far 应大于 r_near', 'evidence': ''}
        except:
            pass

    return {'result': 'pass', 'message': '磁通量积分变量校验通过', 'evidence': '检测到 L * ln(r_far / r_near) 形式且 r_far > r_near'}

