# rule_id=exp_7cf000807a5a8961 | domain=Electromagnetism | topic=Electromagnetic Induction and Faraday's Law
def check_exp_7cf000807a5a8961_a199604f4eab(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否提及平均磁场、感应磁场时间平均、tanα关系
    has_avg_field = any(word in prediction for word in ['average', 'mean', 'time average', 'temporal average'])
    has_induced_avg = any(word in prediction for word in ['induced field', 'b_induced_avg', 'b_induced average'])
    has_tan_alpha = any(word in prediction for word in ['tan alpha', 'tan α', 'tan(α)', 'tan(α)'])
    has_ratio = any(word in prediction for word in ['ratio', 'divided by', 'over', 'b_induced_avg / b_earth'])

    # 检查是否正确表达 tan α = B_induced_avg / B_earth
    if not (has_avg_field and has_induced_avg and has_tan_alpha and has_ratio):
        return {
            "result": "inconclusive",
            "message": "未明确提及平均感应场与tanα关系",
            "evidence": ""
        }

    # 尝试提取 tan α = B_induced_avg / B_earth 的结构
    # 使用简单字符串匹配，避免复杂解析
    pattern = r'tan[\s]*\(?[a-zA-Zα]\)?[\s]*=[\s]*([a-zA-Z0-9_]+)[\s]*/[\s]*([a-zA-Z0-9_]+)'

    match = re.search(pattern, prediction)
    if not match:
        return {
            "result": "inconclusive",
            "message": "未发现 tan α = ... / ... 的表达式",
            "evidence": ""
        }

    left, right = match.groups()
    left_clean = left.strip().lower()
    right_clean = right.strip().lower()

    # 检查左侧是否为 tan α 或 tan(α)
    if not any(kw in left_clean for kw in ['tan alpha', 'tan α', 'tan(α)', 'tan(α)']):
        return {
            "result": "fail",
            "message": "左侧不匹配 tan α",
            "evidence": match.group()
        }

    # 检查右侧是否为 B_induced_avg / B_earth 或等价形式
    if not (any(kw in right_clean for kw in ['b_induced_avg', 'b_induced average', 'induced field avg']) and
            any(kw in right_clean for kw in ['b_earth', 'background field', 'external field'])):
        return {
            "result": "fail",
            "message": "右侧不匹配 B_induced_avg / B_earth",
            "evidence": match.group()
        }

    # 检查是否在上下文或答案中支持该关系
    if 'b_induced_avg' not in context and 'b_induced_avg' not in answer:
        return {
            "result": "inconclusive",
            "message": "上下文未定义感应场平均值",
            "evidence": ""
        }

    return {
        "result": "pass",
        "message": "正确表达 tan α = B_induced_avg / B_earth 关系",
        "evidence": match.group()
    }

