    context = sample.get('context', '').lower()

    if 'force' not in prediction and 'f' not in prediction:
        return {'result': 'inconclusive', 'message': '未提及力的表达式', 'evidence': ''}

    # 检查是否包含 B(t) 和 I(t) 的乘积项
    # 优先检查是否包含 B(t) 和 I(t) 的显式时间依赖
    has_Bt = any(token in prediction for token in ['b(t)', 'b(t)', 'b(t)', 'b(t)'])
    has_It = any(token in prediction for token in ['i(t)', 'i(t)', 'i(t)', 'i(t)'])

    # 检查是否包含 B(t)*I(t) 或类似形式
    has_BtIt = 'b(t)*i(t)' in prediction or 'b(t) * i(t)' in prediction or 'b(t)i(t)' in prediction

    # 检查是否包含 B(t) 和 I(t) 的乘积项，但不依赖初始值
    # 若仅出现 B 和 I 但无 (t)，可能为常量
    has_B_I = 'b' in prediction and 'i' in prediction and not any(token in prediction for token in ['b(t)', 'i(t)', 'b(t)', 'i(t)'])

    # 若仅使用初始值，如 B0, I0，则为错误
    has_B0 = 'b0' in prediction or 'b_0' in prediction or 'b_initial' in prediction
    has_I0 = 'i0' in prediction or 'i_0' in prediction or 'i_initial' in prediction

    # 若包含 B(t) 和 I(t) 的乘积项，则通过
    if has_BtIt or (has_Bt and has_It):
        return {'result': 'pass', 'message': '包含B(t)与I(t)的瞬时乘积项', 'evidence': 'B(t)*I(t)'}

    # 若仅使用初始值，如 B0, I0，则失败
    if (has_B0 and has_I0) or (has_B0 and 'i' in prediction) or (has_I0 and 'b' in prediction):
        return {'result': 'fail', 'message': '仅使用初始值B0和I0，未体现瞬时性', 'evidence': 'B0, I0'}

    # 若仅出现B和I但无(t)，可能为常量
    if has_B_I and not has_Bt and not has_It:
        return {'result': 'fail', 'message': 'B和I未体现时间依赖，应为B(t)和I(t)', 'evidence': 'B, I'}

    # 无法判断
    return {'result': 'inconclusive', 'message': '无法确认是否包含瞬时项', 'evidence': ''}

