    if 'theta' not in text and 'θ' not in text:
        return {'result': 'inconclusive', 'message': '未提及旋转角度 θ', 'evidence': ''}

    # 检查是否涉及多个空间方向导线
    if 'direction' not in text and 'spatial' not in text and 'orientation' not in text:
        return {'result': 'inconclusive', 'message': '未提及多个空间方向导线', 'evidence': ''}

    # 检查是否包含 sin(θ) 和 cos(θ) 的线性组合
    has_sin = any(keyword in text for keyword in ['sin(', 'sinθ', 'sin(θ)', 'sin theta'])
    has_cos = any(keyword in text for keyword in ['cos(', 'cosθ', 'cos(θ)', 'cos theta'])

    if not has_sin or not has_cos:
        return {'result': 'fail', 'message': '未同时包含 sin(θ) 和 cos(θ)', 'evidence': ''}

    # 检查是否为线性组合（即 sin 和 cos 项无高阶或乘积）
    # 简单检查：sin 和 cos 项是否以 a*sin(θ) + b*cos(θ) 形式出现
    # 通过关键词组合判断
    sin_pattern = r'([+-]?)\s*\d*\s*(sin|sin\(θ|sin\(theta|sinθ|sin theta)\s*\(\s*θ|\(\s*theta|\(\s*θ\s*\))'
    cos_pattern = r'([+-]?)\s*\d*\s*(cos|cos\(θ|cos\(theta|cosθ|cos theta)\s*\(\s*θ|\(\s*theta|\(\s*θ\s*\))'

    # 简化判断：只要 sin 和 cos 都出现，且未明显出现乘积或高阶形式
    # 若出现 sin(θ)cos(θ) 或 sin²(θ) 等，视为非线性
    if any(kw in text for kw in ['sin(θ)cos(θ)', 'sinθcosθ', 'sin(θ)cos(θ)', 'sin^2', 'cos^2', 'sin²', 'cos²', 'sin(θ)cos(θ)', 'sinθcosθ']):
        return {'result': 'fail', 'message': '包含非线性项如 sin(θ)cos(θ) 或平方项', 'evidence': ''}

    # 检查是否包含 ω
    if 'omega' not in text and 'ω' not in text:
        return {'result': 'fail', 'message': '未包含角速度 ω', 'evidence': ''}

    # 检查是否包含 B, l, ω, θ 的组合
    if not any(kw in text for kw in ['b', 'b field', 'magnetic field', 'b l', 'b l^2', 'b l²']):
        return {'result': 'fail', 'message': '未包含 B 或 l 相关项', 'evidence': ''}

    return {'result': 'pass', 'message': '符合 sin(θ) 和 cos(θ) 线性组合形式，且包含 ω 和 B l² 项', 'evidence': ''}

