def check_exp_9ef087a87b93dea7_19ead04e64d0(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否触发条件：磁通量Φ且磁场极短时间内消失
    trigger_keywords = ['磁通量', 'phi', 'φ', '磁场消失', '突然消失', '瞬间消失']
    if not any(kw in question or kw in context for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未触发磁通量突变条件', 'evidence': ''}

    # 查找 I(0) = Φ / L 的表达式
    target_pattern = r'I\(0\)\s*=\s*\Phi\s*/\s*L|I_0\s*=\s*\Phi\s*/\s*L|I_0\s*=\s*\phi\s*/\s*L'

    if not re.search(target_pattern, prediction, re.IGNORECASE) and not re.search(target_pattern, answer, re.IGNORECASE):
        return {'result': 'fail', 'message': '未正确使用磁链守恒公式 I(0) = Φ/L', 'evidence': ''}

    # 尝试提取 Φ 和 L 的数值
    phi_match = re.search(r'\b(\d+\.?\d*)\s*\*?\s*\Phi|\b(\d+\.?\d*)\s*\*?\s*\phi', prediction + ' ' + answer, re.IGNORECASE)
    l_match = re.search(r'\b(\d+\.?\d*)\s*\*?\s*L', prediction + ' ' + answer, re.IGNORECASE)

    if not phi_match or not l_match:
        return {'result': 'inconclusive', 'message': '未找到Φ或L的数值', 'evidence': ''}

    try:
        phi_val = float(phi_match.group(1))
        l_val = float(l_match.group(1))
        i0_val = phi_val / l_val

        # 检查预测或答案中是否包含 I(0) = ... 且值接近
        i0_pattern = r'I\(0\)\s*=\s*(\d+\.?\d*)|I_0\s*=\s*(\d+\.?\d*)'
        i0_found = re.search(i0_pattern, prediction, re.IGNORECASE) or re.search(i0_pattern, answer, re.IGNORECASE)
        if not i0_found:
            return {'result': 'fail', 'message': '未给出初始电流值', 'evidence': ''}

        i0_pred = float(i0_found.group(1))
        if abs(i0_pred - i0_val) < 1e-5:
            return {'result': 'pass', 'message': '初始电流符合磁链守恒 I(0) = Φ/L', 'evidence': i0_found.group(0)}
        else:
            return {'result': 'fail', 'message': f'初始电流值不匹配：预期 {i0_val:.6f}，得到 {i0_pred:.6f}', 'evidence': i0_found.group(0)}
    except Exception:
        return {'result': 'inconclusive', 'message': '数值解析失败', 'evidence': ''}

