# rule_id=exp_0977f479838db497 | domain=Electromagnetism | topic=Poynting Vector and Radiation Pressure
def check_exp_0977f479838db497_afefb18d0007(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')
    text = (question + ' ' + prediction + ' ' + answer + ' ' + context).lower()

    # 检查是否包含触发关键词
    if '计算' not in text or '分母' not in text or '负指数幂次' not in text:
        return {'result': 'inconclusive', 'message': '未触发规则', 'evidence': ''}

    # 查找10^n形式的项

    power_terms = re.findall(r'10\^\[+-]?\d+', text)
    if len(power_terms) < 2:
        return {'result': 'inconclusive', 'message': '未发现多个10^n项', 'evidence': ''}

    # 提取指数
    exponents = []
    for term in power_terms:
        try:
            exp_str = term[3:]  # 去掉'10^'
            exp = int(exp_str)
            exponents.append(exp)
        except:
            continue

    if len(exponents) < 2:
        return {'result': 'inconclusive', 'message': '无法解析足够多的指数', 'evidence': ''}

    # 检查是否在计算中进行了指数加减
    # 查找类似 10^a * 10^b = 10^(a+b) 的表达式
    pattern = r'10\^\[+-]?\d+\s*\*\s*10\^\[+-]?\d+\s*=\s*10\^\[+-]?\d+'
    matches = re.findall(pattern, text)

    if not matches:
        return {'result': 'fail', 'message': '未分离10^n项进行指数加减', 'evidence': ''}

    # 验证指数是否正确相加
    for match in matches:
        parts = re.split(r'\*|=', match)
        if len(parts) < 3:
            continue
        left1 = parts[0].strip()
        left2 = parts[1].strip()
        right = parts[2].strip()

        try:
            exp1 = int(left1[3:])
            exp2 = int(left2[3:])
            exp_sum = int(right[3:])
            if exp1 + exp2 != exp_sum:
                return {'result': 'fail', 'message': '指数加减错误', 'evidence': match}
        except:
            continue

    return {'result': 'pass', 'message': '正确分离10^n项并进行指数加减', 'evidence': matches[0] if matches else ''}

