# rule_id=exp_2a3efc7d3a4143ce | domain=Thermodynamics & Statistical Physics | topic=First Law of Thermodynamics
def check_exp_2a3efc7d3a4143ce_4a131498e911(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').strip()
    answer = sample.get('answer', '').strip()
    context = sample.get('context', '')

    # 检查是否涉及速率比与温度比的关系
    if '速率' not in question and 'v' not in question and 'rms' not in question:
        return {'result': 'inconclusive', 'message': '未提及速率相关量', 'evidence': ''}

    if '温度' not in question and 't' not in question and 't1/t2' not in question:
        return {'result': 'inconclusive', 'message': '未提及温度比', 'evidence': ''}

    # 提取预测中的比值表达式
    # 尝试匹配形如 v1/v2 = sqrt(T1/T2) 或类似形式

    pattern = r'([0-9.]+)/?([0-9.]+).*?sqrt.*?([0-9.]+)/([0-9.]+)'
    match = re.search(pattern, prediction, re.IGNORECASE)

    if not match:
        return {'result': 'inconclusive', 'message': '未检测到符合的比值表达式', 'evidence': ''}

    # 解析数值
    try:
        v1, v2, t1, t2 = map(float, match.groups())
        v_ratio = v1 / v2
        t_ratio = t1 / t2
        sqrt_t_ratio = t_ratio ** 0.5

        # 检查是否 v1/v2 ≈ sqrt(T1/T2)
        if abs(v_ratio - sqrt_t_ratio) < 1e-5:
            return {'result': 'pass', 'message': '速率比等于温度开方比，符合分子速率温度幂次律', 'evidence': prediction}
        else:
            return {'result': 'fail', 'message': '速率比不等于温度开方比，违反幂次律', 'evidence': prediction}
    except Exception:
        return {'result': 'inconclusive', 'message': '数值解析失败', 'evidence': ''}

