def check_exp_de6e0ca5a77a1103_5f354d1da947(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    context = sample.get('context', '').lower()
    prediction = sample.get('prediction', '').lower()

    # 检查触发条件
    if '绝热容器连接' not in context and '绝热容器连接' not in question:
        return {'result': 'inconclusive', 'message': '未触发绝热混合条件', 'evidence': ''}
    if '混合' not in context and '混合' not in question:
        return {'result': 'inconclusive', 'message': '未提及混合过程', 'evidence': ''}
    if '理想气体温度' not in context and '理想气体温度' not in question:
        return {'result': 'inconclusive', 'message': '未涉及理想气体温度', 'evidence': ''}

    # 提取 P, V, T 值
    def extract_values(text: str) -> list:

        # 匹配 P1, V1, T1, P2, V2, T2 等形式
        pattern = r'(?:P|p|压力|压强)[12]?(?:\s*=[^\d]*)?([\d.]+)\s*(?:atm|kpa|pa|mpa|k|c|°c)?'
        matches = re.findall(pattern, text)
        if len(matches) < 6:
            return None
        try:
            values = [float(x) for x in matches[:6]]
            return values
        except:
            return None

    values = extract_values(context + ' ' + prediction)
    if not values:
        return {'result': 'inconclusive', 'message': '无法提取压力、体积、温度数据', 'evidence': ''}

    P1, V1, T1, P2, V2, T2 = values

    # 计算总内能
    # 假设 C_v 为常数，理想气体，内能正比于 nT
    # n = PV / RT，但 R 未知，可约去
    # 所以 Σ(n_i * T_i) ∝ Σ(P_i * V_i / T_i)
    # 等效于：T_eq = (P1*V1 + P2*V2) / (P1*V1/T1 + P2*V2/T2)

    try:
        numerator = P1 * V1 + P2 * V2
        denominator = (P1 * V1) / T1 + (P2 * V2) / T2
        if abs(denominator) < 1e-10:
            return {'result': 'inconclusive', 'message': '分母接近零', 'evidence': ''}
        T_eq = numerator / denominator

        # 检查预测中是否包含 T_eq
        # 简单匹配预测中是否出现类似 T_eq 的表达式
        if 't_eq' in prediction or 't_eq' in context or '最终温度' in prediction or '平衡温度' in prediction:
            # 尝试提取预测的 T_eq
            pattern = r'(?:t_eq|t_eq|最终温度|平衡温度|temperatur|temperature)\s*[:=]?(\s*[-+]?\d+\.?\d*)'
            match = re.search(pattern, prediction)
            if match:
                pred_T_eq = float(match.group(1))
                if abs(pred_T_eq - T_eq) < 1e-5:
                    return {'result': 'pass', 'message': '内能守恒验证通过', 'evidence': '绝热混合过程，内能守恒'}
                else:
                    return {'result': 'fail', 'message': f'预测温度 {pred_T_eq:.2f} 与理论值 {T_eq:.2f} 不符', 'evidence': '绝热混合过程，内能守恒'}
            else:
                return {'result': 'inconclusive', 'message': '未提取预测的平衡温度', 'evidence': ''}
        else:
            return {'result': 'inconclusive', 'message': '未在预测中找到平衡温度', 'evidence': ''}
    except Exception as e:
        return {'result': 'inconclusive', 'message': f'计算异常: {str(e)}', 'evidence': ''}

# rule_id=exp_ee9def544645155f | domain=Thermodynamics & Statistical Physics | topic=First Law of Thermodynamics
def check_exp_ee9def544645155f_2fb6ab6dfa8f(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否涉及 'heat added' 或 'heat absorbed'，而非 'net heat'
    if not any(keyword in question for keyword in ['heat added', 'heat absorbed']):
        return {'result': 'inconclusive', 'message': '未触发吸热量计算场景', 'evidence': ''}

    if any(keyword in question for keyword in ['net heat', 'net energy', 'total heat']):
        return {'result': 'inconclusive', 'message': '题目要求净热量，不适用此规则', 'evidence': ''}

    # 查找预测中是否仅累加了正的 Q 值
    # 简单模式匹配：寻找 Q_i > 0 的累加表达式
    # 优先检查是否出现类似 Q1 + Q2 + ... 且所有项为正
    # 保守判断：若出现 'sum of positive Q' 或 'Q_in = sum(Q_i for Q_i > 0)' 等表述
    positive_sum_keywords = ['sum of positive', 'q_in = sum', 'heat added = sum', 'q_in = sum of q_i where q_i > 0']
    if any(keyword in prediction for keyword in positive_sum_keywords):
        return {'result': 'pass', 'message': '正确仅累加正热量', 'evidence': prediction}

    # 检查是否对所有 Q 进行代数和（如 Q1 + Q2 + Q3，含负值）
    # 若出现 'sum of all Q' 或 'net heat' 等词，且未明确限定正项
    algebraic_sum_keywords = ['sum of all q', 'total heat', 'net heat', 'q1 + q2 + q3', 'sum q_i']
    if any(keyword in prediction for keyword in algebraic_sum_keywords):
        # 但若上下文或答案中明确指出只取正项，则可能仍正确
        if any(keyword in context for keyword in ['only positive', 'absorbed heat', 'heat added']):
            return {'result': 'inconclusive', 'message': '上下文支持正项累加，但表达式模糊', 'evidence': prediction}
        return {'result': 'fail', 'message': '错误地对所有 Q 进行代数和，未仅累加正热量', 'evidence': prediction}

    # 若无明确表达式，但答案中出现数值且为正，且题目要求吸热量
    # 保守判断：若答案为正数，且未提及负值，可能正确
    # 但无法确认是否仅累加正项，返回 inconclusive
    try:
        # 尝试提取数值

        numbers = re.findall(r'\d+\.?\d*', answer)
        if numbers:
            # 若答案为正数，且题目要求吸热量，可能正确
            if all(float(n) > 0 for n in numbers):
                return {'result': 'inconclusive', 'message': '答案为正，但无法确认是否仅累加正项', 'evidence': answer}
    except:
        pass

    return {'result': 'inconclusive', 'message': '无法判断是否仅累加正热量', 'evidence': ''}

# rule_id=exp_3bd2af80486d4900 | domain=Thermodynamics & Statistical Physics | topic=Heat Transfer (Conduction, Convection, Radiation)
def check_exp_3bd2af80486d4900_e419103ffd31(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    context = sample.get('context', '')
    text = (question + ' ' + prediction + ' ' + context).lower()

    if 'estimate of an order of magnitude' not in text:
        return {'result': 'inconclusive', 'message': '未触发规则', 'evidence': ''}

    # 查找热导率k、温差ΔT、厚度d的数值
    k_values = []
    delta_t_values = []
    d_values = []

    # 简单数值提取：匹配数字+单位

    # 匹配 k 的值，如 0.5 W/m·K, 50 W/m·K
    k_matches = re.findall(r'(\d+\.?\d*)\s*[wW][^\d]*[kK][^\d]*[mM][^\d]*[kK]', text)
    for m in k_matches:
        try:
            val = float(m)
            if 0.01 <= val <= 1000:  # 合理热导率范围
                k_values.append(val)
        except:
            pass

    # 匹配 ΔT，如 100 K, 50°C
    delta_t_matches = re.findall(r'(\d+\.?\d*)\s*[kK][^\d]*|[^\d]*[cC][^\d]*[eE][^\d]*[lL][^\d]*[sS][^\d]*', text)
    for m in delta_t_matches:
        try:
            val = float(m)
            if 1 <= val <= 1000:  # 合理温差
                delta_t_values.append(val)
        except:
            pass

    # 匹配 d，如 0.01 m, 1 cm
    d_matches = re.findall(r'(\d+\.?\d*)\s*[mM][^\d]*', text)
    for m in d_matches:
        try:
            val = float(m)
            if 0.001 <= val <= 1:  # 合理厚度
                d_values.append(val)
        except:
            pass

    # 若未找到足够参数，返回 inconclusive
    if not k_values or not delta_t_values or not d_values:
        return {'result': 'inconclusive', 'message': '参数不足', 'evidence': ''}

    # 取平均值估算热流
    k_avg = sum(k_values) / len(k_values)
    delta_t_avg = sum(delta_t_values) / len(delta_t_values)
    d_avg = sum(d_values) / len(d_values)

    # 计算热流 J ≈ k * ΔT / d
    j_est = k_avg * delta_t_avg / d_avg

    # 合理热流边界：一般不超过 10000 W/m²，煮蛋场景应远低于 1000 W
    if j_est > 10000:
        return {'result': 'fail', 'message': '估算热流超过10000 W/m²，不合理', 'evidence': 'estimate of an order of magnitude'}

    if j_est < 0.1:
        return {'result': 'fail', 'message': '估算热流过低，可能遗漏关键因素', 'evidence': 'estimate of an order of magnitude'}

    return {'result': 'pass', 'message': '数量级估算合理', 'evidence': 'estimate of an order of magnitude'}

# rule_id=exp_4e9602ce8d30a1fc | domain=Thermodynamics & Statistical Physics | topic=Heat Transfer (Conduction, Convection, Radiation)
def check_exp_4e9602ce8d30a1fc_75445dc66824(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    # 检查是否涉及 Heat flow 或 Heat flux
    if not any(keyword in question for keyword in ['heat flow', 'heat flux', 'heat transfer']):
        return {'result': 'inconclusive', 'message': '未触发热流或热通量计算', 'evidence': ''}

    # 提取答案中的单位
    units = []
    for word in answer.split():
        word_clean = word.strip('()[]{}').lower()
        if 'w' in word_clean and ('m' in word_clean or 'm²' in word_clean):
            if 'w/m²' in word_clean or 'w/m^2' in word_clean or 'w/m²' in word_clean:
                units.append('W/m²')
            elif 'w/m' in word_clean or 'w/m^1' in word_clean:
                units.append('W/m')
            elif 'w' in word_clean and 'm' not in word_clean:
                units.append('W')

    if not units:
        return {'result': 'inconclusive', 'message': '未识别答案单位', 'evidence': ''}

    # 判断是否应为 W/m²（单位面积通量）
    # 若题目未提面积，应默认为通量
    has_area = any(keyword in context.lower() + question.lower() for keyword in ['area', 'surface', 'm²', 'm^2', 'square meter'])

    # 若未提及面积，应要求 W/m²
    if not has_area:
        if 'w/m²' in str(units) or 'w/m^2' in str(units) or 'w/m²' in str(units):
            return {'result': 'pass', 'message': '单位正确：W/m²', 'evidence': answer}
        elif 'w' in str(units) and 'm' not in str(units):
            return {'result': 'fail', 'message': '应为单位面积通量 W/m²，但给出 W', 'evidence': answer}
        else:
            return {'result': 'inconclusive', 'message': '单位不明确', 'evidence': answer}

    # 若提及面积，则应为 W
    if 'w' in str(units) and 'm' not in str(units):
        return {'result': 'pass', 'message': '单位正确：W', 'evidence': answer}
    elif 'w/m²' in str(units) or 'w/m^2' in str(units):
        return {'result': 'fail', 'message': '提及面积，应为 W，但给出 W/m²', 'evidence': answer}
    else:
        return {'result': 'inconclusive', 'message': '单位不匹配或不明确', 'evidence': answer}

# rule_id=exp_500c807abe9aa3fe | domain=Thermodynamics & Statistical Physics | topic=Heat Transfer (Conduction, Convection, Radiation)
def check_exp_500c807abe9aa3fe_1fafa4fac1e4(sample: dict) -> dict:
    text = (sample.get('prediction', '') + ' ' + sample.get('context', '')).lower()

    # 检查是否出现积分形式
    integral_pattern = r't\s*=\s*\int|t\s*=\s*\int_{.*?}^{.*?}\s*\frac{c}{p\(t\)}\s*d\s*t|t\s*=\s*\int\s*\frac{c}{p\(t\)}\s*d\s*t'
    if not any(keyword in text for keyword in ['int', 'integral', '∫', 'integrate']):
        return {
            "result": "fail",
            "message": "未使用积分形式求解冷却时间",
            "evidence": ""
        }

    # 检查是否包含 C / P(T) 的积分结构
    if not any(pattern in text for pattern in [
        r'\int.*?\frac{c}{p\(t\)}.*?d\s*t',
        r'\int.*?\frac{c}{p\(t\)}.*?dt',
        r'\int.*?c\s*/\s*p\(t\)\s*.*?dt',
        r'\int.*?c\s*/\s*p\(t\)\s*.*?d\s*t'
    ]):
        return {
            "result": "fail",
            "message": "积分形式中未正确包含 C / P(T) 项",
            "evidence": ""
        }

    # 检查是否使用了 t = ΔQ / P_avg 或 t = ΔQ / P_initial
    forbidden_patterns = [
        r't\s*=\s*\frac{\Delta q}{p\s*\w*\s*avg}',
        r't\s*=\s*\frac{\Delta q}{p\s*\w*\s*initial}',
        r't\s*=\s*\frac{\Delta q}{p\s*\w*}',
        r't\s*=\s*\frac{q}{p\s*\w*\s*avg}',
        r't\s*=\s*\frac{q}{p\s*\w*\s*initial}',
        r't\s*=\s*\frac{q}{p\s*\w*}'
    ]
    for pattern in forbidden_patterns:
        if any(pattern in text for pattern in forbidden_patterns):
            return {
                "result": "fail",
                "message": "使用了简略齐次公式，如 t = ΔQ / P_avg 或 t = ΔQ / P_initial",
                "evidence": ""
            }

    # 检查是否包含 C 和 P(T) 的符号
    if 'c' not in text or 'p(t)' not in text and 'p\(t\)' not in text:
        return {
            "result": "inconclusive",
            "message": "未明确识别 C 或 P(T) 符号",
            "evidence": ""
        }

    return {
        "result": "pass",
        "message": "正确使用积分形式 t = ∫ C / P(T) dT 求解冷却时间",
        "evidence": ""
    }

