# rule_id=exp_18efe81dfcd6a9b3 | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_exp_18efe81dfcd6a9b3_15cbda52eb81(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否涉及球体半径变化且为绝热过程
    if 'sphere' not in question and 'radius' not in question and 'r' not in question:
        return {'result': 'inconclusive', 'message': '未提及球体或半径', 'evidence': ''}
    if 'adiabatic' not in question and 'no heat exchange' not in question and 'ignore heat' not in question:
        return {'result': 'inconclusive', 'message': '未声明绝热过程', 'evidence': ''}

    # 检查预测中是否出现 T ∝ r^(-3(γ-1)) 或等价形式
    # 匹配 T ∝ r^(-3(γ-1)) 或 T ~ r^(-3(γ-1)) 或 T = const * r^(-3(γ-1))

    pattern = r'(t|temperature).*?(proportional|~|\=).*?r\^\(-3\(gamma-1\)\)|r\^\(-3\*\(gamma-1\)\)|r\^\(-3\*gamma\+3\)'
    if re.search(pattern, prediction, re.IGNORECASE):
        return {'result': 'pass', 'message': '正确转换为 T ∝ r^(-3(γ-1))', 'evidence': re.search(pattern, prediction, re.IGNORECASE).group()}

    # 检查是否出现 T * r^(3*(gamma-1)) = constant
    canonical_pattern = r't\s*\*\s*r\^\(3\*\(gamma-1\)\)\s*=\s*constant'
    if re.search(canonical_pattern, prediction, re.IGNORECASE):
        return {'result': 'pass', 'message': '正确使用 T * r^(3*(gamma-1)) = constant', 'evidence': re.search(canonical_pattern, prediction, re.IGNORECASE).group()}

    # 检查是否出现 T ∝ r^(-3(γ-1)) 的变体（如指数为 -3*gamma+3）
    if re.search(r't\s*\*\s*r\^\(-3\*gamma\+3\)\s*=\s*constant', prediction, re.IGNORECASE):
        return {'result': 'pass', 'message': '正确转换为 T ∝ r^(-3(γ-1))', 'evidence': re.search(r't\s*\*\s*r\^\(-3\*gamma\+3\)\s*=\s*constant', prediction, re.IGNORECASE).group()}

    return {'result': 'fail', 'message': '未正确转换为 T ∝ r^(-3(γ-1)) 或等价形式', 'evidence': ''}

# rule_id=exp_8c7f11a4f8dae4ff | domain=Thermodynamics & Statistical Physics | topic=Thermodynamic Processes (Isothermal, Adiabatic, etc.)
def check_exp_8c7f11a4f8dae4ff_1c56b2e5b75a(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    context = sample.get('context', '')
