# rule_id=exp_2cfa70362ef366a3 | domain=Thermodynamics & Statistical Physics | topic=Second Law and Entropy
def check_exp_2cfa70362ef366a3_1215970483b4(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    # 提取温度符号
    T_A = None
    T_B = None
    # 尝试从 prediction 或 answer 中提取两个温度

    temp_matches = re.findall(r'([0-9]+\.?[0-9]*)\s*\w*\s*([kKkK]\.?|kelvin|celsius|°c|°k)?', prediction + ' ' + answer + ' ' + context)
    if len(temp_matches) >= 2:
        try:
            T_A = float(temp_matches[0][0])
            T_B = float(temp_matches[1][0])
        except:
            pass

    if T_A is None or T_B is None:
        return {
            "result": "inconclusive",
            "message": "未提取到有效温度值",
            "evidence": ""
        }

    # 计算算术平均和几何平均
    arithmetic_mean = (T_A + T_B) / 2
    geometric_mean = (T_A * T_B) ** 0.5

    # 检查是否满足几何平均 < 算术平均（严格不等式）
    if geometric_mean >= arithmetic_mean:
        return {
            "result": "fail",
            "message": "几何平均不应大于或等于算术平均，违反熵增原理",
            "evidence": "sqrt(T_A*T_B) < (T_A+T_B)/2"
        }

    # 检查 prediction 或 answer 是否区分了接触与热机
    if any(keyword in prediction for keyword in ["直接接触", "接触", "热接触", "thermal contact"]):
        # 若为直接接触，应为算术平均
        if abs(arithmetic_mean - T_A) < 1e-6 or abs(arithmetic_mean - T_B) < 1e-6:
            return {
                "result": "pass",
                "message": "直接接触时平衡温度为算术平均，符合规则",
                "evidence": "直接接触"
            }
        else:
            return {
                "result": "fail",
                "message": "直接接触时平衡温度应为算术平均，但预测不符",
                "evidence": "直接接触"
            }
    elif any(keyword in prediction for keyword in ["热机", "热机做功", "卡诺机", "最大功"]):
        # 若为热机，应为几何平均
        if abs(geometric_mean - T_A) < 1e-6 or abs(geometric_mean - T_B) < 1e-6:
            return {
                "result": "pass",
                "message": "热机做功时平衡温度为几何平均，符合规则",
                "evidence": "热机做功"
            }
        else:
            return {
                "result": "fail",
                "message": "热机做功时平衡温度应为几何平均，但预测不符",
                "evidence": "热机做功"
            }
    else:
        return {
            "result": "inconclusive",
            "message": "未明确区分接触或热机场景",
            "evidence": ""
        }

# rule_id=exp_ce7eed588405c92b | domain=Thermodynamics & Statistical Physics | topic=Second Law and Entropy
def check_exp_ce7eed588405c92b_aca3ca13163f(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    evidence = ''
    result = 'inconclusive'
    message = ''

    # 检查是否提及熵增为零或可逆过程
    if any(keyword in prediction.lower() for keyword in ['entropy change zero', 'reversible', 'delta s = 0', 'deltas = 0']):
        # 提取 T_A, T_B, T_0

        # 匹配 T_A, T_B, T_0 的数值表达式
        t_a_match = re.search(r'T_A\s*=\s*([\d.]+)', prediction) or re.search(r'T_A\s*=\s*([\d.]+)', context)
        t_b_match = re.search(r'T_B\s*=\s*([\d.]+)', prediction) or re.search(r'T_B\s*=\s*([\d.]+)', context)
        t_0_match = re.search(r'T_0\s*=\s*([\d.]+)', prediction) or re.search(r'T_0\s*=\s*([\d.]+)', context)

        if t_a_match and t_b_match and t_0_match:
            try:
                t_a = float(t_a_match.group(1))
                t_b = float(t_b_match.group(1))
                t_0 = float(t_0_match.group(1))

                # 计算几何平均
                expected_t0 = (t_a * t_b) ** 0.5

                # 允许微小误差
                if abs(t_0 - expected_t0) < 1e-6:
                    result = 'pass'
                    message = '终温满足 T_0 = sqrt(T_A * T_B)'
                else:
                    result = 'fail'
                    message = f'终温不满足 T_0 = sqrt(T_A * T_B)；计算值 {t_0:.4f} ≠ {expected_t0:.4f}'

                evidence = f'T_A={t_a}, T_B={t_b}, T_0={t_0}'
            except:
                result = 'inconclusive'
                message = '数值解析失败'
        else:
            result = 'inconclusive'
            message = '未提取到足够温度变量'
    else:
        result = 'inconclusive'
        message = '未提及熵增为零或可逆过程'

    return {
        "result": result,
        "message": message,
        "evidence": evidence
    }

