            # 若未明确关联，但有正确项分解，视为部分正确
            if 'p de' in text and 'e dp' in text:
                return {
                    "result": "inconclusive",
                    "message": "能量分解正确，但未明确功热对应关系",
                    "evidence": "d<E> = p dE + E dp"
                }

