# rule_id=exp_2fd345bf551aef67 | domain=Thermodynamics & Statistical Physics | topic=Kinetic Theory of Gases
def check_exp_2fd345bf551aef67_ef7f91202daf(sample: dict) -> dict:
    text = (sample.get('prediction', '') + ' ' + sample.get('answer', '') + ' ' + sample.get('context', '')).lower()

    # 查找指数形式 P(h) = P0 * exp(-h / X)

    pattern = r'exp\(\?[-+]?\d*\.?\d+\s*\*\s*h\s*[/\*]\s*\(?[^)]+\)?\)?'
    matches = re.findall(pattern, text)

    if not matches:
        return {
            "result": "inconclusive",
            "message": "未找到指数项表达式",
            "evidence": ""
        }

    # 检查指数项中 h 是否除以一个包含 R, T, μ, g 的表达式
    valid_terms = ["rt/μg", "kT/mg", "r t / μ g", "k t / m g"]
    found = False
    evidence = ""

    for match in matches:
        # 简单字符串匹配特征项
        for term in valid_terms:
            if term in match:
                found = True
                evidence = match
                break
        if found:
            break

    if not found:
        return {
            "result": "fail",
            "message": "指数项中 h 未除以特征长度量纲项（如 RT/μg）",
            "evidence": evidence or matches[0]
        }

    return {
        "result": "pass",
        "message": "指数项无量纲性验证通过",
        "evidence": evidence
    }

