# rule_id=exp_1e1993b292e01c6c | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_exp_1e1993b292e01c6c_36a6a664cd25(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')

    # 检查题目中是否存在 (x) 或 (数字) 形式的占位符

    placeholder_pattern = r'\([^)]*\d+[^)]*\)'
    placeholders = re.findall(placeholder_pattern, question)

    if not placeholders:
        return {
            "result": "pass",
            "message": "未发现括号数字占位符，无需处理",
            "evidence": ""
        }

    # 检查占位符是否为待填空序号（如 (26) h）
    # 仅当括号内为纯数字或带单位的数字（如 (26) h）时视为占位符
    valid_placeholder = False
    for ph in placeholders:
        # 去除括号，提取内容
        content = ph.strip('()')
        # 检查是否为数字或数字+单位组合
        if re.match(r'^\d+\s*[a-zA-Z]*$', content.strip()):
            valid_placeholder = True
            break

    if not valid_placeholder:
        return {
            "result": "pass",
            "message": "占位符格式不符，不视为干扰项",
            "evidence": ""
        }

    # 检查预测或答案中是否包含与占位符相关的数值
    # 若预测或答案中出现与占位符数字相同的数值，且该数值在物理计算中无意义，则可能为干扰
    # 但规则强调：不因占位符数值与计算结果不符而强行修正
    # 因此只要预测/答案符合物理逻辑，即使数值与占位符不一致，也应通过

    # 保守判断：若占位符存在且预测/答案中未出现明显错误（如单位错误、逻辑矛盾），则 pass
    # 但若预测/答案中出现与占位符数字完全一致的数值，且该数值在上下文中无物理意义，可能为干扰

    # 提取预测和答案中的所有数字
    all_numbers = re.findall(r'\d+(?:\.\d+)?', prediction + ' ' + answer)

    # 检查是否有数字与占位符数字一致
    matched_numbers = []
    for ph in placeholders:
        ph_num = re.search(r'\d+', ph)
        if ph_num:
            ph_val = ph_num.group()
            if ph_val in all_numbers:
                matched_numbers.append(ph_val)

    # 若存在匹配，但预测/答案整体逻辑正确，仍应 pass
    # 由于无法判断物理逻辑，只能保守判断
    if matched_numbers:
        # 无法判断是否为干扰，返回 inconclusive
        return {
            "result": "inconclusive",
            "message": "检测到占位符与数值匹配，但无法判断是否为干扰，需人工确认",
            "evidence": ", ".join(placeholders)
        }

    # 无匹配，且占位符存在，但预测/答案未受干扰
    return {
        "result": "pass",
        "message": "占位符存在但未影响预测逻辑，符合规则",
        "evidence": ", ".join(placeholders)
    }

