# rule_id=exp_8d20ef317c1cbc07 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_exp_8d20ef317c1cbc07_834cf14d7839(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否涉及等温混合、隔板移除、容器分割
    trigger_keywords = ['分割', '移除隔板', '等温平衡', '混合', '连通', '连通后']
    if not any(kw in question or kw in context for kw in trigger_keywords):
        return {'result': 'inconclusive', 'message': '未触发等温混合场景', 'evidence': ''}

    # 提取 n1, n2, V1, V2, P1, P_final

    # 匹配 n1, n2
    n_match = re.findall(r'(?:n|摩尔数|物质的量)​?[:：]?​?([\d\.]+)', prediction + ' ' + context)
    if len(n_match) < 2:
        return {'result': 'inconclusive', 'message': '未提取到足够物质的量', 'evidence': ''}
    n1, n2 = float(n_match[0]), float(n_match[1])

    # 匹配 V1, V2
    v_match = re.findall(r'(?:v|体积|容积)[:：]?([\d\.]+)', prediction + ' ' + context)
    if len(v_match) < 2:
        return {'result': 'inconclusive', 'message': '未提取到足够体积', 'evidence': ''}
    v1, v2 = float(v_match[0]), float(v_match[1])

    # 匹配 P1, P_final
    p_match = re.findall(r'(?:p|压强|压力)[:：]?([\d\.]+)', prediction + ' ' + context)
    if len(p_match) < 2:
        return {'result': 'inconclusive', 'message': '未提取到足够压强', 'evidence': ''}
    p1, p_final = float(p_match[0]), float(p_match[1])

    # 检查是否 V1 == V2
    if abs(v1 - v2) > 1e-6:
        # 一般情况：P_final = (n1+n2)RT / (V1+V2)
        # 但无 R,T，无法直接验证，只能验证比例关系
        # 用 P_final / P1 = (n1+n2)/(2*n1) 仅当 V1=V2
        # 所以若 V1 != V2，无法验证该比例
        return {'result': 'inconclusive', 'message': '体积不等，无法验证比例关系', 'evidence': ''}

    # V1 == V2
    # 检查 P_final / P1 == (n1 + n2) / (2 * n1)
    expected_ratio = (n1 + n2) / (2 * n1)
    actual_ratio = p_final / p1
    if abs(actual_ratio - expected_ratio) < 1e-6:
        return {'result': 'pass', 'message': '等温混合压力比例校验通过', 'evidence': f'P_final/P1 = {actual_ratio:.4f}, expected = {expected_ratio:.4f}'}
    else:
        return {'result': 'fail', 'message': '等温混合压力比例校验失败', 'evidence': f'P_final/P1 = {actual_ratio:.4f}, expected = {expected_ratio:.4f}'}

