# rule_id=exp_a3ab98f4a1a4b451 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_exp_a3ab98f4a1a4b451_067905e3c644(sample: dict) -> dict:
    try:
        prediction = sample.get('prediction', '').strip()
        answer = sample.get('answer', '').strip()
        if not prediction or not answer:
            return {'result': 'inconclusive', 'message': '缺少预测或答案', 'evidence': ''}

        # 提取预测中的 M_mix

        pred_match = re.search(r'M_mix\s*=\s*([\d.]+)', prediction)
        if not pred_match:
            return {'result': 'inconclusive', 'message': '未找到 M_mix 公式', 'evidence': ''}
        M_mix_pred = float(pred_match.group(1))

        # 提取答案中的 M_mix
        ans_match = re.search(r'M_mix\s*=\s*([\d.]+)', answer)
        if not ans_match:
            return {'result': 'inconclusive', 'message': '答案中未找到 M_mix', 'evidence': ''}
        M_mix_true = float(ans_match.group(1))

        # 解析 w_i 和 M_i
        w_M_pairs = re.findall(r'w_i\s*=\s*([\d.]+)\s*,\s*M_i\s*=\s*([\d.]+)', prediction)
        if not w_M_pairs:
            return {'result': 'inconclusive', 'message': '未找到 w_i 和 M_i 数据', 'evidence': ''}

        # 计算 1/M_mix 的理论值
        sum_inv = 0.0
        M_i_list = []
        for w, M in w_M_pairs:
            w_val = float(w)
            M_val = float(M)
            if w_val < 0 or M_val <= 0:
                return {'result': 'inconclusive', 'message': '无效的 w_i 或 M_i', 'evidence': ''}
            sum_inv += w_val / M_val
            M_i_list.append(M_val)

        M_mix_calc = 1.0 / sum_inv

        # 检查 M_mix 是否在最值之间
        min_M = min(M_i_list)
        max_M = max(M_i_list)
        if not (min_M <= M_mix_pred <= max_M):
            return {'result': 'fail', 'message': 'M_mix 不在最小组分与最大组分摩尔质量之间', 'evidence': prediction}

        # 检查计算是否正确
        if abs(M_mix_pred - M_mix_calc) > 1e-6:
            return {'result': 'fail', 'message': '公式 1/M_mix = sum(w_i/M_i) 未正确执行', 'evidence': prediction}

        # 检查与答案是否一致
        if abs(M_mix_pred - M_mix_true) > 1e-6:
            return {'result': 'fail', 'message': '预测值与答案不一致', 'evidence': prediction}

        return {'result': 'pass', 'message': '混合气体平均摩尔质量守恒检查通过', 'evidence': prediction}
    except Exception:
        return {'result': 'inconclusive', 'message': '解析或计算异常', 'evidence': ''}

# rule_id=exp_a88f99b62e7df910 | domain=Thermodynamics & Statistical Physics | topic=Ideal Gas Law and Real Gas Behavior
def check_exp_a88f99b62e7df910_146521e2423e(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    answer = sample.get('answer', '')
    context = sample.get('context', '')

    text = question + ' ' + prediction + ' ' + answer + ' ' + context
    text = text.lower()

    if 'air cooling' not in text and 'dehumidification' not in text and 'saturation vapor pressure' not in text and 'condensation' not in text:
        return {'result': 'inconclusive', 'message': 'no relevant keywords', 'evidence': ''}

    # 提取 P1, P2, T1, T2, V, M

    P1_match = re.search(r'p1\s*=\s*([\d\.]+)', text)
    P2_match = re.search(r'p2\s*=\s*([\d\.]+)', text)
    T1_match = re.search(r't1\s*=\s*([\d\.]+)', text)
    T2_match = re.search(r't2\s*=\s*([\d\.]+)', text)
    V_match = re.search(r'v\s*=\s*([\d\.]+)', text)
    M_match = re.search(r'm\s*=\s*([\d\.]+)', text)

    if not all([P1_match, P2_match, T1_match, T2_match, V_match, M_match]):
        return {'result': 'inconclusive', 'message': 'missing required parameters', 'evidence': ''}

    try:
        P1 = float(P1_match.group(1))
        P2 = float(P2_match.group(1))
        T1 = float(T1_match.group(1))
        T2 = float(T2_match.group(1))
        V = float(V_match.group(1))
        M = float(M_match.group(1))

        R = 8.314  # J/(mol·K)

        n1 = P1 * V / (R * T1)
        n2 = P2 * V / (R * T2)
        delta_n = abs(n1 - n2)
        mass = M * delta_n

        # 检查答案是否在合理范围内
        if not answer:
            return {'result': 'inconclusive', 'message': 'no answer provided', 'evidence': ''}

        answer_match = re.search(r'[-+]?\d*\.?\d+', answer)
        if not answer_match:
            return {'result': 'inconclusive', 'message': 'invalid answer format', 'evidence': ''}

        answer_val = float(answer_match.group(0))

        # 允许 10% 误差
        if abs(mass - answer_val) <= 0.1 * max(mass, answer_val):
            return {'result': 'pass', 'message': 'correct modeling', 'evidence': f'P1={P1}, P2={P2}, T1={T1}, T2={T2}, V={V}, M={M}'}
        else:
            return {'result': 'fail', 'message': 'incorrect mass calculation', 'evidence': f'computed mass={mass:.4f}, answer={answer_val}'}

    except Exception:
        return {'result': 'inconclusive', 'message': 'computation error', 'evidence': ''}

