    right = 'rho * d * l' in prediction or 'density * thickness * latent heat' in prediction

    if left and right:
        return {'result': 'pass', 'message': '满足能量通量时间积分守恒律', 'evidence': 'J_Q * t = rho * d * L'}

    # 尝试更宽松匹配：是否出现 J_Q * t 和 rho * d * L 的组合
    if ('j_q' in prediction or 'power flux' in prediction) and ('t' in prediction or 'time' in prediction):
        if ('rho' in prediction or 'density' in prediction) and ('d' in prediction or 'thickness' in prediction) and ('l' in prediction or 'latent heat' in prediction):
            return {'result': 'pass', 'message': '符号存在且结构匹配', 'evidence': 'J_Q * t = rho * d * L'}

    return {'result': 'fail', 'message': '未发现能量通量时间积分守恒律的正确表达', 'evidence': ''}

