    pattern3 = r'\(1\s*[-+*/]\s*\(rho_i\s*/\s*rho_w\)\)\s*\*\s*v_melt'
    pattern4 = r'\(1\s*[-+*/]\s*\(ρi\s*/\s*ρw\)\)\s*\*\s*v_melt'

    matched = False
    if any(pattern in prediction or pattern in context for pattern in [pattern1, pattern2, pattern3, pattern4]):
        matched = True

    # 检查是否错误地使用了等体积假设
    wrong_pattern = r'volume.*equal|same volume|v_melt.*=.*v_surface|v_surface.*=.*v_melt'
    if any(re.search(wrong_pattern, text, re.IGNORECASE) for text in [prediction, context]):
        return {'result': 'fail', 'message': '错误地假设体积不变，未考虑密度差异', 'evidence': re.search(wrong_pattern, prediction + context, re.IGNORECASE).group() if re.search(wrong_pattern, prediction + context, re.IGNORECASE) else ''}

    if matched and has_density and has_mass_conservation:
        return {'result': 'pass', 'message': '正确考虑密度差异与质量守恒', 'evidence': '检测到密度比和质量守恒相关表达式'}

    if not matched and (has_density or has_mass_conservation):
        return {'result': 'fail', 'message': '未正确使用密度差导致的体积变化公式', 'evidence': '提及密度或质量守恒但未使用正确公式'}

    return {'result': 'inconclusive', 'message': '未充分提及密度或质量守恒相关逻辑', 'evidence': ''}

