# rule_id=exp_c2e4d7354a6824a7 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
def check_exp_c2e4d7354a6824a7_abe5585fd334(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    context = sample.get('context', '')
    text = (question + ' ' + prediction + ' ' + context).lower()

    if any(trigger in text for trigger in ['再次放入', '继续反应', '第二阶段', '后续过程', '接下来']):
        # 查找是否出现潜热公式形式

        # 匹配 ΔQ = Δm * L 或类似表达
        pattern = r'\?delta\?q\?[^a-z]*=\?[^a-z]*\?delta\?m\?[^a-z]*\*\?[^a-z]*l|q\?[^a-z]*=\?[^a-z]*m\?[^a-z]*\*\?[^a-z]*l'
        matches = re.findall(pattern, text, re.IGNORECASE)

        if not matches:
            return {'result': 'inconclusive', 'message': '未发现潜热公式', 'evidence': ''}

        # 检查是否使用了 Δm 而非总质量
        # 查找 Δm 或 "新增" "额外" "新" 等关键词
        has_delta_m = any(kw in text for kw in ['delta m', 'Δm', '新增', '额外', '新生成', '新冻结', '新增质量'])
        has_total_m = any(kw in text for kw in ['总质量', '累计', '之前', '第一阶段'])

        if not has_delta_m:
            return {'result': 'fail', 'message': '第二阶段未使用增量质量 Δm', 'evidence': matches[0]}

        if has_total_m and not has_delta_m:
            return {'result': 'fail', 'message': '第二阶段错误使用总质量而非增量', 'evidence': matches[0]}

        # 若使用了 Δm 且未提及第一阶段潜热累加，则通过
        if '第一阶段' not in text or '累加' not in text:
            return {'result': 'pass', 'message': '正确使用增量质量 Δm 计算第二阶段潜热', 'evidence': matches[0]}

        # 若提及累加但使用 Δm，仍可能正确，需保守
        return {'result': 'inconclusive', 'message': '存在累加表述，但使用 Δm，难以判断', 'evidence': matches[0]}

    return {'result': 'inconclusive', 'message': '未触发分阶段描述', 'evidence': ''}

# rule_id=exp_ca7eb95f07f66865 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
def check_exp_ca7eb95f07f66865_71ed3dd8fb23(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()
    text = question + ' ' + prediction + ' ' + context

    if 'hydrostatic equilibrium' not in text and 'pressure equilibrium' not in text:
        return {'result': 'inconclusive', 'message': '未触发关键词', 'evidence': ''}

    # 检查是否出现冰盖总压强 = 水柱压强的等价形式
    # 目标方程: ρi * g * H_total = ρw * g * H_water + ρi * g * (H_total - H_water)
    # 简化后为: ρi * H_total = ρw * H_water + ρi * (H_total - H_water)
    # 即: ρi * H_total = ρw * H_water + ρi * H_total - ρi * H_water
    # 化简得: 0 = ρw * H_water - ρi * H_water → H_water * (ρw - ρi) = 0
    # 但实际应保留原始形式验证

    # 检查是否出现类似形式的等式
    # 优先匹配符号：ρi, ρw, H_total, H_water, g
    # 但不依赖符号值，只检查结构

    # 检查是否出现 'rho_i' 或 'ρi'，'rho_w' 或 'ρw'，'h_total' 或 'H_total'，'h_water' 或 'H_water'
    has_rhosi = any(k in text for k in ['rho_i', 'ρi', 'rho_i', 'rho_i'])
    has_rhows = any(k in text for k in ['rho_w', 'ρw', 'rho_w', 'rho_w'])
    has_htotal = any(k in text for k in ['h_total', 'h_total', 'h_total', 'h_total'])
    has_hwater = any(k in text for k in ['h_water', 'h_water', 'h_water', 'h_water'])

    if not (has_rhosi and has_rhows and has_htotal and has_hwater):
        return {'result': 'inconclusive', 'message': '缺少关键符号', 'evidence': ''}

    # 检查是否出现等式形式：左边 = 右边
    # 且左边为 ρi * g * H_total
    # 右边为 ρw * g * H_water + ρi * g * (H_total - H_water)
    # 但 g 可能省略，或用其他符号
    # 保守匹配：检查是否存在类似结构的等式
    # 用正则匹配等式

    eq_pattern = r'([a-zA-Z0-9_]+).*?=(.*?)'
    matches = re.findall(eq_pattern, text)

    found = False
    for left, right in matches:
        left_clean = left.strip().replace(' ', '')
        right_clean = right.strip().replace(' ', '')

        # 检查左边是否为 ρi * g * H_total 或类似
        if any(k in left_clean for k in ['rhoi', 'ρi', 'rho_i', 'rho_i']) and any(k in left_clean for k in ['h_total', 'h_total', 'h_total']):
            # 检查右边是否为 ρw * g * H_water + ρi * g * (H_total - H_water)
            if any(k in right_clean for k in ['rho_w', 'ρw', 'rho_w']) and any(k in right_clean for k in ['h_water', 'h_water', 'h_water']) and '+' in right_clean and any(k in right_clean for k in ['rhoi', 'ρi', 'rho_i']) and 'h_total' in right_clean and '(' in right_clean and ')' in right_clean:
                # 检查是否有 (H_total - H_water)
                if re.search(r'h_total.*?h_water', right_clean) or re.search(r'H_total.*?H_water', right_clean):
                    found = True
                    break

    if found:
        return {'result': 'pass', 'message': '满足界面压强平衡方程', 'evidence': '命中的等式结构'}
    else:
        return {'result': 'fail', 'message': '未建立正确的压强平衡方程', 'evidence': ''}

