# rule_id=exp_e1fb7c838d477e51 | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
def check_exp_e1fb7c838d477e51_689f5acfd314(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    context = sample.get('context', '')

    text = question + ' ' + prediction + ' ' + context
    text_lower = text.lower()

    # 检查是否涉及加热曲线时间轴到热量轴的转换
    if 'time' not in text_lower or 'heat' not in text_lower or 'q' not in text_lower:
        return {'result': 'inconclusive', 'message': '未提及时间与热量转换', 'evidence': ''}

    # 检查是否提到恒定功率
    if 'constant power' not in text_lower and 'p constant' not in text_lower and 'power is constant' not in text_lower:
        return {'result': 'inconclusive', 'message': '未说明功率恒定', 'evidence': ''}

    # 查找时间轴段落长度比例

    time_ratios = re.findall(r'(\d+\.?\d*)\s*:\s*(\d+\.?\d*)', text)
    if not time_ratios:
        return {'result': 'inconclusive', 'message': '未找到时间轴比例', 'evidence': ''}

    # 查找热量轴段落长度比例
    heat_ratios = re.findall(r'(\d+\.?\d*)\s*:\s*(\d+\.?\d*)', text)
    if not heat_ratios:
        return {'result': 'inconclusive', 'message': '未找到热量轴比例', 'evidence': ''}

    # 取第一个比例
    t_ratio = time_ratios[0]
    q_ratio = heat_ratios[0]

    try:
        t1, t2 = float(t_ratio[0]), float(t_ratio[1])
        q1, q2 = float(q_ratio[0]), float(q_ratio[1])

        # 比较比例是否相等
        t_val = t1 / t2
        q_val = q1 / q2

        # 允许微小误差
        if abs(t_val - q_val) < 1e-6:
            return {'result': 'pass', 'message': '热量段长度比例与时间轴一致', 'evidence': f"{t_ratio[0]}:{t_ratio[1]} vs {q_ratio[0]}:{q_ratio[1]}"}
        else:
            return {'result': 'fail', 'message': '热量段长度比例与时间轴不一致', 'evidence': f"{t_ratio[0]}:{t_ratio[1]} vs {q_ratio[0]}:{q_ratio[1]}"}

    except Exception:
        return {'result': 'inconclusive', 'message': '比例解析失败', 'evidence': ''}

# rule_id=exp_e8df1df814984f8a | domain=Thermodynamics & Statistical Physics | topic=Phase Transitions and Latent Heat
def check_exp_e8df1df814984f8a_654c681467a9(sample: dict) -> dict:
    text = (sample.get('question', '') + ' ' + sample.get('prediction', '') + ' ' + sample.get('answer', '') + ' ' + sample.get('context', '')).lower()

    # 检查是否涉及每年、每小时等时间跨度
    if not any(keyword in text for keyword in ['每年', '每小时', 'per year', 'per hour']):
        return {'result': 'inconclusive', 'message': '未触发时间单位相关计算', 'evidence': ''}

    # 定义时间转换常数
    seconds_per_year = 3.1536e7
    seconds_per_hour = 3600

    # 查找可能的数值表达式

    # 匹配类似 1.2 year 或 5 per year 的模式
    patterns = [
        r'(\d+\.?\d*)\s*[yY]ear',
        r'(\d+\.?\d*)\s*[pP]er\s+[yY]ear',
        r'(\d+\.?\d*)\s*[hH]our',
        r'(\d+\.?\d*)\s*[pP]er\s+[hH]our'
    ]

    found = False
    for pattern in patterns:
        matches = re.findall(pattern, text)
        for m in matches:
            try:
                value = float(m)
                # 检查是否在表达式中乘以了正确的秒数
                # 例如：value * 3.1536e7
                if 'year' in pattern or 'per year' in pattern:
                    if f'{value} * {seconds_per_year}' not in text and f'{value} * 3.1536e7' not in text:
                        return {'result': 'fail', 'message': '年单位未正确转换为秒', 'evidence': m}
                elif 'hour' in pattern or 'per hour' in pattern:
                    if f'{value} * {seconds_per_hour}' not in text and f'{value} * 3600' not in text:
                        return {'result': 'fail', 'message': '小时单位未正确转换为秒', 'evidence': m}
                found = True
            except:
                continue

    if not found:
        return {'result': 'inconclusive', 'message': '未发现时间单位数值表达式', 'evidence': ''}

    return {'result': 'pass', 'message': '时间单位转换一致', 'evidence': ''}

