    text = (question + ' ' + context + ' ' + prediction + ' ' + answer).lower()

    # 检查是否提及线性热容 C = a + bT
    if 'c = a + b*t' not in text and 'c = a + bt' not in text and 'c = a + b*t' not in text:
        return {'result': 'inconclusive', 'message': '未提及线性热容形式', 'evidence': ''}

    # 提取 a, b, T1, T2

    # 匹配 a, b, T1, T2 的数值表达式
    # 优先匹配 a, b, T1, T2 的符号或数值
    # 从预测或答案中提取 a, b, T1, T2
    # 使用正则匹配 a, b, T1, T2 的数值
    # 例如: a=2, b=3, T1=300, T2=400
    pattern = r'(?:a|a=|a =)​?([+-]?\d*\.?\d+)(?:\s*,\s*|\s+|\s*\+\s*|\s*\-\s*)(?:b|b=|b =)​?([+-]?\d*\.?\d+)(?:\s*,\s*|\s+|\s*\+\s*|\s*\-\s*)(?:t1|t1=|t1 =|t_1|t_1=|t_1 =)​?([+-]?\d*\.?\d+)(?:\s*,\s*|\s+|\s*\+\s*|\s*\-\s*)(?:t2|t2=|t2 =|t_2|t_2=|t_2 =)​?([+-]?\d*\.?\d+)'
    match = re.search(pattern, text)
    if not match:
        return {'result': 'inconclusive', 'message': '未提取到 a, b, T1, T2', 'evidence': ''}

    try:
        a = float(match.group(1))
        b = float(match.group(2))
        T1 = float(match.group(3))
        T2 = float(match.group(4))
    except:
        return {'result': 'inconclusive', 'message': '数值解析失败', 'evidence': ''}

    # 计算 C_avg = a + b*(T1+T2)/2
    C_avg = a + b * (T1 + T2) / 2
    delta_T = T2 - T1
    Q_expected = C_avg * delta_T

    # 从预测或答案中提取 Q 的表达式
    # 匹配 Q = ... 的表达式
    q_pattern = r'q\s*=\s*([+-]?\d*\.?\d+|a\s*\+\s*b\s*\*\s*\(t1\s*\+\s*t2\s*\)\s*/\s*2\s*\*\s*\(t2\s*\-\s*t1\s*\))'
    q_match = re.search(q_pattern, text)
    if not q_match:
        return {'result': 'inconclusive', 'message': '未找到 Q 的表达式', 'evidence': ''}

    q_expr = q_match.group(1).strip()

    # 简单数值解析 Q
    # 如果是表达式 a + b*(T1+T2)/2 * (T2-T1)
    if 'a + b*(t1 + t2)/2 * (t2 - t1)' in q_expr or 'a + b*(t1+t2)/2*(t2-t1)' in q_expr:
        Q_computed = Q_expected
    else:
        # 尝试数值解析
        try:
            Q_computed = float(q_expr)
        except:
            return {'result': 'inconclusive', 'message': 'Q 表达式无法解析', 'evidence': ''}

    # 比较 Q_expected 和 Q_computed
    # 允许小误差
    if abs(Q_expected - Q_computed) < 1e-6:
        return {'result': 'pass', 'message': '积分等价性成立', 'evidence': q_expr}
    else:
        return {'result': 'fail', 'message': '积分等价性不成立', 'evidence': q_expr}

