def check_exp_2a28e21c9a90c8bd_6faef0f1b64f(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()
    text = question + ' ' + prediction + ' ' + context

    # 检查是否提及行星、球体、吸收、辐射、能量平衡
    if not any(kw in text for kw in ['planet', 'sphere', 'absorb', 'radiate', 'energy balance']):
        return {'result': 'inconclusive', 'message': '未提及关键物理情境', 'evidence': ''}

    # 检查吸收项是否为 πR²，辐射项是否为 4πR²
    # 吸收项应为 (1-a) S π R^2
    # 辐射项应为 4 π R^2 σ T^4
    # 关键是：4 是否在辐射项中，且不在吸收项中

    # 检查吸收项中是否有 πR²
    absorb_pattern = r'\pi\s*\*\s*[rR]\s*\^\s*2|pi\s*\*\s*[rR]\s*\^\s*2|\pi\s*[rR]\s*\^\s*2'
    rad_pattern = r'4\s*\*\s*\pi\s*\*\s*[rR]\s*\^\s*2|4\s*\*\s*pi\s*\*\s*[rR]\s*\^\s*2|4\s*\*\s*\pi\s*[rR]\s*\^\s*2'

    absorb_match = any(kw in text for kw in ['pi r^2', 'pi r²', 'pi*r^2', 'pi*r²', 'πr^2', 'πr²'])
    rad_match = any(kw in text for kw in ['4*pi*r^2', '4*pi*r²', '4*π*r^2', '4*π*r²', '4 pi r^2', '4 pi r²', '4πr^2', '4πr²'])

    # 检查是否在公式中出现 4 在辐射项，且吸收项无 4
    # 但注意：4 可能出现在其他地方，需结合上下文
    # 保守判断：若吸收项有 πR² 且辐射项有 4πR²，则认为正确
    if absorb_match and rad_match:
        # 检查是否在等式两侧分别出现
        parts = text.split('=')
        if len(parts) < 2:
            return {'result': 'inconclusive', 'message': '未发现等式', 'evidence': ''}

        left = parts[0].strip()
        right = parts[1].strip()

        # 吸收项在左边，辐射项在右边
        # 检查左边是否有 πR²，右边是否有 4πR²
        left_has_pi_r2 = any(kw in left for kw in ['pi r^2', 'pi r²', 'pi*r^2', 'pi*r²', 'πr^2', 'πr²'])
        right_has_4pi_r2 = any(kw in right for kw in ['4*pi*r^2', '4*pi*r²', '4*π*r^2', '4*π*r²', '4 pi r^2', '4 pi r²', '4πr^2', '4πr²'])

        if left_has_pi_r2 and right_has_4pi_r2:
            return {'result': 'pass', 'message': '吸收用投影面积，辐射用全表面积，系数4位置正确', 'evidence': '4πR² in radiation, πR² in absorption'}
        elif left_has_pi_r2 and not right_has_4pi_r2:
            return {'result': 'fail', 'message': '辐射项缺少系数4，应为4πR²', 'evidence': right}
        elif not left_has_pi_r2 and right_has_4pi_r2:
            return {'result': 'fail', 'message': '吸收项未使用投影面积πR²', 'evidence': left}
        else:
            return {'result': 'inconclusive', 'message': '面积项不明确', 'evidence': ''}

    # 若未检测到关键项，返回 inconclusive
    return {'result': 'inconclusive', 'message': '未检测到面积项模式', 'evidence': ''}

