# rule_id=exp_86fa90315439189a | domain=Optics | topic=Snell's Law and Critical Angle
def check_exp_86fa90315439189a_74f5ce61f4f3(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否提及 n(z) 或 n^2(z) 随高度变化
    if 'n(z)' not in question and 'n^2(z)' not in question and 'n(z)' not in context and 'n^2(z)' not in context:
        return {'result': 'inconclusive', 'message': '未提及 n(z) 或 n^2(z) 变化', 'evidence': ''}

    # 检查是否使用 Snell 定律的层状变形公式：n(z) * cos(theta) = constant
    snell_pattern = r'n\(z\)\s*\*\s*cos\(\s*theta\s*\)\s*=\s*[^\s]+\s*\*\s*cos\(\s*theta_0\s*\)'
    snell_match = False
    if 'n(z)' in prediction or 'n^2(z)' in prediction:
        if any(keyword in prediction for keyword in ['snell', 'n(z)*cos(theta)', 'n_0*cos(theta_0)', 'constant']):
            snell_match = True

    # 检查是否使用 dx = dz / tan(theta) 建立轨迹积分
    integral_pattern = r'dx\s*=\s*dz\s*/\s*tan\(\s*theta\s*\)'
    integral_match = False
    if 'dx' in prediction and 'dz' in prediction and 'tan' in prediction:
        if any(op in prediction for op in ['/', 'integrate', 'integral', 'trajectory']):
            integral_match = True

    # 若两者均未命中，返回 fail
    if not snell_match and not integral_match:
        return {'result': 'fail', 'message': '未使用 Snell 定律层状变形或轨迹积分公式', 'evidence': ''}

    # 若至少一个命中，返回 pass
    return {'result': 'pass', 'message': '正确使用 Snell 定律层状变形与轨迹积分建模', 'evidence': 'n(z)*cos(theta) = constant' if snell_match else 'dx = dz/tan(theta)'}

