    # 检查是否出现 Re{i * e^{i\phi}} = -sin(\phi)
    if 're{i * e^{i\phi}} = -sin' in text or 're(i * e^{i\phi}) = -sin' in text or 'real(i * exp(i*phi)) = -sin(phi)' in text:
        return {'result': 'pass', 'message': '正确实现复数波矢实部提取规则', 'evidence': 'Re{i * e^{i\phi}} = -sin(\phi)'}

    # 检查是否出现 i 转换为相位差（如 cos 变 sin）
