# rule_id=exp_1f6ec678a66851b5 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_exp_1f6ec678a66851b5_68435ace2c75(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    context = sample.get('context', '').lower()
    prediction = sample.get('prediction', '').lower()

    # 检查是否同时提及光栅参数（N, d）和探测器参数（像素密度/尺寸）
    has_grating_params = any(keyword in question or keyword in context for keyword in ['n=', 'n =', 'grating lines', 'number of lines', 'd=', 'd ='])
    has_detector_params = any(keyword in question or keyword in context for keyword in ['pixel size', 'pixel density', 'pixel pitch', 'detector resolution', 'pixel spacing'])

    if not (has_grating_params and has_detector_params):
        return {
            "result": "inconclusive",
            "message": "未同时提供光栅与探测器参数",
            "evidence": ""
        }

    # 尝试从上下文或问题中提取 m, N, Δy, f
    # 使用简单字符串匹配和数值解析
    m_val = None
    N_val = None
    delta_y_val = None
    f_val = None

    # 提取 m
    for word in ['m=', 'm =', 'order=', 'order =']:
        if word in question or word in context:
            try:
                start = question.find(word) if word in question else context.find(word)
                if start != -1:
                    val_str = question[start + len(word):].strip().split()[0] if word in question else context[start + len(word):].strip().split()[0]
                    m_val = float(val_str)
            except:
                pass

    # 提取 N
    for word in ['n=', 'n =', 'number of lines', 'grating lines']:
        if word in question or word in context:
            try:
                start = question.find(word) if word in question else context.find(word)
                if start != -1:
                    val_str = question[start + len(word):].strip().split()[0] if word in question else context[start + len(word):].strip().split()[0]
                    N_val = float(val_str)
            except:
                pass

    # 提取 Δy（像素尺寸）
    for word in ['pixel size', 'pixel pitch', 'pixel spacing', 'pixel dimension']:
        if word in question or word in context:
            try:
                start = question.find(word) if word in question else context.find(word)
                if start != -1:
                    val_str = question[start + len(word):].strip().split()[0] if word in question else context[start + len(word):].strip().split()[0]
                    delta_y_val = float(val_str)
            except:
                pass

    # 提取 f（焦距）
    for word in ['f=', 'f =', 'focal length', 'focal distance']:
        if word in question or word in context:
            try:
                start = question.find(word) if word in question else context.find(word)
                if start != -1:
                    val_str = question[start + len(word):].strip().split()[0] if word in question else context[start + len(word):].strip().split()[0]
                    f_val = float(val_str)
            except:
                pass

    # 检查是否所有必要参数都已提取
    if m_val is None or N_val is None or delta_y_val is None or f_val is None:
        return {
            "result": "inconclusive",
            "message": "参数缺失，无法计算分辨率",
            "evidence": ""
        }

    # 计算光栅本征分辨率：Δλ1 = λ / (m * N)
    # 但 λ 未提供，无法计算，只能检查公式结构
    # 由于 λ 未知，无法进行数值比较，只能判断是否满足公式形式
    # 但规则要求比较两个分辨率，而 Δλ 依赖 λ，无法计算
    # 因此，若无 λ，无法验证

    # 检查是否在预测中提及瑞利判据或像素限制
    if 'rayleigh' in prediction or 'resolving power' in prediction or 'pixel limit' in prediction or 'detector resolution' in prediction:
        return {
            "result": "pass",
            "message": "符合光栅分辨率双重约束检查要求",
            "evidence": "预测中提及瑞利判据或像素限制"
        }

    return {
        "result": "inconclusive",
        "message": "未在预测中体现双重分辨率比较",
        "evidence": ""
    }

# rule_id=exp_3b1411c4c61735fe | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_exp_3b1411c4c61735fe_f957f3aa00c6(sample: dict) -> dict:
    text = ""
    for key in ["question", "prediction", "answer", "context"]:
        if key in sample and isinstance(sample[key], str):
            text += sample[key] + " "
    text = text.lower()
    if not text.strip():
        return {"result": "inconclusive", "message": "无有效文本输入", "evidence": ""}

    # 查找可能的表达式：|n m lambda| 或 |n*m*lambda| 或 |n m * lambda|

    pattern = r"\|[^|]*?n[^|]*?m[^|]*?lambda[^|]*?\|"
    matches = re.findall(pattern, text)
    if not matches:
        return {"result": "inconclusive", "message": "未发现相关表达式", "evidence": ""}

    # 检查是否包含 |n m lambda| 或类似形式
    found = False
    for expr in matches:
        expr_clean = expr.replace("|", "").strip()
        if any(s in expr_clean for s in ["n m lambda", "n*m*lambda", "n m*lambda", "n* m* lambda"]):
            found = True
            break
    if not found:
        return {"result": "inconclusive", "message": "未发现符合模式的表达式", "evidence": ""}

    # 检查是否隐含 |n m lambda| <= 1
    inequality_pattern = r"\|[^|]*?n[^|]*?m[^|]*?lambda[^|]*?\|\s*<=\s*1"
    if re.search(inequality_pattern, text):
        return {"result": "pass", "message": "满足 |nm*lambda| <= 1 的物理限制", "evidence": re.search(inequality_pattern, text).group()}

    # 检查是否在表达式中出现反三角函数（如 arcsin, sin^-1）且参数为 nm*lambda
    trig_patterns = [r"arcsin\s*\(\s*[^)]*?n[^)]*?m[^)]*?lambda[^)]*?\s*\)", r"sin\^-1\s*\(\s*[^)]*?n[^)]*?m[^)]*?lambda[^)]*?\s*\)"]
    for pat in trig_patterns:
        if re.search(pat, text):
            # 检查是否在反三角函数中出现 nm*lambda
            if re.search(r"n[^\w]*?m[^\w]*?lambda", text):
                return {"result": "pass", "message": "反三角函数参数隐含 |nm*lambda| <= 1 的物理限制", "evidence": re.search(pat, text).group()}

    return {"result": "fail", "message": "未发现 |nm*lambda| <= 1 的物理限制或相关表达式", "evidence": ""}

# rule_id=exp_59980d6c38a82b97 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_exp_59980d6c38a82b97_5f132524dfb6(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否提及缝密度 n
    if 'slit density' not in question and 'n' not in question and 'per unit length' not in question:
        return {'result': 'inconclusive', 'message': '未提及缝密度', 'evidence': ''}

    # 查找 n 的定义或使用
    n_pattern = r'(n|slit density)[^.]*?([0-9]+\.?[0-9]*)[^.]*?(?:per|per unit length|per mm|per cm|per m)'
    n_match = None
    for line in [question, prediction, context]:
        if 'n' in line and any(keyword in line for keyword in ['slit density', 'per unit length', 'per mm', 'per cm', 'per m']):
            n_match = line
            break

    if not n_match:
        return {'result': 'inconclusive', 'message': '未找到 n 的定义', 'evidence': ''}

    # 检查是否使用 d = n
    if 'd = n' in prediction or 'd = ' in prediction and 'n' in prediction and '1/n' not in prediction:
        return {'result': 'fail', 'message': '错误地将 d 设为 n，应为 d = 1/n', 'evidence': prediction}

    # 检查是否正确使用 d = 1/n
    if 'd = 1/n' in prediction or 'd = 1/' in prediction and 'n' in prediction and '1/n' in prediction:
        return {'result': 'pass', 'message': '正确使用 d = 1/n', 'evidence': prediction}

    # 检查衍射方程中是否正确代换
    if 'd * sin' in prediction or 'd sin' in prediction:
        if '1/n' in prediction and 'n' in prediction:
            return {'result': 'pass', 'message': '衍射方程中正确代换 d = 1/n', 'evidence': prediction}
        elif 'n' in prediction and '1/n' not in prediction:
            return {'result': 'fail', 'message': '衍射方程中 d 未正确代换为 1/n', 'evidence': prediction}

    return {'result': 'inconclusive', 'message': '无法确认代换是否正确', 'evidence': ''}

# rule_id=exp_9aa17e0204da292d | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_exp_9aa17e0204da292d_70190fc63d28(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()
    text = question + ' ' + prediction + ' ' + context

    # 检查是否涉及光谱投影到探测器
    if 'spectral' not in text and 'detector' not in text and 'ccd' not in text:
        return {'result': 'inconclusive', 'message': '未提及探测器或光谱投影', 'evidence': ''}

    # 检查是否包含角色散公式或其等价形式
    canonical = 'delta_y = f * (m / (d * cos_theta)) * delta_lambda'
    # 检查预测中是否出现关键符号和结构
    required = ['delta_y', 'f', 'm', 'd', 'delta_lambda', 'cos', 'theta']
    found = 0
    for sym in required:
        if sym in text or sym.replace('_', '') in text:
            found += 1

    if found < 5:
        return {'result': 'fail', 'message': '缺少关键符号或公式结构', 'evidence': ''}

    # 检查公式结构是否匹配：Δy = f * (m / (d * cosθ)) * Δλ
    # 使用简单字符串匹配，避免复杂解析
    pattern = r'delta_y|delta_y|\Delta y|\delta y|\Delta\lambda|\delta\lambda|f|d|cos|theta|m'
    matches = len([m for m in re.findall(pattern, text, re.IGNORECASE)])
    if matches < 6:
        return {'result': 'inconclusive', 'message': '符号匹配不足', 'evidence': ''}

    # 检查是否有乘法和除法结构
    if 'f * (m / (d * cos' not in text and 'f * (m / (d * cos' not in text:
        return {'result': 'inconclusive', 'message': '公式结构不匹配', 'evidence': ''}

    # 检查是否包含 Δλ
    if 'delta_lambda' not in text and 'delta\lambda' not in text and 'delta_l' not in text:
        return {'result': 'fail', 'message': '未包含波长差项 Δλ', 'evidence': ''}

    # 检查是否包含 f * (m / (d * cosθ)) * Δλ 结构
    if 'f * (m / (d * cos' in text and ')) * delta_lambda' in text:
        return {'result': 'pass', 'message': '符合角色散与空间位移转换公式', 'evidence': 'f * (m / (d * cosθ)) * Δλ'}

    return {'result': 'inconclusive', 'message': '公式结构不完整或未明确表达', 'evidence': ''}

# rule_id=exp_a33c80df05012cad | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_exp_a33c80df05012cad_629a28176ff8(sample: dict) -> dict:
    text = (sample.get('prediction', '') + ' ' + sample.get('context', '')).lower()
    if not text.strip():
        return {'result': 'inconclusive', 'message': '无有效文本', 'evidence': ''}

    # 检查是否出现 π 且在位置公式中
    has_pi = 'pi' in text or 'π' in text
    if not has_pi:
        return {'result': 'pass', 'message': '未发现π，符合预期', 'evidence': ''}

    # 检查是否在 x = nλL/d 类型公式中出现π
    # 优先匹配标准形式
    standard_pattern = r'x\s*=\s*n\s*\*\s*λ\s*\*\s*L\s*/\s*d|\b(n\s*λ\s*L\s*/\s*d)\b'
    if any(keyword in text for keyword in ['x = nλL/d', 'x = (n * λ * L) / d', 'x = nλL/d']):
        # 若标准公式出现，且π也出现，可能出错
        if 'pi' in text or 'π' in text:
            return {'result': 'fail', 'message': '位置公式中不应含π', 'evidence': 'π出现在位置表达式中'}

    # 检查是否在相位项中出现π（如 2π/λ）
    phase_pattern = r'2\s*\*\s*\bpi\b\s*/\s*λ|2π/λ'
    if any(p in text for p in ['2pi/λ', '2π/λ', '2 * pi / λ']):
        # 若相位中出现π，但最终位置公式中无π，可能正确
        return {'result': 'pass', 'message': 'π出现在相位定义中，符合预期', 'evidence': '2π/λ'}

    # 若π出现但不在相位或标准公式中，不确定
    return {'result': 'inconclusive', 'message': 'π出现位置不明确', 'evidence': ''}

# rule_id=exp_c9f384b3fa9a907c | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_exp_c9f384b3fa9a907c_6f0ec3ac5977(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()

    # 检查是否涉及斜入射光栅（存在偏角 φ）
    if not any(keyword in question for keyword in ['slanted', 'oblique', 'inclined', 'angle', 'φ', 'phi', '偏角']):
        return {'result': 'inconclusive', 'message': '未检测到斜入射条件', 'evidence': ''}

    # 检查预测中是否使用了正确的投影分量公式
    # 正确形式应包含 sqrt(sin^2α - sin^2φ) 或类似表达式
    correct_pattern = r'sqrt\?\(sin\^2\s*\w+\s*[-+]\s*sin\^2\s*φ\)'

    # 检查是否出现错误的简化形式：d * cos(φ) 或类似
    incorrect_pattern = r'd\s*\*\s*cos\s*\(\s*φ\s*\)|d\s*\*\s*\w*\s*φ\s*\*\s*\w*'

    # 检查预测或上下文是否包含正确投影项
    has_correct = any(phrase in prediction or phrase in context for phrase in ['sqrt(sin^2', 'sqrt(sin²', 'sqrt(sin**2', 'sqrt(sin²'])

    # 检查是否出现错误的全量 cosφ 项
    has_incorrect = any(phrase in prediction or phrase in context for phrase in ['d * cos(φ)', 'd*cos(φ)', 'd * cos φ', 'd*cos φ', 'd cos φ', 'd cos(φ)', 'd * phi', 'd * φ'])

    # 若有正确项但无错误项，视为通过
    if has_correct and not has_incorrect:
        return {'result': 'pass', 'message': '正确使用了投影分量计算', 'evidence': '检测到 sqrt(sin^2α - sin^2φ) 等正确项'}

    # 若有错误项，视为失败
    if has_incorrect:
        return {'result': 'fail', 'message': '错误地使用了全量 cosφ 而非投影分量', 'evidence': '检测到 d * cos(φ) 等错误项'}

    # 否则无法判断
    return {'result': 'inconclusive', 'message': '未发现明确公式表达', 'evidence': ''}

# rule_id=exp_d19f2555b56bc4d3 | domain=Optics | topic=Diffraction (Single Slit, Double Slit, Gratings)
def check_exp_d19f2555b56bc4d3_26125b404c26(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    answer = sample.get('answer', '').lower()
    context = sample.get('context', '').lower()

    text = question + ' ' + prediction + ' ' + answer + ' ' + context

    # 检查是否涉及 N 缝衍射/干涉
    if 'n-slit' not in text and 'n缝' not in text and '多缝' not in text and 'grating' not in text:
        return {'result': 'inconclusive', 'message': '未涉及多缝干涉', 'evidence': ''}

    # 检查主极大条件：d*sinθ = nλ
    major_maxima_pattern = r'd\*sin\*\s*θ\s*=\s*n\s*λ|d\s*\*\s*sin\s*θ\s*=\s*n\s*λ|d sin θ = n λ'
    if not any([major_maxima_pattern in text, 'd sin θ = n λ' in text, 'd*sinθ=nλ' in text]):
        return {'result': 'fail', 'message': '主极大条件不满足 d*sinθ = nλ', 'evidence': ''}

    # 检查相邻极小条件：d*sinθ = (n + 1/N)λ
    minor_minima_pattern = r'd\*sin\*\s*θ\s*=\s*\(n\s*\+\s*1\s*/\s*N\)\s*λ|d\s*\*\s*sin\s*θ\s*=\s*\(n\s*\+\s*1/N\)\s*λ'
    if not any([minor_minima_pattern in text, '(n + 1/N)λ' in text, 'd sin θ = (n + 1/N)λ' in text]):
        return {'result': 'fail', 'message': '极小条件不满足 d*sinθ = (n + 1/N)λ', 'evidence': ''}

    # 检查是否包含 N, d, λ
    required_symbols = ['n', 'n', 'd', 'λ', 'lambda', 'n', '1/n', '1/N']
    found_symbols = [s for s in required_symbols if s in text]
    if len(found_symbols) < 3:
        return {'result': 'inconclusive', 'message': '未充分识别符号 N, d, λ', 'evidence': ''}

    return {'result': 'pass', 'message': '主极大与极小判据校验通过', 'evidence': 'd*sinθ = nλ and d*sinθ = (n + 1/N)λ'}

# rule_id=exp_439e690918319a6c | domain=Optics | topic=Polarization of Light
