# rule_id=exp_bf5d8e0b23cf4f8e | domain=Modern Physics | topic=Special Relativity (Time Dilation, Length Contraction)
def check_exp_bf5d8e0b23cf4f8e_6bd0a85b4a25(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    context = sample.get('context', '')
    text = (question + ' ' + prediction + ' ' + context).lower()

    # 提取关键符号 a, P, M

    a_match = re.search(r'a\s*=\s*([\d\.]+)', text)
    P_match = re.search(r'p\s*=\s*([\d\.]+)', text)
    M_match = re.search(r'm\s*=\s*([\d\.]+)', text)

    if not a_match or not P_match or not M_match:
        return {
            "result": "inconclusive",
            "message": "未找到必要参数 a, P, M",
            "evidence": ""
        }

    try:
        a_val = float(a_match.group(1))
        P_val = float(P_match.group(1))
        M_val = float(M_match.group(1))

        # 计算 P_min = M² / (2 * a * P²)
        # 注意：原式中 P 是动量 p，此处 P_val 为 p
        numerator = M_val ** 2
        denominator = 2 * a_val * (P_val ** 2)
        P_min = numerator / denominator

        # 检查 P 是否接近 P_min
        # 由于是压强 P_min，但输入中 P 是动量，需注意符号混淆
        # 规则中 P_min = M² / (2a p²)，即 P_min 与 M² 成正比
        # 但输入中 P 是动量 p，因此不能直接比较
        # 仅检查公式结构是否匹配：aP ≈ M² / (2p²)
        left = a_val * P_val
        right = M_val ** 2 / (2 * (P_val ** 2))

        # 允许一定误差
        if abs(left - right) / (right + 1e-10) < 0.1:  # 10% 误差内
            return {
                "result": "pass",
                "message": "aP ≈ M²/(2p²) 成立，压强与质量平方成正比",
                "evidence": "aP ≈ M²/(2p²)"
            }
        else:
            return {
                "result": "fail",
                "message": "aP ≈ M²/(2p²) 不成立，比例关系不一致",
                "evidence": "aP ≈ M²/(2p²)"
            }

    except Exception:
        return {
            "result": "inconclusive",
            "message": "数值解析失败",
            "evidence": ""
        }

