# rule_id=exp_858ddc24e01d3d96 | domain=Modern Physics | topic=Atomic Models (Bohr, Quantum Mechanical)
def check_exp_858ddc24e01d3d96_7d248137828e(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()
    answer = sample.get('answer', '').lower()

    # 检查是否涉及不同质量或Z值
    if 'muon' not in question and 'z=' not in question and 'z =' not in question and 'mass' not in question:
        return {'result': 'inconclusive', 'message': '未触发规则条件', 'evidence': ''}

    # 提取关键符号：m_x, Z, r, E
    # 从 prediction 或 context 中提取数值

    m_x_match = re.search(r'm_x\s*=\s*([\d.]+)', prediction + ' ' + context)
    Z_match = re.search(r'z\s*=\s*([\d.]+)', prediction + ' ' + context)
    r_match = re.search(r'r\s*=\s*([\d.]+)', prediction + ' ' + context)
    E_match = re.search(r'e\s*=\s*([\d.]+)', prediction + ' ' + context)

    if not m_x_match or not Z_match or not r_match or not E_match:
        return {'result': 'inconclusive', 'message': '缺少必要符号值', 'evidence': ''}

    try:
        m_x = float(m_x_match.group(1))
        Z = float(Z_match.group(1))
        r = float(r_match.group(1))
        E = float(E_match.group(1))
    except:
        return {'result': 'inconclusive', 'message': '数值解析失败', 'evidence': ''}

    # 原始参考值：m_e = 1（相对值），r0, E0 为标准类氢原子值
    # 按比例缩放：r' = r * (m_e/m_x) * (1/Z), E' = E * (m_x/m_e) * Z^2
    # 由于 m_e = 1，简化为：r' = r * (1/m_x) * (1/Z), E' = E * m_x * Z^2

    # 检查半径：r ∝ 1/(mZ) → r * m_x * Z 应为常数（相对值）
    r_check = r * m_x * Z
    # 检查能量：E ∝ mZ^2 → E / (m_x * Z^2) 应为常数
    E_check = E / (m_x * Z * Z)

    # 保守判断：若 r_check 和 E_check 与典型值（如1）接近，视为通过
    # 由于无绝对参考，仅判断比例关系是否一致
    # 若 m_x 和 Z 明显不为1，且 r 和 E 未按比例缩放，则失败

    # 假设标准类氢原子 m_e=1, Z=1, r=1, E=1
    # 则 r' 应为 1/(m_x * Z)，E' 应为 m_x * Z^2
    expected_r = 1 / (m_x * Z)
    expected_E = m_x * Z * Z

    # 允许一定误差（10%）
    tolerance = 0.1

    r_pass = abs(r - expected_r) / (expected_r + 1e-10) <= tolerance
    E_pass = abs(E - expected_E) / (expected_E + 1e-10) <= tolerance

    if r_pass and E_pass:
        return {'result': 'pass', 'message': '比例关系正确', 'evidence': f'r={r}, E={E}, m_x={m_x}, Z={Z}'}
    elif not r_pass and not E_pass:
        return {'result': 'fail', 'message': '半径和能量均不符合比例缩放', 'evidence': f'r={r}, E={E}, m_x={m_x}, Z={Z}'}
    else:
        return {'result': 'inconclusive', 'message': '部分比例关系正确', 'evidence': f'r={r}, E={E}, m_x={m_x}, Z={Z}'}

