# rule_id=exp_6e5c5e14f25e237b | domain=Modern Physics | topic=Wave-Particle Duality and de Broglie Wavelength
def check_exp_6e5c5e14f25e237b_c57350e32f2d(sample: dict) -> dict:
    question = sample.get('question', '')
    prediction = sample.get('prediction', '')
    context = sample.get('context', '')
    text = (question + ' ' + prediction + ' ' + context).lower()

    # 检查是否包含关键符号
    if not any(sym in text for sym in ['e', 'epsilon_0', 'h', 'm_p']):
        return {'result': 'inconclusive', 'message': '未发现关键符号', 'evidence': ''}

    # 提取 e, epsilon_0, h 的幂次
    def extract_power(expr, symbol):

        pattern = re.compile(r'([+-]?)\s*(' + re.escape(symbol) + r')\s*([*\^])?\s*([0-9]+|[+-]?[0-9]*\.?[0-9]+)')
        match = pattern.search(expr)
        if match:
            sign = match.group(1) or '+'
            power_str = match.group(4)
            try:
                power = float(power_str)
                if sign == '-':
                    power = -power
                return power
            except:
                pass
        return None

    # 简单提取表达式中的幂次（仅匹配 e, epsilon_0, h）
    e_power = extract_power(text, 'e')
    epsilon0_power = extract_power(text, 'epsilon_0')
    h_power = extract_power(text, 'h')

    # 若任一缺失，返回 inconclusive
    if e_power is None or epsilon0_power is None or h_power is None:
        return {'result': 'inconclusive', 'message': '未明确提取所有符号幂次', 'evidence': ''}

    # 检查 e^4, epsilon_0^-2, h^-2
    expected_e = 4.0
    expected_epsilon0 = -2.0
    expected_h = -2.0

    # 允许 ±0.5 的误差
    if abs(e_power - expected_e) > 0.5:
        return {'result': 'fail', 'message': 'e 的幂次不为 4', 'evidence': 'e^' + str(e_power)}
    if abs(epsilon0_power - expected_epsilon0) > 0.5:
        return {'result': 'fail', 'message': 'epsilon_0 的幂次不为 -2', 'evidence': 'epsilon_0^' + str(epsilon0_power)}
    if abs(h_power - expected_h) > 0.5:
        return {'result': 'fail', 'message': 'h 的幂次不为 -2', 'evidence': 'h^' + str(h_power)}

    # 检查 pi 的幂次是否与面积/立体角一致（常见为 pi^1 或 pi^2）
    pi_count = text.count('pi')
    if pi_count == 0:
        return {'result': 'inconclusive', 'message': '未发现 pi', 'evidence': ''}

    # 若有 pi，检查是否为 1 或 2 次
    # 通过查找 pi 的幂次表达式
    pi_power = None
    pi_pattern = re.compile(r'pi\s*([*\^])?\s*([0-9]+|[+-]?[0-9]*\.?[0-9]+)')
    pi_match = pi_pattern.search(text)
    if pi_match:
        power_str = pi_match.group(2)
        try:
            pi_power = float(power_str)
        except:
            pass

    if pi_power is None:
        # 若无显式幂次，假设为 1
        pi_power = 1.0

    if pi_power not in [1.0, 2.0]:
        return {'result': 'fail', 'message': 'pi 的幂次应为 1 或 2', 'evidence': 'pi^' + str(pi_power)}

    return {'result': 'pass', 'message': '所有幂次符合精细结构常数量级要求', 'evidence': ''}

