    if not has_V:
        return {'result': 'inconclusive', 'message': '未提供体积信息', 'evidence': ''}

    # 检查是否使用 d ≈ n^(-1/3) 或等价形式
    # 检查是否出现 d = (V / (M/m_p))^(1/3)
    pattern = r'd\s*=\s*\(\s*V\s*/\s*\(\s*M\s*/\s*m_p\s*\)\s*\)\s*\^\s*\(\s*1/3\s*\)'
    if not any(pattern in pred for pred in [prediction, context]):
        return {'result': 'fail', 'message': '未使用 d = (V / (M/m_p))^(1/3) 关系', 'evidence': ''}

    # 检查是否使用了正确的幂律形式
    # 检查是否出现 d ~ n^(-1/3)，其中 n = N/V = M/(m_p * V)
    n_expr = r'n\s*=\s*M\s*/\s*\(\s*m_p\s*\*\s*V\s*\)'
