    context = sample.get('context', '')

    evidence = ''
    result = 'inconclusive'
    message = ''

    # 提取波长 λ（单位：米）
    lambda_val = None
    for s in [question, prediction, answer, context]:
        if s:
            # 查找类似 '0.01nm' 或 '1e-11m' 的模式

            matches = re.findall(r'(\d*\.?\d+)[\s]*([a-zA-Z]+)', s)
            for val, unit in matches:
                try:
                    num = float(val)
                    if unit.lower() == 'nm':
                        lambda_val = num * 1e-9
                    elif unit.lower() == 'm':
                        lambda_val = num
                    elif unit.lower() == 'pm':
                        lambda_val = num * 1e-12
                    elif unit.lower() == 'angstrom' or unit.lower() == 'å':
                        lambda_val = num * 1e-10
                    if lambda_val and lambda_val > 0:
                        break
                except:
                    continue
            if lambda_val:
                break

    if not lambda_val:
        message = '未找到波长信息'
        return {'result': 'inconclusive', 'message': message, 'evidence': ''}

    # 判断是否接近 0.01nm 数量级（即 1e-11m）
    threshold = 1e-11
    need_relativistic = abs(lambda_val - threshold) < 1e-12 or lambda_val < 1e-11 * 10

    # 常数定义（单位：SI）
    h = 6.62607015e-34  # J·s
    m_e = 9.1093837e-31  # kg（电子质量）
    e = 1.602176634e-19  # C

    # 计算非相对论动能 K = h² / (2mλ²)
    try:
        K = h * h / (2 * m_e * lambda_val * lambda_val)
        V = K / e  # 电压 V = K / e
    except:
        message = '计算中出现数值错误'
        return {'result': 'inconclusive', 'message': message, 'evidence': ''}

    # 检查预测或答案中是否包含 V 或 K 的表达式
    found = False
    for s in [prediction, answer, context]:
        if s:
            # 检查是否包含 V = h² / (2meλ²) 或等价形式
            # 简化匹配：检查是否包含 h^2 / (2 * m * e * lambda^2)
            if 'h^2' in s and '2 * m' in s and 'e' in s and 'lambda' in s:
                found = True
                break
            # 检查数值是否接近

            num_matches = re.findall(r'[-+]?\d*\.?\d+([eE][-+]?\d+)?', s)
            for num_str in num_matches:
                try:
                    num = float(num_str)
                    # 检查是否接近 V 或 K
                    if abs(num - V) < 1e-10 or abs(num - K) < 1e-10:
                        found = True
                        break
                except:
                    continue
            if found:
                break

    if not found:
        message = '未发现符合公式或数值的表达式'
        return {'result': 'fail', 'message': message, 'evidence': ''}

    # 若波长接近 0.01nm，需提示相对论修正
    if need_relativistic:
        message = '波长接近 0.01nm，建议使用相对论修正'
        result = 'inconclusive'
    else:
        message = '符合非相对论动能与波长转换关系'
        result = 'pass'

    return {'result': result, 'message': message, 'evidence': evidence}

