# rule_id=exp_2da0dd39e69e64ca | domain=Modern Physics | topic=Cosmology and General Relativity (Basics)
def check_exp_2da0dd39e69e64ca_41b32fdf40ed(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()
    text = question + ' ' + prediction + ' ' + context

    # 检查是否提及宇宙平坦度或密度参数演化
    if 'flatness' not in text and 'density parameter' not in text and 'omega' not in text:
        return {'result': 'inconclusive', 'message': '未提及平坦度或密度参数', 'evidence': ''}

    # 检查是否提及 a(t) ∝ t^p
    if 'a(t) \propto t^p' not in text and 'a(t) ~ t^p' not in text and 'a(t) proportional to t^p' not in text:
        return {'result': 'inconclusive', 'message': '未建立 a(t) ∝ t^p 关系', 'evidence': ''}

    # 检查是否提及 (Omega-1) ∝ t^{2(1-p)}
    target_pattern = '(omega-1) \propto t\^{2\(1-p\)}'
    if target_pattern not in text and '(omega-1) ~ t^{2(1-p)}' not in text and '(omega-1) proportional to t^{2(1-p)}' not in text:
        return {'result': 'fail', 'message': '未正确建立 (Omega-1) 与 t^{2(1-p)} 的正比关系', 'evidence': ''}

    # 检查 p 值是否合理：辐射主导 p=1/2，物质主导 p=2/3
    p_values = []
    for word in text.split():
        if word.replace('.', '').isdigit() and '/' in word:
            try:
                num, den = map(int, word.split('/'))
                p = num / den
                if p in [0.5, 2/3]:
                    p_values.append(p)
            except:
                continue

    if not p_values:
        return {'result': 'inconclusive', 'message': '未指定 p 值', 'evidence': ''}

    # 检查幂次是否为 2(1-p)
    found_correct_power = False
    for word in text.split():
        if word.startswith('t^') or word.startswith('t^{'):
            power_str = word[2:].strip('{}')
            try:
                power = float(power_str)
                for p in p_values:
                    expected = 2 * (1 - p)
                    if abs(power - expected) < 1e-5:
                        found_correct_power = True
                        break
                if found_correct_power:
                    break
            except:
                continue

    if not found_correct_power:
        return {'result': 'fail', 'message': '幂次不匹配 2(1-p)', 'evidence': ''}

    return {'result': 'pass', 'message': '正确建立 (Omega-1) ∝ t^{2(1-p)} 关系', 'evidence': ''}

