# rule_id=exp_4e13c140f0a2611d | domain=Modern Physics | topic=Cosmology and General Relativity (Basics)
def check_exp_4e13c140f0a2611d_9463e59cdc61(sample: dict) -> dict:
    question = sample.get('question', '').lower()
    prediction = sample.get('prediction', '').lower()
    context = sample.get('context', '').lower()
    text = question + ' ' + prediction + ' ' + context

    # 关键词匹配
    if 'radiation' not in text and 'photon' not in text and 'energy density' not in text and 'scale factor' not in text:
        return {'result': 'inconclusive', 'message': '未提及辐射或尺度因子相关描述', 'evidence': ''}

    # 检查是否提及 a^-4 或等价形式
    patterns = [
        r'rho.*\s*proportional.*a\s*\^\s*-4',
        r'rho.*\s*\propto.*a\s*\^\s*-4',
        r'rho.*\s*\sim.*a\s*\^\s*-4',
        r'a\s*\^\s*-4.*rho',
        r'rho.*\s*=.*a\s*\^\s*-4',
        r'rho.*\s*\propto.*\left(\frac{a_0}{a}\right)\s*\^\s*4',
        r'rho.*\s*=.*\left(\frac{a_0}{a}\right)\s*\^\s*4',
        r'rho.*\s*\propto.*a_0\s*\^\s*4.*a\s*\^\s*-4',
        r'rho.*\s*\propto.*a\s*\^\s*-4',
        r'energy density.*\s*\propto.*a\s*\^\s*-4',
        r'rho.*\s*\propto.*a\s*\^-4'
    ]

    for pattern in patterns:

        if re.search(pattern, text, re.IGNORECASE):
            return {'result': 'pass', 'message': '能量密度与 a^-4 成正比，符合辐射演化规律', 'evidence': re.search(pattern, text, re.IGNORECASE).group()}

    # 检查是否提及 a^-3 和 a^-1 的组合解释
    if re.search(r'a\s*\^\s*-3.*and.*a\s*\^\s*-1', text, re.IGNORECASE) or \
       re.search(r'volume.*dilution.*and.*redshift', text, re.IGNORECASE) or \
       re.search(r'number density.*dilution.*and.*energy loss.*due.*redshift', text, re.IGNORECASE):
        return {'result': 'pass', 'message': '正确解释了 a^-3 与 a^-1 的物理来源', 'evidence': 'a^-3 and a^-1'}

    # 检查是否错误地使用 a^-3
    if re.search(r'rho.*\s*\propto.*a\s*\^\s*-3', text, re.IGNORECASE) and not re.search(r'but.*due.*redshift', text, re.IGNORECASE):
        return {'result': 'fail', 'message': '错误地认为能量密度仅随 a^-3 变化，忽略了红移能量损失', 'evidence': 'rho ∝ a^-3'}

    # 检查是否提及 a^-2 或其他错误幂次
    if re.search(r'rho.*\s*\propto.*a\s*\^\s*-2', text, re.IGNORECASE) or \
       re.search(r'rho.*\s*\propto.*a\s*\^\s*-1', text, re.IGNORECASE):
        return {'result': 'fail', 'message': '能量密度幂次错误，应为 a^-4', 'evidence': re.search(r'rho.*\s*\propto.*a\s*\^\s*-[12]', text, re.IGNORECASE).group()}

    return {'result': 'inconclusive', 'message': '未明确提及能量密度与尺度因子的幂次关系', 'evidence': ''}

